import { err, ok, Result } from "../../../shared-kernel";
import { ConversationError, Thread, ThreadId } from "../../domain";
import { ConversationApplicationError } from "../errors";
import {
  OpenCircleThread,
  OpenCircleThreadCommand,
} from "../ports/in/open-circle-thread.port";
import { CircleRoster } from "../ports/out/circle-roster";
import { ThreadIdGenerator } from "../ports/out/id-generators";
import { ThreadRepository } from "../ports/out/thread.repository";

export interface OpenCircleThreadDeps {
  readonly threads: ThreadRepository;
  readonly threadIds: ThreadIdGenerator;
  readonly roster: CircleRoster;
}

// Transaction script: ensure exactly one thread per circle. The roster gates first — an unknown
// circle and an actor outside it are the same CircleNotFound — then an existing thread is
// returned unchanged (idempotent), else a fresh one is seeded from the roster's members and
// joinedAt. Opening records no event, so there is nothing to publish here.
export const makeOpenCircleThread =
  (deps: OpenCircleThreadDeps): OpenCircleThread =>
  async (
    cmd: OpenCircleThreadCommand,
  ): Promise<
    Result<ThreadId, ConversationError | ConversationApplicationError>
  > => {
    const members = await deps.roster.membersOf(cmd.circleId);
    if (!members?.some((m) => m.memberId === cmd.actorId)) {
      return err(ConversationApplicationError.circleNotFound(cmd.circleId));
    }

    const existing = await deps.threads.findByCircle(cmd.circleId);
    if (existing) return ok(existing.id);

    const opened = Thread.openForCircle(
      deps.threadIds.next(),
      cmd.circleId,
      members,
    );
    if (opened.isErr) return err(opened.error);

    await deps.threads.save(opened.value);
    return ok(opened.value.id);
  };

import { err, ok, Result } from "../../../shared-kernel";
import { ConversationError, Thread, ThreadId } from "../../domain";
import { ConversationApplicationError } from "../errors";
import {
  OpenDmThread,
  OpenDmThreadCommand,
} from "../ports/in/open-dm-thread.port";
import { ConnectionPolicy } from "../ports/out/connection-policy";
import { ThreadIdGenerator } from "../ports/out/id-generators";
import { ThreadRepository } from "../ports/out/thread.repository";

export interface OpenDmThreadDeps {
  readonly threads: ThreadRepository;
  readonly threadIds: ThreadIdGenerator;
  readonly connections: ConnectionPolicy;
}

// Transaction script: ensure exactly one DM thread per member pair. The pair rule (self-DM) is
// the aggregate's own invariant and fails before any I/O; the connection gate is the
// ConnectionPolicy's answer; the pair-uniqueness rule is the order-insensitive repository lookup.
// Opening records no event, so there is nothing to publish here.
export const makeOpenDmThread =
  (deps: OpenDmThreadDeps): OpenDmThread =>
  async (
    cmd: OpenDmThreadCommand,
  ): Promise<
    Result<ThreadId, ConversationError | ConversationApplicationError>
  > => {
    const opened = Thread.openDm(deps.threadIds.next(), [
      cmd.initiatorId,
      cmd.recipientId,
    ]);
    if (opened.isErr) return err(opened.error); // self-DM: fail before any I/O

    if (
      !(await deps.connections.canMessage(cmd.initiatorId, cmd.recipientId))
    ) {
      return err(ConversationApplicationError.notConnected());
    }

    const existing = await deps.threads.findDmByParticipants(
      cmd.initiatorId,
      cmd.recipientId,
    );
    if (existing) return ok(existing.id);

    await deps.threads.save(opened.value);
    return ok(opened.value.id);
  };

import { ok, Result } from "../../../shared-kernel";
import { Thread, ThreadId } from "../../domain";
import { OpenThread, OpenThreadCommand } from "../ports/in/open-thread.port";
import { ThreadIdGenerator } from "../ports/out/id-generators";
import { ThreadRepository } from "../ports/out/thread.repository";

export interface OpenThreadDeps {
  readonly threads: ThreadRepository;
  readonly threadIds: ThreadIdGenerator;
}

// Transaction script: ensure exactly one Thread per exchange. If a thread already exists for the
// exchange, return its id unchanged (idempotent); otherwise open a fresh one with the supplied
// participants and persist it. Opening records no event, so there is nothing to publish here.
export const makeOpenThread =
  (deps: OpenThreadDeps): OpenThread =>
  async (cmd: OpenThreadCommand): Promise<Result<ThreadId, never>> => {
    const existing = await deps.threads.findByExchange(cmd.exchangeId);
    if (existing) return ok(existing.id);

    const thread = Thread.openForExchange(
      deps.threadIds.next(),
      cmd.exchangeId,
      cmd.participants,
    );
    await deps.threads.save(thread);
    return ok(thread.id);
  };

