import { DomainEvent, err, ok, Result } from "../../shared-kernel";
import { ExchangeError } from "./errors";
import {
  DisputeRaised,
  ExchangeAccepted,
  ExchangeCancelled,
  ExchangeCompleted,
  ExchangeProposed,
  ExchangeRejected,
  OwnershipTransferred,
  PossessionTransferred,
} from "./events";
import { ExchangeKind } from "./exchange-kind";
import { ExchangeStatus } from "./exchange-status";
import { CopyId, ExchangeId, MemberId } from "./ids";
import {
  ExchangeTerms,
  ExchangeTermsInput,
  Money,
  validateTerms,
} from "./terms";

// Legal status moves. The aggregate's single source of truth for the state machine;
// any move not listed here is an IllegalTransition. (proposal §1.4)
const ALLOWED_TRANSITIONS: Readonly<
  Record<ExchangeStatus, readonly ExchangeStatus[]>
> = {
  proposed: ["accepted", "rejected", "cancelled"],
  accepted: ["completed", "cancelled", "disputed"],
  completed: ["disputed"], // a problem can surface after settlement
  rejected: [],
  cancelled: [],
  disputed: [],
};

// What made the initiator eligible to ask, recorded at propose time: "direct" when a route through
// the owner (public profile, household, mutual follow) allowed it, "circle" when only their own
// Exchange/Admin circle seats did. Rows proposed before it was recorded have none.
export type EligibleVia = "direct" | "circle";

// Input to propose(): the requested copy plus kind-tagged (still-unvalidated) terms.
export interface ProposeProps {
  readonly id: ExchangeId;
  readonly initiator: MemberId;
  readonly recipient: MemberId;
  readonly requestedCopyId: CopyId;
  readonly terms: ExchangeTermsInput;
  readonly eligibleVia?: EligibleVia;
  // Swap only: who owned the offered copy when it was offered (the initiator, or the housemate whose
  // copy they co-manage). Ignored for any other kind.
  readonly offeredCopyOwnerId?: MemberId;
  readonly now: Date;
}

// The persistable shape, kept deliberately close to the `exchanges` table columns so the
// 1b mapper is a trivial field-for-field translation (with kind <-> legacy-type renaming).
export interface ExchangeState {
  readonly id: ExchangeId;
  readonly initiatorId: MemberId;
  readonly recipientId: MemberId;
  readonly kind: ExchangeKind;
  readonly requestedCopyId: CopyId;
  readonly offeredCopyId?: CopyId; // swap only
  // Swap only: the offered copy's owner at propose time; accept and confirm refuse once the copy has
  // another owner (settlement-guard), and its OwnershipTransferred names them as the expected
  // previous owner. Absent on swaps proposed before it was recorded.
  readonly offeredCopyOwnerId?: MemberId;
  readonly price?: Money; // sale only
  readonly returnDate?: Date; // lend only
  readonly status: ExchangeStatus;
  readonly initiatorConfirmationTimestamp?: Date;
  readonly recipientConfirmationTimestamp?: Date;
  readonly eligibleVia?: EligibleVia;
  readonly createdAt: Date;
  readonly updatedAt: Date;
}

export class Exchange {
  private events: DomainEvent[] = [];

  private constructor(private state: ExchangeState) {}

  get id(): ExchangeId {
    return this.state.id;
  }

  get status(): ExchangeStatus {
    return this.state.status;
  }

  get kind(): ExchangeKind {
    return this.state.kind;
  }

  // Create a brand-new proposal. Decides only from its own data: rejects self-exchange
  // and invalid kind-specific terms. Availability/dedup checks need repositories and live
  // in the application layer (1b), not here.
  static propose(props: ProposeProps): Result<Exchange, ExchangeError> {
    if (props.initiator === props.recipient) {
      return err(ExchangeError.selfExchange());
    }

    const terms = validateTerms(props.terms, props.now);
    if (terms.isErr) return err(terms.error);

    const state = Exchange.stateFromTerms(props, terms.value);
    const exchange = new Exchange(state);
    exchange.record(
      new ExchangeProposed(
        state.id,
        state.kind,
        state.initiatorId,
        state.recipientId,
        props.now,
      ),
    );
    return ok(exchange);
  }

  // Recipient agrees to the proposal.
  accept(by: MemberId, now: Date): Result<void, ExchangeError> {
    return this.guarded(
      "accepted",
      () => this.requireParty(by, "recipient", "accept"),
      now,
      () => {
        this.record(new ExchangeAccepted(this.id, now));
      },
    );
  }

  // Recipient declines the proposal.
  decline(by: MemberId, now: Date): Result<void, ExchangeError> {
    return this.guarded(
      "rejected",
      () => this.requireParty(by, "recipient", "decline"),
      now,
      () => {
        this.record(new ExchangeRejected(this.id, now));
      },
    );
  }

  // Call a deal off. The initiator may withdraw a proposed or an accepted deal. Once accepted, the
  // recipient may call it off too: accepting sets their copy aside for this one deal (accept-exchange),
  // so they need a way out when the other side goes quiet or the deal can't settle any more. A
  // proposal the recipient doesn't want is declined, not cancelled.
  cancel(by: MemberId, now: Date): Result<void, ExchangeError> {
    return this.guarded(
      "cancelled",
      () =>
        this.status === "accepted" && this.partyOf(by)
          ? ok(undefined)
          : this.requireParty(by, "initiator", "cancel"),
      now,
      () => {
        this.record(new ExchangeCancelled(this.id, by, now));
      },
    );
  }

  // Dual confirmation: record the acting party's timestamp; only settle to `completed`
  // once BOTH parties have confirmed. A lone confirmation does not transition status.
  confirmCompletion(by: MemberId, now: Date): Result<void, ExchangeError> {
    if (this.status !== "accepted") {
      return err(ExchangeError.illegalTransition(this.status, "completed"));
    }
    const party = this.partyOf(by);
    if (!party) return err(ExchangeError.wrongParty("confirm completion"));

    this.state = {
      ...this.state,
      ...(party === "initiator"
        ? { initiatorConfirmationTimestamp: now }
        : { recipientConfirmationTimestamp: now }),
      updatedAt: now,
    };

    if (!this.bothConfirmed()) return ok(undefined);
    return this.settle(now);
  }

  // Either party flags a problem (from accepted or after completion).
  raiseDispute(by: MemberId, now: Date): Result<void, ExchangeError> {
    if (!this.partyOf(by))
      return err(ExchangeError.wrongParty("raise a dispute"));
    return this.guarded(
      "disputed",
      () => ok(undefined),
      now,
      () => {
        this.record(new DisputeRaised(this.id, by, now));
      },
    );
  }

  // Drain recorded events for the publisher; clears the buffer so a save can't double-emit.
  pullEvents(): readonly DomainEvent[] {
    const drained = this.events;
    this.events = [];
    return drained;
  }

  // Map to/from persistence without the aggregate knowing about any storage technology.
  static rehydrate(state: ExchangeState): Exchange {
    return new Exchange(state);
  }

  toState(): ExchangeState {
    return this.state;
  }

  // --- internals ---

  // Shared guard for the simple transitions: authorise, check the move is legal, mutate
  // status, then let the caller record its event. Illegal moves return an error, never no-op.
  private guarded(
    to: ExchangeStatus,
    authorise: () => Result<void, ExchangeError>,
    now: Date,
    onTransition: () => void,
  ): Result<void, ExchangeError> {
    const auth = authorise();
    if (auth.isErr) return auth;
    const moved = this.transition(to, now);
    if (moved.isErr) return moved;
    onTransition();
    return ok(undefined);
  }

  // The ONLY place status changes. Rejects any move not in ALLOWED_TRANSITIONS.
  private transition(
    to: ExchangeStatus,
    now: Date,
  ): Result<void, ExchangeError> {
    if (!ALLOWED_TRANSITIONS[this.state.status].includes(to)) {
      return err(ExchangeError.illegalTransition(this.state.status, to));
    }
    this.state = { ...this.state, status: to, updatedAt: now };
    return ok(undefined);
  }

  // Settlement: complete, then hand over the requested copy. A swap/sale moves OWNERSHIP; a lend
  // moves only POSSESSION (the borrower holds it open-endedly, the owner keeps ownership). For a
  // swap the offered copy's ownership also moves to the recipient. Each move names the owner the
  // deal was made with (the recipient; the recorded owner of the offered copy), so Library never
  // moves or lends a copy away from anyone else. (Cross-aggregate "a copy is set aside for at most
  // one accepted exchange that could still settle" is an APPLICATION-layer rule, checked on accept
  // by accept-exchange, not enforced here.)
  private settle(now: Date): Result<void, ExchangeError> {
    const moved = this.transition("completed", now);
    if (moved.isErr) return moved;
    this.record(new ExchangeCompleted(this.id, now));
    if (this.state.kind === "lend") {
      this.record(
        new PossessionTransferred(
          this.id,
          this.state.requestedCopyId,
          this.state.initiatorId,
          this.state.returnDate,
          this.state.recipientId,
          now,
        ),
      );
    } else {
      this.record(
        new OwnershipTransferred(
          this.id,
          this.state.requestedCopyId,
          this.state.initiatorId,
          this.state.recipientId,
          now,
        ),
      );
    }
    if (this.state.kind === "swap" && this.state.offeredCopyId) {
      this.record(
        new OwnershipTransferred(
          this.id,
          this.state.offeredCopyId,
          this.state.recipientId,
          this.state.offeredCopyOwnerId,
          now,
        ),
      );
    }
    return ok(undefined);
  }

  private bothConfirmed(): boolean {
    return (
      this.state.initiatorConfirmationTimestamp !== undefined &&
      this.state.recipientConfirmationTimestamp !== undefined
    );
  }

  private partyOf(member: MemberId): "initiator" | "recipient" | null {
    if (member === this.state.initiatorId) return "initiator";
    if (member === this.state.recipientId) return "recipient";
    return null;
  }

  private requireParty(
    member: MemberId,
    expected: "initiator" | "recipient",
    action: string,
  ): Result<void, ExchangeError> {
    const required =
      expected === "initiator"
        ? this.state.initiatorId
        : this.state.recipientId;
    return member === required
      ? ok(undefined)
      : err(ExchangeError.wrongParty(action));
  }

  private record(event: DomainEvent): void {
    this.events.push(event);
  }

  private static stateFromTerms(
    props: ProposeProps,
    terms: ExchangeTerms,
  ): ExchangeState {
    const base: Omit<
      ExchangeState,
      "kind" | "offeredCopyId" | "offeredCopyOwnerId" | "price" | "returnDate"
    > = {
      id: props.id,
      initiatorId: props.initiator,
      recipientId: props.recipient,
      requestedCopyId: props.requestedCopyId,
      status: "proposed",
      ...(props.eligibleVia ? { eligibleVia: props.eligibleVia } : {}),
      createdAt: props.now,
      updatedAt: props.now,
    };
    switch (terms.kind) {
      case "swap":
        return {
          ...base,
          kind: "swap",
          offeredCopyId: terms.offeredCopyId,
          ...(props.offeredCopyOwnerId
            ? { offeredCopyOwnerId: props.offeredCopyOwnerId }
            : {}),
        };
      case "sale":
        return { ...base, kind: "sale", price: terms.price };
      case "lend":
        return { ...base, kind: "lend", returnDate: terms.returnDate };
    }
  }
}

src/exchange/domain/terms.ts.source:
import { err, ok, Result } from "../../shared-kernel";
import { ExchangeError } from "./errors";
import { CopyId } from "./ids";

// The highest price a sale can carry: a million in the major unit. Far above any puzzle; it only
// keeps nonsense (1e300 is an integer too) off the other party's screen.
export const MAX_MONEY_CENTS = 100_000_000;

// How far a return date may lie: from yesterday (a member's today can be behind UTC's) to ten years.
const RETURN_DATE_PAST_MS = 24 * 60 * 60 * 1000;
const RETURN_DATE_AHEAD_MS = 10 * 365 * 24 * 60 * 60 * 1000;

const isPossibleReturnDate = (date: Date, now: Date): boolean => {
  const at = date.getTime();
  return (
    at >= now.getTime() - RETURN_DATE_PAST_MS &&
    at <= now.getTime() + RETURN_DATE_AHEAD_MS
  );
};

// Money as positive integer minor units (cents) plus an ISO-4217 currency, avoiding
// floating-point money bugs. Immutable value object validated at construction.
export class Money {
  private constructor(
    readonly amountCents: number,
    readonly currency: string,
  ) {}

  static create(
    amountCents: number,
    currency: string,
  ): Result<Money, ExchangeError> {
    if (!Number.isInteger(amountCents) || amountCents <= 0) {
      return err(
        ExchangeError.missingTerms(
          "sale",
          "price must be a positive integer (cents)",
        ),
      );
    }
    if (amountCents > MAX_MONEY_CENTS) {
      return err(ExchangeError.missingTerms("sale", "the price is too high"));
    }
    if (currency.length !== 3) {
      return err(
        ExchangeError.missingTerms(
          "sale",
          "currency must be a 3-letter ISO code",
        ),
      );
    }
    return ok(new Money(amountCents, currency.toUpperCase()));
  }

  // Rehydrate a persisted value that was already validated when first stored.
  static fromState(amountCents: number, currency: string): Money {
    return new Money(amountCents, currency);
  }
}

// Discriminated terms: exactly the data each kind requires, nothing more. The aggregate
// trusts a constructed ExchangeTerms to already be valid for its kind.
export type ExchangeTerms =
  | { readonly kind: "swap"; readonly offeredCopyId: CopyId }
  | { readonly kind: "sale"; readonly price: Money }
  | { readonly kind: "lend"; readonly returnDate?: Date };

// Raw, kind-tagged input as it arrives from the boundary; validated into ExchangeTerms.
export type ExchangeTermsInput =
  | { readonly kind: "swap"; readonly offeredCopyId?: CopyId }
  | { readonly kind: "sale"; readonly price?: Money }
  | { readonly kind: "lend"; readonly returnDate?: Date };

// Enforce term validity per kind: swap needs an offered copy, sale a price. A lend is open-ended —
// returnDate is an optional, advisory expected-return, never required, but when given it has to be
// a date the loan can end on.
export const validateTerms = (
  input: ExchangeTermsInput,
  now: Date,
): Result<ExchangeTerms, ExchangeError> => {
  switch (input.kind) {
    case "swap":
      if (!input.offeredCopyId) {
        return err(
          ExchangeError.missingTerms("swap", "an offered copy is required"),
        );
      }
      return ok({ kind: "swap", offeredCopyId: input.offeredCopyId });
    case "sale":
      if (!input.price) {
        return err(ExchangeError.missingTerms("sale", "a price is required"));
      }
      return ok({ kind: "sale", price: input.price });
    case "lend":
      if (input.returnDate && !isPossibleReturnDate(input.returnDate, now)) {
        return err(
          ExchangeError.missingTerms("lend", "the return date isn't possible"),
        );
      }
      return ok({ kind: "lend", returnDate: input.returnDate });
  }
};

