import { DomainEvent, err, ok, Result } from "../../shared-kernel";
import { HouseholdError } from "./errors";
import {
  HouseholdInviteAccepted,
  HouseholdInviteDeclined,
  HouseholdInviteSent,
} from "./events";
import { HouseholdId, HouseholdInviteId, MemberId } from "./ids";

// An invite lapses this long after it was sent (like a request to join); lapsing is read from
// createdAt, never stored, so existing invites need no new field. A lapsed invite reads as missing.
export const HOUSEHOLD_INVITE_TTL_MS = 14 * 24 * 60 * 60 * 1000;

export type HouseholdInviteStatus = "pending" | "accepted" | "declined";

export interface HouseholdInviteState {
  readonly id: HouseholdInviteId;
  readonly householdId: HouseholdId;
  readonly inviterId: MemberId;
  readonly inviteeId: MemberId;
  readonly status: HouseholdInviteStatus;
  readonly createdAt: Date;
  readonly respondedAt?: Date;
}

// An invitation to join a household: pending → accepted | declined, answered only by the invitee.
// Joining (admitting into the Household) and the at-most-one-household rule are orchestrated by the
// application layer on accept, which also refuses a lapsed invite (isExpired).
export class HouseholdInvite {
  private events: DomainEvent[] = [];

  private constructor(private state: HouseholdInviteState) {}

  get id(): HouseholdInviteId {
    return this.state.id;
  }

  get householdId(): HouseholdId {
    return this.state.householdId;
  }

  get inviterId(): MemberId {
    return this.state.inviterId;
  }

  get inviteeId(): MemberId {
    return this.state.inviteeId;
  }

  get status(): HouseholdInviteStatus {
    return this.state.status;
  }

  static send(props: {
    readonly id: HouseholdInviteId;
    readonly householdId: HouseholdId;
    readonly inviterId: MemberId;
    readonly inviteeId: MemberId;
    readonly now: Date;
  }): Result<HouseholdInvite, HouseholdError> {
    if (props.inviterId === props.inviteeId) {
      return err(HouseholdError.selfInvite());
    }
    const invite = new HouseholdInvite({
      id: props.id,
      householdId: props.householdId,
      inviterId: props.inviterId,
      inviteeId: props.inviteeId,
      status: "pending",
      createdAt: props.now,
    });
    invite.record(
      new HouseholdInviteSent(
        props.id,
        props.householdId,
        props.inviterId,
        props.inviteeId,
        props.now,
      ),
    );
    return ok(invite);
  }

  isExpired(now: Date): boolean {
    return (
      now.getTime() >= this.state.createdAt.getTime() + HOUSEHOLD_INVITE_TTL_MS
    );
  }

  accept(by: MemberId, now: Date): Result<void, HouseholdError> {
    const guard = this.guardResponse(by);
    if (guard.isErr) return guard;
    this.state = { ...this.state, status: "accepted", respondedAt: now };
    this.record(
      new HouseholdInviteAccepted(
        this.state.id,
        this.state.householdId,
        this.state.inviterId,
        this.state.inviteeId,
        now,
      ),
    );
    return ok(undefined);
  }

  decline(by: MemberId, now: Date): Result<void, HouseholdError> {
    const guard = this.guardResponse(by);
    if (guard.isErr) return guard;
    this.state = { ...this.state, status: "declined", respondedAt: now };
    this.record(
      new HouseholdInviteDeclined(
        this.state.id,
        this.state.householdId,
        this.state.inviterId,
        this.state.inviteeId,
        now,
      ),
    );
    return ok(undefined);
  }

  pullEvents(): readonly DomainEvent[] {
    const drained = this.events;
    this.events = [];
    return drained;
  }

  static rehydrate(state: HouseholdInviteState): HouseholdInvite {
    return new HouseholdInvite(state);
  }

  toState(): HouseholdInviteState {
    return this.state;
  }

  private guardResponse(by: MemberId): Result<void, HouseholdError> {
    if (by !== this.state.inviteeId) return err(HouseholdError.notInvitee());
    if (this.state.status !== "pending") {
      return err(HouseholdError.inviteNotPending());
    }
    return ok(undefined);
  }

  private record(event: DomainEvent): void {
    this.events.push(event);
  }
}

src/household/domain/household.ts.source:
import {
  DomainEvent,
  err,
  hasVisibleCharacter,
  normaliseDisplayName,
  ok,
  Result,
} from "../../shared-kernel";
import {
  resolveHouseholdCopyPermission,
  type HouseholdCopyPermission,
} from "./copy-access";
import { HouseholdError } from "./errors";
import {
  HouseholdDissolved,
  HouseholdFounded,
  HouseholdMemberJoined,
  HouseholdMemberLeft,
  HouseholdMemberRemoved,
} from "./events";
import { HouseholdId, MemberId } from "./ids";

export type HouseholdRole = "admin" | "member";

// The longest a household's name may be, counted after normalising (same rule as circle names).
export const MAX_HOUSEHOLD_NAME_LENGTH = 100;

export interface HouseholdMember {
  readonly memberId: MemberId;
  readonly role: HouseholdRole;
  readonly joinedAt: Date;
}

// What leaving does to the household, as the leave-and-join confirmation names it: the last member
// deletes it; an admin with housemates and no other admin hands it over (the longest-standing
// member is promoted); anyone else just leaves.
export type HouseholdLeaveConsequence = "deleted" | "handover" | "leave";

export const householdLeaveConsequence = (
  members: readonly Pick<HouseholdMember, "memberId" | "role">[],
  memberId: MemberId,
): HouseholdLeaveConsequence => {
  const others = members.filter((m) => m.memberId !== memberId);
  if (others.length === 0) return "deleted";
  const isAdmin = members.some(
    (m) => m.memberId === memberId && m.role === "admin",
  );
  return isAdmin && !others.some((m) => m.role === "admin")
    ? "handover"
    : "leave";
};

export interface HouseholdState {
  readonly id: HouseholdId;
  readonly members: readonly HouseholdMember[];
  readonly createdAt: Date;
  // The permission a member's copy grants the household when the copy has no explicit value.
  // Absent = the global default (manage), so existing households need no backfill.
  readonly defaultCopyPermission?: HouseholdCopyPermission;
  // The members' own name for the household; absent = unnamed. Only members ever see it.
  readonly name?: string;
}

// Household: the members who pool their libraries. The founder is the admin (invites + removes);
// when the admin leaves, the longest-standing remaining member is promoted; when the last member
// leaves the household is dissolved. "At most one household per member" spans aggregates and is
// enforced by the application layer.
export class Household {
  private events: DomainEvent[] = [];

  private constructor(private state: HouseholdState) {}

  get id(): HouseholdId {
    return this.state.id;
  }

  get members(): readonly HouseholdMember[] {
    return this.state.members;
  }

  isMember(memberId: MemberId): boolean {
    return this.state.members.some((m) => m.memberId === memberId);
  }

  isAdmin(memberId: MemberId): boolean {
    return this.state.members.some(
      (m) => m.memberId === memberId && m.role === "admin",
    );
  }

  leaveConsequenceFor(memberId: MemberId): HouseholdLeaveConsequence {
    return householdLeaveConsequence(this.state.members, memberId);
  }

  static found(props: {
    readonly id: HouseholdId;
    readonly founderId: MemberId;
    readonly now: Date;
  }): Household {
    const household = new Household({
      id: props.id,
      members: [
        { memberId: props.founderId, role: "admin", joinedAt: props.now },
      ],
      createdAt: props.now,
    });
    household.record(
      new HouseholdFounded(props.id, props.founderId, props.now),
    );
    return household;
  }

  admit(memberId: MemberId, now: Date): Result<void, HouseholdError> {
    if (this.isMember(memberId)) return err(HouseholdError.alreadyMember());
    this.state = {
      ...this.state,
      members: [
        ...this.state.members,
        { memberId, role: "member", joinedAt: now },
      ],
    };
    this.record(new HouseholdMemberJoined(this.state.id, memberId, now));
    return ok(undefined);
  }

  leave(
    memberId: MemberId,
    now: Date,
  ): Result<{ readonly dissolved: boolean }, HouseholdError> {
    if (!this.isMember(memberId)) return err(HouseholdError.notAMember());
    this.drop(memberId);
    this.record(new HouseholdMemberLeft(this.state.id, memberId, now));
    if (this.state.members.length === 0) {
      this.record(new HouseholdDissolved(this.state.id, now));
      return ok({ dissolved: true });
    }
    return ok({ dissolved: false });
  }

  remove(
    by: MemberId,
    target: MemberId,
    now: Date,
  ): Result<void, HouseholdError> {
    if (!this.isAdmin(by)) return err(HouseholdError.notHouseholdAdmin());
    if (by === target) return err(HouseholdError.cannotRemoveSelf());
    if (!this.isMember(target)) return err(HouseholdError.notAMember());
    this.drop(target);
    this.record(new HouseholdMemberRemoved(this.state.id, target, by, now));
    return ok(undefined);
  }

  // The admin sets the household-wide default for copies without an explicit permission. It
  // applies at read time to every such copy; no event (no notifications by decision).
  setDefaultCopyPermission(
    by: MemberId,
    permission: HouseholdCopyPermission,
  ): Result<{ readonly changed: boolean }, HouseholdError> {
    if (!this.isAdmin(by)) return err(HouseholdError.notHouseholdAdmin());
    const changed =
      resolveHouseholdCopyPermission(
        undefined,
        this.state.defaultCopyPermission,
      ) !== permission;
    this.state = { ...this.state, defaultCopyPermission: permission };
    return ok({ changed });
  }

  // The admin names the household (like its other settings), or clears the name with null. The
  // name is normalised and must then show a visible character and be at most
  // MAX_HOUSEHOLD_NAME_LENGTH long. No event: nobody is notified.
  rename(by: MemberId, raw: string | null): Result<void, HouseholdError> {
    if (!this.isAdmin(by)) return err(HouseholdError.notHouseholdAdmin());
    if (raw === null) {
      const { name: _cleared, ...rest } = this.state;
      this.state = rest;
      return ok(undefined);
    }
    const name = normaliseDisplayName(raw);
    if (!hasVisibleCharacter(name) || name.length > MAX_HOUSEHOLD_NAME_LENGTH) {
      return err(HouseholdError.invalidHouseholdName());
    }
    this.state = { ...this.state, name };
    return ok(undefined);
  }

  pullEvents(): readonly DomainEvent[] {
    const drained = this.events;
    this.events = [];
    return drained;
  }

  static rehydrate(state: HouseholdState): Household {
    return new Household(state);
  }

  toState(): HouseholdState {
    return this.state;
  }

  // Remove a member; if that leaves remaining members but no admin, promote the longest-standing.
  private drop(memberId: MemberId): void {
    const remaining = this.state.members.filter((m) => m.memberId !== memberId);
    const hasAdmin = remaining.some((m) => m.role === "admin");
    let members = remaining;
    if (!hasAdmin && remaining.length > 0) {
      const senior = remaining.reduce((a, b) =>
        b.joinedAt.getTime() < a.joinedAt.getTime() ? b : a,
      );
      members = remaining.map((m) =>
        m.memberId === senior.memberId ? { ...m, role: "admin" } : m,
      );
    }
    this.state = { ...this.state, members };
  }

  private record(event: DomainEvent): void {
    this.events.push(event);
  }
}

