import { err, ok, Result } from "../../shared-kernel";
import { IdentityError } from "./errors";

// The elevated roles a Member may hold beyond a plain account. The literal union IS the value
// object: an ordinary member holds none of these. Mirrors StarRating's "create validates the
// primitive" style without needing a wrapper class for a closed string set.
export const ROLES = ["admin", "moderator"] as const;

export type Role = (typeof ROLES)[number];

// Validate an untrusted string (e.g. from a Clerk claim or an admin command) into a Role.
export const createRole = (value: string): Result<Role, IdentityError> => {
  if ((ROLES as readonly string[]).includes(value)) {
    return ok(value as Role);
  }
  return err(IdentityError.invalidRole(value));
};

export const isRole = (value: string): value is Role =>
  (ROLES as readonly string[]).includes(value);

src/identity/domain/username.ts.source:
import { err, ok, Result } from "../../shared-kernel";
import { IdentityError } from "./errors";

// 3-30 chars of letters, digits, underscore, or hyphen — matches the public handle conventions
// we expose, narrow enough to keep URLs/mentions unambiguous.
const USERNAME_PATTERN = /^[A-Za-z0-9_-]{3,30}$/;

// An optional public handle as an immutable value object. Constructed only via `create`, which
// validates length and charset; the membership stores it verbatim (case-preserving).
export class Username {
  private constructor(readonly value: string) {}

  static create(value: string): Result<Username, IdentityError> {
    if (!USERNAME_PATTERN.test(value)) {
      return err(IdentityError.invalidUsername(value));
    }
    return ok(new Username(value));
  }
}

src/insights/collection-breakdown.ts.source:
// Distributions over the member's owned copies, shaped for chart components: every distribution is
// a `{ label, value }[]`. Pure and total — empty input yields empty arrays.
//
// Labels are data (a bucket range, a brand, a difficulty enum), never display words: "no value"
// and "the long tail" are the sentinels below, which the client translates.

export interface CopyBreakdownInput {
  // Piece count of the puzzle (from the copy's catalog snapshot); buckets group these.
  readonly pieceCount?: number;
  readonly brand?: string;
  readonly difficulty?: string;
  readonly condition?: string;
}

export interface DistributionEntry {
  readonly label: string;
  readonly value: number;
}

export interface CollectionBreakdown {
  readonly byPieceCount: DistributionEntry[];
  readonly byBrand: DistributionEntry[];
  readonly byDifficulty: DistributionEntry[];
  readonly byCondition: DistributionEntry[];
}

// Piece-count buckets, ordered low→high. Each carries only its exclusive upper bound: a count lands
// in the first bucket it falls below, so the lower edge is implied by the previous bucket and every
// boundary is single-sourced (e.g. 300 appears once). The final Infinity bound catches 2000+.
const PIECE_BUCKETS: ReadonlyArray<{ label: string; below: number }> = [
  { label: "< 100", below: 100 },
  { label: "100-299", below: 300 },
  { label: "300-499", below: 500 },
  { label: "500-999", below: 1000 },
  { label: "1000-1999", below: 2000 },
  { label: "2000+", below: Number.POSITIVE_INFINITY },
];

// Bucket for copies without a value (no piece count, brand, difficulty or condition). Always listed
// last, after every real value and after OTHER_BUCKET. Part of the insights wire contract: the web
// (components/insights/collection-breakdown.tsx) mirrors both strings and translates them.
export const UNKNOWN_BUCKET = "__unknown";
// The brands beyond the top N, summed into one entry.
export const OTHER_BUCKET = "__other";

// The trailing unknown bucket, or nothing when every copy has a value.
const unknownEntry = (count: number): DistributionEntry[] =>
  count > 0 ? [{ label: UNKNOWN_BUCKET, value: count }] : [];

// Bucket each copy's piece count into the ordered ranges; copies with no piece count fall in the
// unknown bucket. Only non-empty buckets are returned, preserving the natural ascending order.
const pieceCountDistribution = (
  copies: readonly CopyBreakdownInput[],
): DistributionEntry[] => {
  const counts = new Map<string, number>();
  for (const copy of copies) {
    const n = copy.pieceCount;
    const label =
      typeof n === "number" && Number.isFinite(n)
        ? (PIECE_BUCKETS.find((b) => n < b.below)?.label ?? UNKNOWN_BUCKET)
        : UNKNOWN_BUCKET;
    counts.set(label, (counts.get(label) ?? 0) + 1);
  }
  // Emit buckets in their declared order, then a trailing unknown bucket if present.
  const ordered: DistributionEntry[] = [];
  for (const b of PIECE_BUCKETS) {
    const value = counts.get(b.label);
    if (value) ordered.push({ label: b.label, value });
  }
  return [...ordered, ...unknownEntry(counts.get(UNKNOWN_BUCKET) ?? 0)];
};

// Count a string-valued facet. Real values are sorted by value desc, then label asc for stable,
// deterministic output; missing/blank values are counted apart so callers can list them last.
const countFacet = (
  copies: readonly CopyBreakdownInput[],
  pick: (copy: CopyBreakdownInput) => string | undefined,
): { known: DistributionEntry[]; unknown: number } => {
  const counts = new Map<string, number>();
  let unknown = 0;
  for (const copy of copies) {
    const raw = pick(copy);
    if (raw && raw.trim().length > 0) {
      counts.set(raw, (counts.get(raw) ?? 0) + 1);
    } else {
      unknown += 1;
    }
  }
  const known = sortEntries(
    [...counts.entries()].map(([label, value]) => ({ label, value })),
  );
  return { known, unknown };
};

// A facet's real values, then the unknown bucket last however large it is.
const facetDistribution = (
  copies: readonly CopyBreakdownInput[],
  pick: (copy: CopyBreakdownInput) => string | undefined,
): DistributionEntry[] => {
  const { known, unknown } = countFacet(copies, pick);
  return [...known, ...unknownEntry(unknown)];
};

const sortEntries = (entries: DistributionEntry[]): DistributionEntry[] =>
  [...entries].sort(
    (a, b) => b.value - a.value || a.label.localeCompare(b.label),
  );

// Like a facet distribution but collapse the long tail: keep the top `topN` real brands and sum the
// rest into a single OTHER_BUCKET entry, then the unknown bucket last. Copies without a brand never
// compete for a top-N slot. With <= topN distinct brands no OTHER_BUCKET appears.
const brandDistribution = (
  copies: readonly CopyBreakdownInput[],
  topN: number,
): DistributionEntry[] => {
  const { known, unknown } = countFacet(copies, (c) => c.brand);
  const top = known.slice(0, topN);
  const otherValue = known
    .slice(topN)
    .reduce((acc, entry) => acc + entry.value, 0);
  const other =
    otherValue > 0 ? [{ label: OTHER_BUCKET, value: otherValue }] : [];
  return [...top, ...other, ...unknownEntry(unknown)];
};

// The "Top brands" chart shows six brands; the rest fold into OTHER_BUCKET here, so the chart can
// render the series as is instead of re-ranking or cutting it.
const DEFAULT_BRAND_TOP_N = 6;

// Compute all four distributions for the collection charts. `topN` caps the brand chart's series.
export const computeCollectionBreakdown = (
  copies: readonly CopyBreakdownInput[],
  topN: number = DEFAULT_BRAND_TOP_N,
): CollectionBreakdown => ({
  byPieceCount: pieceCountDistribution(copies),
  byBrand: brandDistribution(copies, topN),
  byDifficulty: facetDistribution(copies, (c) => c.difficulty),
  byCondition: facetDistribution(copies, (c) => c.condition),
});

src/insights/completion-trends.ts.source:
// Completions grouped per calendar month for a trend chart. Pure and deterministic: the caller
// passes the completion timestamps and the "now" reference so the 12-month window is testable
// without touching the system clock.

import { DEFAULT_WINDOW_MONTHS, lastMonthKeys, monthKey } from "./month-window";

export interface CompletionTrendInput {
  // Epoch milliseconds the solve finished. Only finished solves should be passed in.
  readonly completedAt: number;
  // The time the member typed (typedSolveMinutes), never the duration stored from the dates.
  readonly completionTimeMinutes?: number;
  // Absent = "day". Year-only and undated solves have no month, so they are skipped (spec D4).
  readonly datePrecision?: "day" | "year" | "unknown";
}

export interface CompletionTrendPoint {
  // Calendar month label, "YYYY-MM" (UTC), so points sort lexicographically by chronology.
  readonly month: string;
  readonly count: number;
  readonly totalMinutes: number;
}

// Build the last `windowMonths` month buckets ending at `now` (inclusive), each pre-seeded to zero
// so a quiet month still renders as a gap in the chart rather than disappearing. Completions
// outside the window are ignored; within it they fold into their month's count + totalMinutes.
// Result is oldest→newest (the window's own order).
export const computeCompletionTrends = (
  completions: readonly CompletionTrendInput[],
  now: number = Date.now(),
  windowMonths: number = DEFAULT_WINDOW_MONTHS,
): CompletionTrendPoint[] => {
  // Seed the window so every month in range is present even with no completions.
  const buckets = new Map(
    lastMonthKeys(now, windowMonths).map((key) => [
      key,
      { count: 0, totalMinutes: 0 },
    ]),
  );

  for (const c of completions) {
    if ((c.datePrecision ?? "day") !== "day") continue;
    const key = monthKey(c.completedAt);
    const bucket = buckets.get(key);
    if (!bucket) continue; // outside the window
    bucket.count += 1;
    bucket.totalMinutes +=
      typeof c.completionTimeMinutes === "number" ? c.completionTimeMinutes : 0;
  }

  return [...buckets.entries()].map(([month, { count, totalMinutes }]) => ({
    month,
    count,
    totalMinutes,
  }));
};

src/insights/month-window.ts.source:
// The calendar-month buckets the insights charts share. Months are UTC so grouping is
// timezone-stable and deterministic; the web formats the "YYYY-MM" keys in UTC to match.

// How far back the monthly insights charts look.
export const DEFAULT_WINDOW_MONTHS = 12;

// "YYYY-MM" (UTC) for an epoch-ms instant, so keys sort lexicographically by chronology.
export const monthKey = (epochMs: number): string => {
  const d = new Date(epochMs);
  const year = d.getUTCFullYear();
  const month = `${d.getUTCMonth() + 1}`.padStart(2, "0");
  return `${year}-${month}`;
};

// The last `windowMonths` month keys ending at the month of `now` (inclusive), oldest first. A
// chart seeds every one of them to zero, so a quiet month still renders as a gap instead of
// disappearing.
export const lastMonthKeys = (now: number, windowMonths: number): string[] => {
  const nowDate = new Date(now);
  const year = nowDate.getUTCFullYear();
  const month = nowDate.getUTCMonth();
  const keys: string[] = [];
  for (let back = windowMonths - 1; back >= 0; back--) {
    // Date.UTC normalises a negative month into the previous year(s).
    keys.push(monthKey(Date.UTC(year, month - back, 1)));
  }
  return keys;
};

src/insights/personal-stats.ts.source:
// Insights is a read-side context: these are pure, total projection functions over plain input
// DTOs (no Convex imports). The Convex adapter fetches rows, maps them to these inputs, and applies
// the function. Keeping the maths here makes it deterministic and unit-testable in isolation.

// One completed solve, reduced to what the stats need.
export interface CompletionStatInput {
  // The time the member typed (typedSolveMinutes), never the duration stored from the dates: an
  // untimed solve must not add up to a solve time.
  readonly completionTimeMinutes?: number;
  readonly isCompleted: boolean;
  // Absent = "day". Every precision counts in the lifetime total; only dated solves feed the
  // time averages.
  readonly datePrecision?: "day" | "year" | "unknown";
}

// One owned copy, reduced to its catalog snapshot facets used for counting/distribution.
export interface CopyStatInput {
  // The catalog definition this copy instantiates; distinct definitions are counted from these.
  readonly puzzleDefinitionKey?: string;
}

// One exchange the member took part in, reduced to its lifecycle status.
export type ExchangeStatStatus =
  "proposed" | "accepted" | "completed" | "rejected" | "cancelled" | "disputed";

export interface ExchangeStatInput {
  readonly status: ExchangeStatStatus;
}

// One PartnerReview rating received by the member (1-5).
export interface ReceivedReviewStatInput {
  readonly rating: number;
}

// One goal, reduced to the flags the stats summarise.
export interface GoalStatInput {
  readonly isActive: boolean;
  readonly targetCompletions: number;
  readonly currentCompletions: number;
}

export interface PersonalStatsInput {
  readonly completions: readonly CompletionStatInput[];
  readonly copies: readonly CopyStatInput[];
  readonly collectionsCount: number;
  readonly exchanges: readonly ExchangeStatInput[];
  // The 1-5 ratings from the member's puzzle reviews (the two-level review model's
  // `puzzleReviews` rows), no longer attached to completions.
  readonly puzzleReviewRatings: readonly number[];
  readonly reviewsReceived: readonly ReceivedReviewStatInput[];
  readonly goals: readonly GoalStatInput[];
}

export interface PersonalStats {
  readonly completionsCount: number;
  readonly totalSolveMinutes: number;
  readonly averageSolveMinutes: number;
  readonly puzzlesOwned: number;
  readonly distinctDefinitions: number;
  readonly collectionsCount: number;
  readonly exchangesCompleted: number;
  // null when the member has no puzzle reviews (distinguishes "no reviews" from a 0 average).
  readonly averageRatingGiven: number | null;
  readonly averageRatingReceived: number;
  readonly goalsActive: number;
  readonly goalsAchieved: number;
  // Every goal the member has, archived ones included: achieved counts archived goals too, so
  // "{achieved} of {total} goals" needs this total (goalsActive can be lower than goalsAchieved).
  readonly goalsTotal: number;
}

// Mean of the present numeric values; empty input is 0 (not NaN) so the read model is total. Kept
// internal so the divide-by-zero guard lives in exactly one place.
const mean = (values: readonly number[]): number => {
  if (values.length === 0) return 0;
  const sum = values.reduce((acc, v) => acc + v, 0);
  return sum / values.length;
};

// Roll the member's rows into the personal stats card. Only *completed* solves count toward the
// completion totals and the average solve time; in-progress rows are ignored. Averages divide by
// the number of present samples, never by the total row count.
export const computePersonalStats = (
  input: PersonalStatsInput,
): PersonalStats => {
  const completed = input.completions.filter((c) => c.isCompleted);

  const solveMinutes = completed
    .filter((c) => (c.datePrecision ?? "day") === "day")
    .map((c) => c.completionTimeMinutes)
    .filter((m): m is number => typeof m === "number");
  const totalSolveMinutes = solveMinutes.reduce((acc, m) => acc + m, 0);

  const distinctDefinitions = new Set(
    input.copies
      .map((c) => c.puzzleDefinitionKey)
      .filter((k): k is string => typeof k === "string" && k.length > 0),
  ).size;

  return {
    completionsCount: completed.length,
    totalSolveMinutes,
    averageSolveMinutes: mean(solveMinutes),
    puzzlesOwned: input.copies.length,
    distinctDefinitions,
    collectionsCount: input.collectionsCount,
    exchangesCompleted: input.exchanges.filter((e) => e.status === "completed")
      .length,
    averageRatingGiven:
      input.puzzleReviewRatings.length === 0
        ? null
        : mean(input.puzzleReviewRatings),
    averageRatingReceived: mean(input.reviewsReceived.map((r) => r.rating)),
    goalsActive: input.goals.filter((g) => g.isActive).length,
    goalsAchieved: input.goals.filter(
      (g) => g.currentCompletions >= g.targetCompletions,
    ).length,
    goalsTotal: input.goals.length,
  };
};

