import { err, ok, type Result } from "../../shared-kernel";
import { LibraryError } from "./errors";
import { PuzzleDefinitionId } from "./ids";

// The most definitions one batch add may acquire (counted after deduplication). Keeps a single
// transaction's reads and writes bounded; the web picker sends a larger tray in chunks of this
// size.
export const MAX_ACQUIRE_BATCH = 25;

export interface AcquireBatchRequest {
  readonly puzzleDefinitionId: PuzzleDefinitionId;
  readonly forTrade?: boolean;
  readonly forLend?: boolean;
}

export interface AcquireBatchItem {
  readonly puzzleDefinitionId: PuzzleDefinitionId;
  readonly forTrade: boolean;
  readonly forLend: boolean;
}

// Normalise a requested batch add: duplicates collapse to their first occurrence (one copy per
// definition per batch), each item's offers default to false (the SharingSetting default),
// and an empty batch or more distinct definitions than the cap reject the whole batch.
export const planAcquireBatch = (
  requests: readonly AcquireBatchRequest[],
): Result<AcquireBatchItem[], LibraryError> => {
  const byDefinition = new Map<PuzzleDefinitionId, AcquireBatchItem>();
  for (const request of requests) {
    if (byDefinition.has(request.puzzleDefinitionId)) continue;
    byDefinition.set(request.puzzleDefinitionId, {
      puzzleDefinitionId: request.puzzleDefinitionId,
      forTrade: request.forTrade ?? false,
      forLend: request.forLend ?? false,
    });
  }
  const items = [...byDefinition.values()];
  if (items.length === 0) return err(LibraryError.emptyAcquireBatch());
  if (items.length > MAX_ACQUIRE_BATCH)
    return err(LibraryError.acquireBatchTooLarge(MAX_ACQUIRE_BATCH));
  return ok(items);
};

src/library/domain/acquisition.ts.source:
import { Price } from "./price";

// How a Copy entered the owner's library, matching the persisted `ownedPuzzles`
// acquisition columns (acquisitionDate / acquisitionSource) plus an optional paid price.
export type AcquisitionSource = "bought_new" | "bought_used" | "trade" | "gift";

const EARLIEST_ACQUISITION = Date.UTC(1900, 0, 1);
const LATEST_ACQUISITION_AHEAD_MS = 366 * 24 * 60 * 60 * 1000;

// A date a copy can have been acquired on: a real date from 1900 on, and at most a year ahead, so
// every month of the current year (all of them are in the Edit dialog's month picker) is fine. An
// impossible one must never be stored: formatting it back throws, in every client that reads it.
export const isPossibleAcquisitionDate = (date: Date, now: Date): boolean => {
  const at = date.getTime();
  return (
    at >= EARLIEST_ACQUISITION &&
    at <= now.getTime() + LATEST_ACQUISITION_AHEAD_MS
  );
};

// Value object: all fields optional because acquisition history is frequently unknown.
export class Acquisition {
  private constructor(
    readonly date?: Date,
    readonly source?: AcquisitionSource,
    readonly price?: Price,
  ) {}

  static create(
    props: {
      readonly date?: Date;
      readonly source?: AcquisitionSource;
      readonly price?: Price;
    } = {},
  ): Acquisition {
    return new Acquisition(props.date, props.source, props.price);
  }

  // The empty acquisition (everything unknown) — the default for a freshly minted Copy.
  static unknown(): Acquisition {
    return new Acquisition();
  }
}

