import {
  Clock,
  DomainEvent,
  DomainEventPublisher,
  ok,
  Result,
} from "../../../shared-kernel";
import {
  MarkAllRead,
  MarkAllReadCommand,
} from "../ports/in/mark-all-read.port";
import { NotificationRepository } from "../ports/out/notification.repository";

export interface MarkAllReadDeps {
  readonly notifications: NotificationRepository;
  readonly events: DomainEventPublisher;
  readonly clock: Clock;
}

// Bulk-mark a member's unread notifications. The repository returns the affected aggregates with
// their NotificationRead events already recorded (markAllReadForUser only touches unread ones);
// we drain and publish those events and report the count. No ownership check is needed because the
// scan is scoped to the member by construction.
export const makeMarkAllRead =
  (deps: MarkAllReadDeps): MarkAllRead =>
  async (cmd: MarkAllReadCommand): Promise<Result<number, never>> => {
    const affected = await deps.notifications.markAllReadForUser(
      cmd.memberId,
      deps.clock.now(),
    );

    const pending: DomainEvent[] = [];
    for (const notification of affected) {
      pending.push(...notification.pullEvents());
    }
    if (pending.length > 0) {
      await deps.events.publish(pending);
    }
    return ok(affected.length);
  };

import {
  Clock,
  DomainEventPublisher,
  err,
  ok,
  Result,
} from "../../../shared-kernel";
import { NotificationError } from "../../domain";
import { NotificationApplicationError } from "../errors";
import {
  MarkNotificationRead,
  MarkNotificationReadCommand,
} from "../ports/in/mark-notification-read.port";
import { NotificationRepository } from "../ports/out/notification.repository";

export interface MarkNotificationReadDeps {
  readonly notifications: NotificationRepository;
  readonly events: DomainEventPublisher;
  readonly clock: Clock;
}

// Load the notification, delegate the ownership + idempotency rules to the aggregate, then save
// and publish. A missing notification is an application error; a wrong owner is a domain error.
export const makeMarkNotificationRead =
  (deps: MarkNotificationReadDeps): MarkNotificationRead =>
  async (
    cmd: MarkNotificationReadCommand,
  ): Promise<
    Result<void, NotificationError | NotificationApplicationError>
  > => {
    const notification = await deps.notifications.findById(cmd.notificationId);
    if (!notification) {
      return err(
        NotificationApplicationError.notificationNotFound(cmd.notificationId),
      );
    }

    const marked = notification.markRead(cmd.memberId, deps.clock.now());
    if (marked.isErr) return err(marked.error);

    await deps.notifications.save(notification);
    await deps.events.publish(notification.pullEvents());
    return ok(undefined);
  };

import {
  Clock,
  DomainEvent,
  DomainEventPublisher,
  ok,
  Result,
} from "../../../shared-kernel";
import {
  Channel,
  CHANNELS,
  EMAIL_ELIGIBLE_TYPES,
  MANDATORY_IN_APP_TYPES,
  MemberId,
  Notification,
  NotificationId,
  NotificationPreference,
} from "../../domain";
import {
  NotifyMember,
  NotifyMemberCommand,
} from "../ports/in/notify-member.port";
import { NotificationDelivery } from "../ports/out/notification-delivery.port";
import { NotificationIdGenerator } from "../ports/out/notification-id-generator";
import { NotificationPreferenceIdGenerator } from "../ports/out/notification-preference-id-generator";
import { NotificationPreferenceRepository } from "../ports/out/notification-preference.repository";

export interface NotifyMemberDeps {
  readonly delivery: NotificationDelivery;
  readonly preferences: NotificationPreferenceRepository;
  readonly notificationIds: NotificationIdGenerator;
  readonly preferenceIds: NotificationPreferenceIdGenerator;
  readonly events: DomainEventPublisher;
  readonly clock: Clock;
}

// The key entry the backend subscriber calls. This is the POLICY SEAM that makes Notifications a
// pure subscriber: it loads the member's preference (or a default if none stored), then for each
// candidate channel allowed by that preference, creates and saves a Notification. If the member
// has suppressed every channel for this type, it is a legitimate no-op (ok with an empty array).
//
// Notifications never fails here — there is no upstream contract to break; an unwanted event is
// simply not materialised. Hence the `never` error channel.
export const makeNotifyMember =
  (deps: NotifyMemberDeps): NotifyMember =>
  async (
    cmd: NotifyMemberCommand,
  ): Promise<Result<readonly NotificationId[], never>> => {
    const preference = await loadPreference(deps, cmd.memberId);

    const candidates: readonly Channel[] = cmd.channels ?? CHANNELS;
    const allowed = candidates.filter(
      (channel) =>
        (channel === "inApp" && MANDATORY_IN_APP_TYPES.has(cmd.type)) ||
        ((channel !== "email" || EMAIL_ELIGIBLE_TYPES.has(cmd.type)) &&
          preference.allows(cmd.type, channel)),
    );

    const created: NotificationId[] = [];
    const pending: DomainEvent[] = [];
    const now = deps.clock.now();

    for (const channel of allowed) {
      const notification = Notification.create({
        id: deps.notificationIds.next(),
        userId: cmd.memberId,
        type: cmd.type,
        params: cmd.params,
        relatedId: cmd.relatedId,
        actorId: cmd.actorId,
        subject: cmd.subject,
        channel,
        now,
      });
      // Delivery owns the medium: in-app persists, email/push dispatch out-of-band. The use case
      // stays oblivious to which, and must NOT also persist or in-app rows would double-write.
      await deps.delivery.deliver(channel, notification);
      created.push(notification.id);
      pending.push(...notification.pullEvents());
    }

    if (pending.length > 0) {
      await deps.events.publish(pending);
    }
    return ok(created);
  };

// Load the member's stored preference, or materialise (and persist) the sensible default so a
// member who never visited their settings still receives the default in-app deliveries.
const loadPreference = async (
  deps: NotifyMemberDeps,
  memberId: MemberId,
): Promise<NotificationPreference> => {
  const existing = await deps.preferences.findByMember(memberId);
  if (existing) return existing;

  const fresh = NotificationPreference.createDefault(
    deps.preferenceIds.next(),
    memberId,
    deps.clock.now(),
  );
  await deps.preferences.save(fresh);
  return fresh;
};

import { Clock, ok, Result } from "../../../shared-kernel";
import { NotificationPreference } from "../../domain";
import {
  SetMessagePreview,
  SetMessagePreviewCommand,
} from "../ports/in/set-message-preview.port";
import { NotificationPreferenceIdGenerator } from "../ports/out/notification-preference-id-generator";
import { NotificationPreferenceRepository } from "../ports/out/notification-preference.repository";

export interface SetMessagePreviewDeps {
  readonly preferences: NotificationPreferenceRepository;
  readonly preferenceIds: NotificationPreferenceIdGenerator;
  readonly clock: Clock;
}

// Set whether email or push may quote a message's text, materialising the member's default
// preference first if none is stored. The aggregate owns the default and the no-op rule.
export const makeSetMessagePreview =
  (deps: SetMessagePreviewDeps): SetMessagePreview =>
  async (cmd: SetMessagePreviewCommand): Promise<Result<void, never>> => {
    const now = deps.clock.now();
    const preference =
      (await deps.preferences.findByMember(cmd.memberId)) ??
      NotificationPreference.createDefault(
        deps.preferenceIds.next(),
        cmd.memberId,
        now,
      );
    preference.setMessagePreview(cmd.channel, cmd.enabled, now);
    await deps.preferences.save(preference);
    return ok(undefined);
  };

import {
  Clock,
  DomainEventPublisher,
  ok,
  Result,
} from "../../../shared-kernel";
import { NotificationPreference } from "../../domain";
import {
  UpdateNotificationPreference,
  UpdateNotificationPreferenceCommand,
} from "../ports/in/update-notification-preference.port";
import { NotificationPreferenceIdGenerator } from "../ports/out/notification-preference-id-generator";
import { NotificationPreferenceRepository } from "../ports/out/notification-preference.repository";

export interface UpdateNotificationPreferenceDeps {
  readonly preferences: NotificationPreferenceRepository;
  readonly preferenceIds: NotificationPreferenceIdGenerator;
  readonly events: DomainEventPublisher;
  readonly clock: Clock;
}

// Toggle a single (type, channel) for a member, materialising the default preference first if the
// member has none stored. Delegates enablement (and the no-op-when-unchanged rule) to the
// aggregate, then saves and publishes any PreferenceChanged event.
export const makeUpdateNotificationPreference =
  (deps: UpdateNotificationPreferenceDeps): UpdateNotificationPreference =>
  async (
    cmd: UpdateNotificationPreferenceCommand,
  ): Promise<Result<void, never>> => {
    const now = deps.clock.now();
    const preference =
      (await deps.preferences.findByMember(cmd.memberId)) ??
      NotificationPreference.createDefault(
        deps.preferenceIds.next(),
        cmd.memberId,
        now,
      );

    if (cmd.enabled) {
      preference.enable(cmd.type, cmd.channel, now);
    } else {
      preference.disable(cmd.type, cmd.channel, now);
    }

    await deps.preferences.save(preference);
    await deps.events.publish(preference.pullEvents());
    return ok(undefined);
  };

import {
  Clock,
  DomainEventPublisher,
  ok,
  Result,
} from "../../../shared-kernel";
import { NotificationPreference } from "../../domain";
import {
  UpdateNotificationPreferences,
  UpdateNotificationPreferencesCommand,
} from "../ports/in/update-notification-preferences.port";
import { NotificationPreferenceIdGenerator } from "../ports/out/notification-preference-id-generator";
import { NotificationPreferenceRepository } from "../ports/out/notification-preference.repository";

export interface UpdateNotificationPreferencesDeps {
  readonly preferences: NotificationPreferenceRepository;
  readonly preferenceIds: NotificationPreferenceIdGenerator;
  readonly events: DomainEventPublisher;
  readonly clock: Clock;
}

// Toggle a batch of (type, channel) preferences for a member atomically: materialise the default
// preference first if the member has none stored, apply every update against that ONE loaded
// aggregate, then save once and publish once. This is what makes a category header click atomic
// (no partial category state if something after the first toggle were to fail).
export const makeUpdateNotificationPreferences =
  (deps: UpdateNotificationPreferencesDeps): UpdateNotificationPreferences =>
  async (
    cmd: UpdateNotificationPreferencesCommand,
  ): Promise<Result<void, never>> => {
    const now = deps.clock.now();
    const preference =
      (await deps.preferences.findByMember(cmd.memberId)) ??
      NotificationPreference.createDefault(
        deps.preferenceIds.next(),
        cmd.memberId,
        now,
      );

    for (const update of cmd.updates) {
      if (update.enabled) {
        preference.enable(update.type, update.channel, now);
      } else {
        preference.disable(update.type, update.channel, now);
      }
    }

    await deps.preferences.save(preference);
    await deps.events.publish(preference.pullEvents());
    return ok(undefined);
  };

src/notifications/domain/events.ts.source:
import { DomainEvent } from "../../shared-kernel";
import { Channel } from "./channel";
import { MemberId, NotificationId } from "./ids";
import { NotificationType } from "./notification-type";

// All Notifications domain events implement DomainEvent (name + occurredAt). They are plain
// immutable records the aggregate records; an outbound publisher serialises and dispatches them
// (e.g. a delivery adapter that actually sends the email/push for the created notification).

// A notification was created and is awaiting / has had delivery on its channel.
export class NotificationCreated implements DomainEvent {
  readonly name = "NotificationCreated";
  constructor(
    readonly notificationId: NotificationId,
    readonly userId: MemberId,
    readonly type: NotificationType,
    readonly channel: Channel,
    readonly occurredAt: Date,
  ) {}
}

// The recipient read a notification (first time only; markRead is idempotent and won't re-emit).
export class NotificationRead implements DomainEvent {
  readonly name = "NotificationRead";
  constructor(
    readonly notificationId: NotificationId,
    readonly userId: MemberId,
    readonly occurredAt: Date,
  ) {}
}

// A member changed whether a given (type, channel) is enabled.
export class PreferenceChanged implements DomainEvent {
  readonly name = "PreferenceChanged";
  constructor(
    readonly memberId: MemberId,
    readonly type: NotificationType,
    readonly channel: Channel,
    readonly enabled: boolean,
    readonly occurredAt: Date,
  ) {}
}

export type NotificationDomainEvent =
  NotificationCreated | NotificationRead | PreferenceChanged;

src/notifications/domain/notification-pr.source:
import { DomainEvent } from "../../shared-kernel";
import { Channel, CHANNELS } from "./channel";
import { PreferenceChanged } from "./events";
import { MemberId, NotificationPreferenceId } from "./ids";
import { NOTIFICATION_TYPES, NotificationType } from "./notification-type";

// The set of channels enabled for a single notification type. A missing channel means disabled.
export type ChannelToggles = Readonly<Partial<Record<Channel, boolean>>>;

// The off-app channels a message notification can quote the message's text on. In-app always shows
// it (the member is signed in), so it has no setting.
export type MessagePreviewChannel = Exclude<Channel, "inApp">;

export const MESSAGE_PREVIEW_CHANNELS: readonly MessagePreviewChannel[] = [
  "email",
  "push",
];

// Per off-app channel: may a message notification quote the message text? Absent = the default.
export type MessagePreviewToggles = Readonly<
  Partial<Record<MessagePreviewChannel, boolean>>
>;

// The defaults (SEC-64): an email leaves the text out (it sits in a third-party mailbox, often
// forwarded or read on shared screens), a push includes it (the member opted into push on their
// own device; this keeps push's existing behaviour).
const DEFAULT_MESSAGE_PREVIEWS: Readonly<
  Record<MessagePreviewChannel, boolean>
> = { email: false, push: true };

// A channel toggle map with every channel explicitly resolved -- what `defaultToggles` and
// `resolvedToggles` always produce (no absent keys to fall back on).
type ResolvedChannelToggles = Readonly<Record<Channel, boolean>>;

// The persistable shape: per (type, channel) enablement, plus the member it belongs to. We store
// only the toggles that differ from "off" is NOT assumed — we store the full resolved map so the
// 4a-backend mapper is a plain serialise; `allows` reads it directly without re-deriving defaults.
export interface NotificationPreferenceState {
  readonly id: NotificationPreferenceId;
  readonly memberId: MemberId;
  // type -> channel -> enabled. Absent (type or channel) resolves to disabled.
  readonly toggles: Readonly<Partial<Record<NotificationType, ChannelToggles>>>;
  // Whether email / push may quote a message's text. Absent (rows written before the setting, or a
  // channel never toggled) resolves to DEFAULT_MESSAGE_PREVIEWS.
  readonly messagePreviews?: MessagePreviewToggles;
  readonly updatedAt: Date;
}

// Build the sensible default toggle map: every type enabled on inApp, email and push off (push is
// opt-in for every type, circle messages included, same as direct messages). This is the policy a
// member with no stored preference gets (the application layer materialises one of these).
const defaultToggles = (): Record<NotificationType, ResolvedChannelToggles> => {
  const map = {} as Record<NotificationType, ResolvedChannelToggles>;
  for (const type of NOTIFICATION_TYPES) {
    map[type] = { inApp: true, email: false, push: false };
  }
  return map;
};

// NotificationPreference: the per-member aggregate root governing which (type, channel) deliveries
// a member accepts. NotifyMember consults `allows` per channel; this is the policy seam that keeps
// Notifications a pure subscriber.
export class NotificationPreference {
  private events: DomainEvent[] = [];

  private constructor(private state: NotificationPreferenceState) {}

  get id(): NotificationPreferenceId {
    return this.state.id;
  }

  get memberId(): MemberId {
    return this.state.memberId;
  }

  // A fresh preference set carrying the sensible defaults (all types on inApp; email/push off).
  static createDefault(
    id: NotificationPreferenceId,
    memberId: MemberId,
    now: Date,
  ): NotificationPreference {
    return new NotificationPreference({
      id,
      memberId,
      toggles: defaultToggles(),
      updatedAt: now,
    });
  }

  // Does this member accept a notification of `type` on `channel`? Falls back PER CHANNEL: absent
  // keys arise from type-level absence (untouched types, or types added after the row was written)
  // or channels added later; an explicit stored value (including false) always wins.
  allows(type: NotificationType, channel: Channel): boolean {
    return (
      this.state.toggles[type]?.[channel] ?? defaultToggles()[type][channel]
    );
  }

  // The full 21-type read model: every NOTIFICATION_TYPES member resolved to its complete
  // {inApp, email, push} triple, via the same per-channel stored-over-default merge as `allows`.
  // This is the READ-side truth the preferences UI renders; `allows` is the delivery-side
  // equivalent.
  resolvedToggles(): Readonly<Record<NotificationType, ChannelToggles>> {
    const resolved = {} as Record<NotificationType, ChannelToggles>;
    for (const type of NOTIFICATION_TYPES) {
      const triple = {} as Record<Channel, boolean>;
      for (const channel of CHANNELS) {
        triple[channel] = this.allows(type, channel);
      }
      resolved[type] = triple;
    }
    return resolved;
  }

  // May a message notification on `channel` quote the message's text? An explicit stored value
  // wins; otherwise the channel's default (email no, push yes).
  includesMessagePreview(channel: MessagePreviewChannel): boolean {
    return (
      this.state.messagePreviews?.[channel] ?? DEFAULT_MESSAGE_PREVIEWS[channel]
    );
  }

  // Both off-app channels resolved: the read side the settings UI renders.
  resolvedMessagePreviews(): Readonly<Record<MessagePreviewChannel, boolean>> {
    return {
      email: this.includesMessagePreview("email"),
      push: this.includesMessagePreview("push"),
    };
  }

  // Let `channel` quote message text, or not. A no-op when the value already matches. Records no
  // event: like PreferenceChanged, nothing downstream subscribes; delivery reads it at send time.
  setMessagePreview(
    channel: MessagePreviewChannel,
    enabled: boolean,
    now: Date,
  ): void {
    if (this.includesMessagePreview(channel) === enabled) return;
    this.state = {
      ...this.state,
      messagePreviews: { ...this.state.messagePreviews, [channel]: enabled },
      updatedAt: now,
    };
  }

  // Turn a (type, channel) delivery on. Records PreferenceChanged only when it actually changed.
  enable(type: NotificationType, channel: Channel, now: Date): void {
    this.set(type, channel, true, now);
  }

  // Turn a (type, channel) delivery off. Records PreferenceChanged only when it actually changed.
  disable(type: NotificationType, channel: Channel, now: Date): void {
    this.set(type, channel, false, now);
  }

  // Drain recorded events for the publisher; clears the buffer so a save can't double-emit.
  pullEvents(): readonly DomainEvent[] {
    const drained = this.events;
    this.events = [];
    return drained;
  }

  // Map to/from persistence without the aggregate knowing about any storage technology.
  static rehydrate(state: NotificationPreferenceState): NotificationPreference {
    return new NotificationPreference(state);
  }

  toState(): NotificationPreferenceState {
    return this.state;
  }

  // --- internals ---

  // The ONLY place toggles change. No-ops (and records nothing) if the value already matches, so a
  // redundant toggle never emits a spurious PreferenceChanged.
  private set(
    type: NotificationType,
    channel: Channel,
    enabled: boolean,
    now: Date,
  ): void {
    if (this.allows(type, channel) === enabled) {
      return;
    }
    const current = this.state.toggles[type] ?? defaultToggles()[type];
    const nextForType: ChannelToggles = { ...current, [channel]: enabled };
    this.state = {
      ...this.state,
      toggles: { ...this.state.toggles, [type]: nextForType },
      updatedAt: now,
    };
    this.record(
      new PreferenceChanged(this.state.memberId, type, channel, enabled, now),
    );
  }

  private record(event: DomainEvent): void {
    this.events.push(event);
  }
}

