// Activation (quick start spec §1.2, decisions 5 and 10): a member is activated when, within 7 days
// of sign-up (inclusive), they own ≥ 3 copies AND have at least one of: a finished solve (any date
// precision), a mutual connection, or a household link. The backend gathers the facts; the rules
// and the report aggregation live here so the thresholds are unit-tested. Timestamps are epoch ms.
//
// Household link (decision 10): the member created or joined a household inside their window, and
// that household has at least one other member, WHENEVER that member joined. So a member can flip
// to activated after day 7, when a second member joins their household later. The report therefore
// reads current household membership and is not frozen once a cohort's window has closed.

import {
  QUICK_START_COPIES_DONE,
  QUICK_START_STEP_IDS,
  type QuickStartStepId,
} from "./quickStart";

const DAY_MS = 24 * 60 * 60 * 1000;
export const ACTIVATION_WINDOW_MS = 7 * DAY_MS;
/** The secondary "engaged" signal: a finished solve within this long. Not part of activation. */
export const ENGAGED_WINDOW_MS = 14 * DAY_MS;
/** Report cohorts are weekly sign-up buckets. */
export const ACTIVATION_COHORT_MS = 7 * DAY_MS;
/** One report covers at most this much sign-up time, so a single query stays within budget. */
export const ACTIVATION_REPORT_MAX_RANGE_MS = 31 * DAY_MS;

export interface ActivationFacts {
  /** createdAt of the member's own copies. */
  copyCreatedAts: readonly number[];
  /** createdAt of the member's finished solves, at any date precision. */
  completionCreatedAts: readonly number[];
  /** Per mutual connection: when it became mutual (the later of the two follow rows). */
  mutualConnectedAts: readonly number[];
  /** The member's household membership, if any. */
  household?: { joinedAt: number; hasOtherMember: boolean };
}

export interface Activation {
  copies3: boolean;
  completion: boolean;
  mutual: boolean;
  household: boolean;
  activated: boolean;
  /** Secondary signal: a finished solve within 14 days. */
  completion14d: boolean;
}

export const evaluateActivation = (
  facts: ActivationFacts,
  signupAt: number,
): Activation => {
  const within = (windowMs: number) => (t: number) =>
    t >= signupAt && t <= signupAt + windowMs;
  const inWeek = within(ACTIVATION_WINDOW_MS);
  const copies3 =
    facts.copyCreatedAts.filter(inWeek).length >= QUICK_START_COPIES_DONE;
  const completion = facts.completionCreatedAts.some(inWeek);
  const mutual = facts.mutualConnectedAts.some(inWeek);
  const household =
    facts.household !== undefined &&
    facts.household.hasOtherMember &&
    inWeek(facts.household.joinedAt);
  return {
    copies3,
    completion,
    mutual,
    household,
    activated: copies3 && (completion || mutual || household),
    completion14d: facts.completionCreatedAts.some(within(ENGAGED_WINDOW_MS)),
  };
};

export const isActivated = (facts: ActivationFacts, signupAt: number) =>
  evaluateActivation(facts, signupAt).activated;

export const isValidActivationRange = (from: number, to: number): boolean =>
  to > from && to - from <= ACTIVATION_REPORT_MAX_RANGE_MS;

/** One cohort member as the report sees it. Quick start fields are the member's current state. */
export interface ActivationReportMember {
  signupAt: number;
  activation: ActivationFacts;
  welcomeAnswered: boolean;
  startedQuickStart: boolean;
  householdLinkCreated: boolean;
  /** The member's derived quick start steps (deriveQuickStart), optional ones included. */
  steps: readonly {
    id: QuickStartStepId;
    status: "todo" | "done" | "skipped";
  }[];
}

type StepCounts = Record<QuickStartStepId, { done: number; skipped: number }>;

export interface ActivationCohort {
  /** Sign-up bounds, [from, to). */
  from: number;
  to: number;
  /** Every member's 7-day window has passed (to + 7 d <= now). Open cohorts can still grow. */
  windowClosed: boolean;
  signedUp: number;
  activated: number;
  /** activated / signedUp; 0 for an empty cohort. */
  rate: number;
  /** Members meeting each criterion within their window (connection = mutual or household). */
  breakdown: {
    copies3: number;
    completion: number;
    mutual: number;
    household: number;
    connection: number;
    completion14d: number;
  };
  /** The quick start funnel. welcomeAnswered, startedQuickStart, quickStartCompleted and
   * householdLinkCreated are current state, not limited to the window. */
  funnel: {
    signedUp: number;
    welcomeAnswered: number;
    startedQuickStart: number;
    copies3: number;
    activated: number;
    quickStartCompleted: number;
    householdLinkCreated: number;
  };
  /** Per quick start step: members for whom it is done, or skipped and not done. */
  steps: StepCounts;
}

export interface ActivationReport {
  from: number;
  to: number;
  generatedAt: number;
  /** Weekly sign-up cohorts starting at `from`; the last one ends at `to`. */
  cohorts: ActivationCohort[];
  total: ActivationCohort;
}

const OPTIONAL_STEP: QuickStartStepId = "household";

const cohortOf = (
  members: readonly ActivationReportMember[],
  from: number,
  to: number,
  now: number,
): ActivationCohort => {
  const inCohort = members.filter((m) => m.signupAt >= from && m.signupAt < to);
  const results = inCohort.map((m) => ({
    member: m,
    activation: evaluateActivation(m.activation, m.signupAt),
  }));
  const count = (pick: (r: (typeof results)[number]) => boolean): number =>
    results.filter(pick).length;
  const activated = count((r) => r.activation.activated);
  const copies3 = count((r) => r.activation.copies3);
  const steps = Object.fromEntries(
    QUICK_START_STEP_IDS.map((id) => [
      id,
      {
        done: count((r) =>
          r.member.steps.some((s) => s.id === id && s.status === "done"),
        ),
        skipped: count((r) =>
          r.member.steps.some((s) => s.id === id && s.status === "skipped"),
        ),
      },
    ]),
  ) as StepCounts;
  return {
    from,
    to,
    windowClosed: to + ACTIVATION_WINDOW_MS <= now,
    signedUp: inCohort.length,
    activated,
    rate: inCohort.length === 0 ? 0 : activated / inCohort.length,
    breakdown: {
      copies3,
      completion: count((r) => r.activation.completion),
      mutual: count((r) => r.activation.mutual),
      household: count((r) => r.activation.household),
      connection: count((r) => r.activation.mutual || r.activation.household),
      completion14d: count((r) => r.activation.completion14d),
    },
    funnel: {
      signedUp: inCohort.length,
      welcomeAnswered: count((r) => r.member.welcomeAnswered),
      startedQuickStart: count((r) => r.member.startedQuickStart),
      copies3,
      activated,
      quickStartCompleted: count(
        (r) =>
          r.member.steps.length > 0 &&
          r.member.steps.every(
            (s) => s.id === OPTIONAL_STEP || s.status === "done",
          ),
      ),
      householdLinkCreated: count((r) => r.member.householdLinkCreated),
    },
    steps,
  };
};

export const summarizeActivation = (
  members: readonly ActivationReportMember[],
  range: { from: number; to: number; now: number },
): ActivationReport => {
  const { from, to, now } = range;
  const cohorts: ActivationCohort[] = [];
  for (let start = from; start < to; start += ACTIVATION_COHORT_MS) {
    cohorts.push(
      cohortOf(members, start, Math.min(start + ACTIVATION_COHORT_MS, to), now),
    );
  }
  return {
    from,
    to,
    generatedAt: now,
    cohorts,
    total: cohortOf(members, from, to, now),
  };
};

src/onboarding/domain/quickStart.ts.source:
// Quick start: a first-sign-in checklist. Each step's "done" is derived from the member's real data
// (facts gathered by the backend); only the member's choices are stored: skipped steps, when the
// welcome dialog / dashboard card were dismissed, and when the member first opened the flow (a
// funnel fact for the activation report, which also retires the welcome). Done wins over skipped.
// Timestamps are epoch ms.

export const QUICK_START_STEP_IDS = [
  "puzzles",
  "solves",
  "people",
  "household",
  "profile",
] as const;
export type QuickStartStepId = (typeof QUICK_START_STEP_IDS)[number];

const OPTIONAL_STEPS: ReadonlySet<QuickStartStepId> = new Set(["household"]);

/** Step 1 is done at this many copies (the activation threshold). */
export const QUICK_START_COPIES_DONE = 3;
const DAY_MS = 24 * 60 * 60 * 1000;
/** New members (younger than this) are eligible for the welcome dialog. */
export const QUICK_START_WELCOME_WINDOW_MS = 7 * DAY_MS;
/** The card shows to members younger than this, or to anyone with 0 copies. */
export const QUICK_START_CARD_WINDOW_MS = 30 * DAY_MS;

export interface QuickStartFacts {
  copies: number;
  completions: number; // finished solves, any date precision
  follows: number; // members I follow
  pendingFollowRequests: number; // my pending requests to private profiles
  inHousehold: boolean;
  householdMembers: number; // people in my household, me included; 0 when in none
  pendingHouseholdInvite: boolean;
  hasLocation: boolean;
  visibilitySet: boolean; // profile visibility explicitly chosen
}

export interface QuickStartState {
  skippedSteps: QuickStartStepId[];
  welcomeDismissedAt?: number;
  cardDismissedAt?: number;
  /** When the member first opened the /welcome flow. */
  startedAt?: number;
}

export interface QuickStartInput {
  now: number;
  accountCreatedAt: number;
  state: QuickStartState;
  facts: QuickStartFacts;
}

export type QuickStartStepStatus = "todo" | "done" | "skipped";

export interface QuickStartStep {
  id: QuickStartStepId;
  status: QuickStartStepStatus;
  optional: boolean;
  count?: number;
  pendingInvite?: boolean;
}

export interface QuickStart {
  eligible: boolean;
  showWelcome: boolean;
  cardVisible: boolean;
  steps: QuickStartStep[];
  requiredDone: number;
  requiredTotal: number;
}

const stepDetails = (
  id: QuickStartStepId,
  f: QuickStartFacts,
): { done: boolean; count?: number; pendingInvite?: boolean } => {
  switch (id) {
    case "puzzles":
      return { done: f.copies >= QUICK_START_COPIES_DONE, count: f.copies };
    case "solves":
      return { done: f.completions > 0, count: f.completions };
    case "people":
      return {
        done: f.follows > 0 || f.pendingFollowRequests > 0,
        count: f.follows,
      };
    case "household":
      // A household of one is still done (the step is optional); the count lets the UI say
      // "just you so far" instead of claiming a shared shelf.
      return {
        done: f.inHousehold,
        count: f.householdMembers,
        pendingInvite: f.pendingHouseholdInvite,
      };
    case "profile":
      return { done: f.hasLocation || f.visibilitySet };
  }
};

export const deriveQuickStart = (input: QuickStartInput): QuickStart => {
  const { now, accountCreatedAt, state, facts } = input;
  const skipped = new Set(state.skippedSteps);
  const steps = QUICK_START_STEP_IDS.map((id): QuickStartStep => {
    const { done, ...details } = stepDetails(id, facts);
    const status: QuickStartStepStatus = done
      ? "done"
      : skipped.has(id)
        ? "skipped"
        : "todo";
    return { id, status, optional: OPTIONAL_STEPS.has(id), ...details };
  });
  const required = steps.filter((s) => !s.optional);
  const age = now - accountCreatedAt;
  const eligible = age < QUICK_START_WELCOME_WINDOW_MS;
  const cardVisible =
    state.cardDismissedAt === undefined &&
    required.some((s) => s.status === "todo") &&
    (age < QUICK_START_CARD_WINDOW_MS || facts.copies === 0);
  return {
    eligible,
    // The welcome offers the flow, so it stops once the member opened /welcome some other way
    // (an invite link, the card, the account menu): it would only repeat that offer.
    showWelcome:
      eligible &&
      state.welcomeDismissedAt === undefined &&
      state.startedAt === undefined,
    cardVisible,
    steps,
    requiredDone: required.filter((s) => s.status === "done").length,
    requiredTotal: required.length,
  };
};

export type QuickStartChange =
  | { kind: "skipStep" | "unskipStep"; step: QuickStartStepId }
  | {
      kind:
        "dismissWelcome" | "dismissCard" | "restoreCard" | "startQuickStart";
    };

// The member's stored state after `change`, or null when it changes nothing (so writes are
// idempotent). Skipped steps stay in step order; a repeated dismiss keeps the first timestamp.
export const applyQuickStartChange = (
  state: QuickStartState,
  change: QuickStartChange,
  now: number,
): QuickStartState | null => {
  switch (change.kind) {
    case "skipStep":
    case "unskipStep": {
      const skip = change.kind === "skipStep";
      if (state.skippedSteps.includes(change.step) === skip) return null;
      const skippedSteps = QUICK_START_STEP_IDS.filter((id) =>
        id === change.step ? skip : state.skippedSteps.includes(id),
      );
      return { ...state, skippedSteps };
    }
    case "dismissWelcome":
      return state.welcomeDismissedAt === undefined
        ? { ...state, welcomeDismissedAt: now }
        : null;
    case "dismissCard":
      return state.cardDismissedAt === undefined
        ? { ...state, cardDismissedAt: now }
        : null;
    case "startQuickStart":
      return state.startedAt === undefined
        ? { ...state, startedAt: now }
        : null;
    case "restoreCard": {
      if (state.cardDismissedAt === undefined) return null;
      const { cardDismissedAt: _, ...rest } = state;
      return rest;
    }
  }
};

