import { DomainEvent } from "../../../shared-kernel";
import { WithdrawInvitesFrom } from "../ports/in/circle-invites.port";
import { CircleInviteDeps } from "./circle-invite-deps";

// When a member leaves a circle, is removed, or loses Admin, every invite they still have pending
// there is withdrawn in the same transaction: nobody joins on the word of someone who can no
// longer invite, and the seats those invites held free up.
export const makeWithdrawInvitesFrom =
  (
    deps: Pick<CircleInviteDeps, "invites" | "events" | "clock">,
  ): WithdrawInvitesFrom =>
  async (cmd) => {
    const now = deps.clock.now();
    const pending = (
      await deps.invites.listPendingForCircle(cmd.circleId)
    ).filter((invite) => invite.inviterId === cmd.inviterId);
    const events: DomainEvent[] = [];
    for (const invite of pending) {
      invite.withdraw(now);
      await deps.invites.save(invite);
      events.push(...invite.pullEvents());
    }
    await deps.events.publish(events);
    return pending.length;
  };

src/sharing/domain/circle-invite.ts.source:
import { DomainEvent, err, ok, Result } from "../../shared-kernel";
import type { Circle } from "./circle";
import { SharingError } from "./errors";
import {
  CircleInviteAccepted,
  CircleInviteDeclined,
  CircleInviteExpired,
  CircleInviteIssued,
  CircleInviteRevoked,
} from "./events";
import { CircleId, CircleInviteId, MemberId } from "./ids";
import { PermissionLevel } from "./permission-level";

// How long an unanswered circle invite stays open.
export const CIRCLE_INVITE_TTL_MS = 14 * 24 * 60 * 60 * 1000;

// After the invitee declines or a member revokes an invite, the same (circle, invitee) can't be invited
// again for this long, so an Admin can't keep re-sending an invite someone turned down.
export const CIRCLE_REINVITE_COOLDOWN_MS = 7 * 24 * 60 * 60 * 1000;

export type CircleInviteStatus =
  "pending" | "accepted" | "declined" | "revoked" | "expired";

export interface CircleInviteState {
  readonly id: CircleInviteId;
  readonly circleId: CircleId;
  readonly inviterId: MemberId;
  readonly inviteeId: MemberId;
  // The seat the invitee takes on accepting.
  readonly permission: PermissionLevel;
  readonly status: CircleInviteStatus;
  readonly createdAt: Date;
  readonly expiresAt: Date;
  readonly decidedAt?: Date;
  // Who revoked it; absent when the system withdrew it (its inviter lost the standing to invite).
  readonly revokedBy?: MemberId;
}

// An invitation to join a circle: pending → accepted | declined | revoked | expired. A pending
// invite grants NOTHING (it is not a membership); the invitee only joins when Circle.admitInvitee
// seats them on an accepted invite. Expiry is lazy: once `expiresAt` has passed, a still-pending
// invite behaves as expired for every transition, whether or not it was flipped yet.
export class CircleInvite {
  private events: DomainEvent[] = [];

  private constructor(private state: CircleInviteState) {}

  get id(): CircleInviteId {
    return this.state.id;
  }

  get circleId(): CircleId {
    return this.state.circleId;
  }

  get inviterId(): MemberId {
    return this.state.inviterId;
  }

  get inviteeId(): MemberId {
    return this.state.inviteeId;
  }

  get permission(): PermissionLevel {
    return this.state.permission;
  }

  get status(): CircleInviteStatus {
    return this.state.status;
  }

  get expiresAt(): Date {
    return this.state.expiresAt;
  }

  // Issue a new pending invite expiring CIRCLE_INVITE_TTL_MS from now. Who may invite whom (Admin
  // actor, contact rule, not already a member, the cap) is checked by the application layer; the
  // invite itself only refuses inviting oneself.
  static issue(props: {
    readonly id: CircleInviteId;
    readonly circleId: CircleId;
    readonly inviterId: MemberId;
    readonly inviteeId: MemberId;
    readonly permission: PermissionLevel;
    readonly now: Date;
  }): Result<CircleInvite, SharingError> {
    if (props.inviterId === props.inviteeId) {
      return err(SharingError.cannotInvite());
    }
    const expiresAt = new Date(props.now.getTime() + CIRCLE_INVITE_TTL_MS);
    const invite = new CircleInvite({
      id: props.id,
      circleId: props.circleId,
      inviterId: props.inviterId,
      inviteeId: props.inviteeId,
      permission: props.permission,
      status: "pending",
      createdAt: props.now,
      expiresAt,
    });
    invite.record(
      new CircleInviteIssued(
        props.id,
        props.circleId,
        props.inviterId,
        props.inviteeId,
        expiresAt,
        props.now,
      ),
    );
    return ok(invite);
  }

  // Pending and not yet past its expiry: the only state in which the invite can still be answered.
  isOpenAt(now: Date): boolean {
    return this.state.status === "pending" && now < this.state.expiresAt;
  }

  // Whether this decided invite still holds off a new invite to the same invitee at `now`: it was
  // declined, or revoked by a member, less than CIRCLE_REINVITE_COOLDOWN_MS ago. A system
  // withdrawal (see withdraw) holds nothing off: the invitee did nothing and nobody chose to.
  holdsOffReinviteAt(now: Date): boolean {
    const { status, decidedAt, revokedBy } = this.state;
    return (
      (status === "declined" ||
        (status === "revoked" && revokedBy !== undefined)) &&
      decidedAt !== undefined &&
      now.getTime() < decidedAt.getTime() + CIRCLE_REINVITE_COOLDOWN_MS
    );
  }

  accept(by: MemberId, now: Date): Result<void, SharingError> {
    const guard = this.guardAnswer(by, now);
    if (guard.isErr) return guard;
    this.decide("accepted", now);
    this.record(
      new CircleInviteAccepted(
        this.state.id,
        this.state.circleId,
        this.state.inviteeId,
        this.state.inviterId,
        now,
      ),
    );
    return ok(undefined);
  }

  decline(by: MemberId, now: Date): Result<void, SharingError> {
    const guard = this.guardAnswer(by, now);
    if (guard.isErr) return guard;
    this.decide("declined", now);
    this.record(
      new CircleInviteDeclined(
        this.state.id,
        this.state.circleId,
        this.state.inviteeId,
        now,
      ),
    );
    return ok(undefined);
  }

  // Withdraw an open invite. Allowed for the member who sent it, or any current Admin of the
  // invite's circle.
  revoke(
    actor: MemberId,
    circle: Circle,
    now: Date,
  ): Result<void, SharingError> {
    const allowed =
      actor === this.state.inviterId ||
      (circle.id === this.state.circleId && circle.isAdmin(actor));
    if (!allowed) return err(SharingError.cannotRevokeInvite());
    const open = this.guardOpen(now);
    if (open.isErr) return open;
    this.decide("revoked", now);
    this.state = { ...this.state, revokedBy: actor };
    this.record(
      new CircleInviteRevoked(this.state.id, this.state.circleId, actor, now),
    );
    return ok(undefined);
  }

  // The system withdraws a pending invite whose inviter can no longer stand behind it (they left,
  // were removed, or lost Admin). Recorded as a revoke with no revoker, so it frees its seat
  // under the cap and the ex-inviter can't act on it any more.
  withdraw(now: Date): Result<void, SharingError> {
    if (this.state.status !== "pending") {
      return err(SharingError.inviteNotPending());
    }
    this.decide("revoked", now);
    this.record(
      new CircleInviteRevoked(this.state.id, this.state.circleId, null, now),
    );
    return ok(undefined);
  }

  // Flip a pending invite whose expiresAt has been reached to expired.
  expire(now: Date): Result<void, SharingError> {
    if (this.state.status !== "pending") {
      return err(SharingError.inviteNotPending());
    }
    if (now < this.state.expiresAt) return err(SharingError.inviteNotDue());
    this.decide("expired", now);
    this.record(
      new CircleInviteExpired(this.state.id, this.state.circleId, now),
    );
    return ok(undefined);
  }

  pullEvents(): readonly DomainEvent[] {
    const drained = this.events;
    this.events = [];
    return drained;
  }

  static rehydrate(state: CircleInviteState): CircleInvite {
    return new CircleInvite(state);
  }

  toState(): CircleInviteState {
    return this.state;
  }

  private guardAnswer(by: MemberId, now: Date): Result<void, SharingError> {
    if (by !== this.state.inviteeId) return err(SharingError.notInvitee());
    return this.guardOpen(now);
  }

  private guardOpen(now: Date): Result<void, SharingError> {
    if (this.state.status !== "pending") {
      return err(SharingError.inviteNotPending());
    }
    if (now >= this.state.expiresAt) return err(SharingError.inviteExpired());
    return ok(undefined);
  }

  private decide(status: CircleInviteStatus, now: Date): void {
    this.state = { ...this.state, status, decidedAt: now };
  }

  private record(event: DomainEvent): void {
    this.events.push(event);
  }
}

src/sharing/domain/circle.ts.source:
import {
  DomainEvent,
  err,
  hasVisibleCharacter,
  normaliseDisplayName,
  ok,
  Result,
} from "../../shared-kernel";
import type { CircleInvite } from "./circle-invite";
import { SharingError } from "./errors";
import {
  CircleCreated,
  CircleDeleted,
  CopySharedToCircle,
  MemberJoinedCircle,
  MemberLeftCircle,
  MemberLeftCircleReason,
} from "./events";
import { CircleId, CopyId, MemberId, MembershipId } from "./ids";
import { Membership } from "./membership";
import {
  canExchangeWithin,
  canManageMembers,
  PermissionLevel,
} from "./permission-level";

// The most seats a circle may hold, the owner's included.
export const MAX_CIRCLE_MEMBERS = 50;

// The longest a circle's name may be, counted after normalising (see normaliseDisplayName). Checked
// on create only: rehydrate never re-checks, so circles stored before the limit keep their names.
export const MAX_CIRCLE_NAME_LENGTH = 100;

// Input to create(): a new private group and its first (owner) membership.
export interface CreateCircleProps {
  readonly id: CircleId;
  readonly ownerId: MemberId;
  readonly ownerMembershipId: MembershipId;
  readonly name: string;
  readonly now: Date;
}

// The persistable shape of a Circle. The membership list is part of the aggregate (loaded/saved as
// one unit) so every invariant — admin-gated changes, no duplicate member, owner is permanent —
// can be enforced against the whole set in one place.
export interface CircleState {
  readonly id: CircleId;
  readonly ownerId: MemberId;
  readonly name: string;
  readonly memberships: readonly ReturnType<Membership["toState"]>[];
  readonly createdAt: Date;
}

// The Circle aggregate root: a private group of members, each at a PermissionLevel. The owner is
// implicitly Admin and always a member. Membership operations are gated on the ACTOR holding Admin
// (so authorisation is a domain rule, not an app-layer afterthought), and only the owner may remove
// or demote another Admin; content is only visible to members, which the VisibilityPolicy reads off
// `isMember`.
export class Circle {
  private events: DomainEvent[] = [];

  private constructor(
    private state: CircleState,
    private memberships: Membership[],
  ) {}

  get id(): CircleId {
    return this.state.id;
  }

  get ownerId(): MemberId {
    return this.state.ownerId;
  }

  get name(): string {
    return this.state.name;
  }

  get members(): readonly Membership[] {
    return this.memberships;
  }

  // Open a new circle. The name is normalised (normaliseDisplayName) and must then show at least
  // one visible character and be at most MAX_CIRCLE_NAME_LENGTH long (InvalidCircleName
  // otherwise). The owner is seeded as the first membership at Admin — the owner is implicitly
  // Admin and can never be demoted or removed.
  static create(props: CreateCircleProps): Result<Circle, SharingError> {
    const name = normaliseDisplayName(props.name);
    if (!hasVisibleCharacter(name) || name.length > MAX_CIRCLE_NAME_LENGTH) {
      return err(SharingError.invalidCircleName());
    }
    const owner = Membership.create(
      props.ownerMembershipId,
      props.ownerId,
      "Admin",
      props.now,
    );
    const circle = new Circle(
      {
        id: props.id,
        ownerId: props.ownerId,
        name,
        memberships: [owner.toState()],
        createdAt: props.now,
      },
      [owner],
    );
    circle.record(new CircleCreated(props.id, props.ownerId, props.now));
    return ok(circle);
  }

  // Is this member currently in the circle? The owner is always a member; the VisibilityPolicy
  // uses this to decide friend-circle visibility (content is visible only while a member).
  isMember(memberId: MemberId): boolean {
    return this.memberships.some((m) => m.memberId === memberId);
  }

  // Does this member hold Admin here? The owner always does.
  isAdmin(memberId: MemberId): boolean {
    return this.requireAdmin(memberId).isOk;
  }

  // Add a member at a permission level. Only an Admin actor may do so; the member must not already
  // belong and the circle must have a free seat. Emits MemberJoinedCircle.
  addMember(
    actor: MemberId,
    membershipId: MembershipId,
    memberId: MemberId,
    permission: PermissionLevel,
    now: Date,
  ): Result<void, SharingError> {
    const gate = this.requireAdmin(actor);
    if (gate.isErr) return err(gate.error);
    return this.seat(membershipId, memberId, permission, now);
  }

  // Seat the invitee of an accepted invite, at the invite's permission. Authorised by the invite
  // rather than by an acting Admin: the invite must be to THIS circle and accepted, and its inviter
  // must STILL be an Admin here (an inviter who lost Admin or left can't bring anyone in). The same
  // already-member and seat-cap rules as addMember apply. Emits MemberJoinedCircle.
  admitInvitee(
    invite: CircleInvite,
    membershipId: MembershipId,
    now: Date,
  ): Result<void, SharingError> {
    if (invite.circleId !== this.state.id || invite.status !== "accepted") {
      return err(SharingError.inviteNotAccepted());
    }
    const gate = this.requireAdmin(invite.inviterId);
    if (gate.isErr) return err(gate.error);
    return this.seat(membershipId, invite.inviteeId, invite.permission, now);
  }

  // Remove a member. Only an Admin actor may do so; the target must be a member and must not be the
  // owner (the owner's seat is permanent). Another Admin's seat is the owner's alone to remove
  // (NotCircleOwner for anyone else), so Admins below the owner can't push each other out. Emits
  // MemberLeftCircle with reason "removed".
  removeMember(
    actor: MemberId,
    memberId: MemberId,
    now: Date,
  ): Result<void, SharingError> {
    const gate = this.requireAdmin(actor);
    if (gate.isErr) return err(gate.error);
    if (memberId === this.state.ownerId)
      return err(SharingError.cannotRemoveOwner());
    const target = this.memberships.find((m) => m.memberId === memberId);
    if (!target) return err(SharingError.notAMember());
    const mayManage = this.requireMayManageSeat(actor, target);
    if (mayManage.isErr) return err(mayManage.error);

    this.dropMember(memberId, "removed", now);
    return ok(undefined);
  }

  // A member walks out of the circle on their own. Any member may leave except the owner, whose
  // seat is permanent. Emits MemberLeftCircle with reason "left".
  leave(memberId: MemberId, now: Date): Result<void, SharingError> {
    if (memberId === this.state.ownerId)
      return err(SharingError.ownerCannotLeave());
    if (!this.isMember(memberId)) return err(SharingError.notAMember());

    this.dropMember(memberId, "left", now);
    return ok(undefined);
  }

  // Change a member's permission. Only an Admin actor may do so; the target must be a member, must
  // not be the owner (the owner stays Admin), and the change must be a real one. Any Admin may
  // promote a member to Admin and step down themselves, but only the owner may change another
  // Admin's level (NotCircleOwner for anyone else).
  changePermission(
    actor: MemberId,
    memberId: MemberId,
    permission: PermissionLevel,
  ): Result<void, SharingError> {
    const gate = this.requireAdmin(actor);
    if (gate.isErr) return err(gate.error);
    if (memberId === this.state.ownerId)
      return err(SharingError.cannotRemoveOwner());

    const current = this.memberships.find((m) => m.memberId === memberId);
    if (!current) return err(SharingError.notAMember());
    const mayManage = this.requireMayManageSeat(actor, current);
    if (mayManage.isErr) return err(mayManage.error);
    if (current.permission === permission) {
      return err(SharingError.duplicatePermission());
    }

    this.memberships = this.memberships.map((m) =>
      m.memberId === memberId ? m.withPermission(permission) : m,
    );
    return ok(undefined);
  }

  // Hand the circle to another member (the system does this when the owner's account is deleted,
  // conversation/purgeMemberMessagingData). The new owner must be a current member; their seat
  // becomes Admin (the owner is always Admin), keeping its identity and join time. The old owner's
  // seat stays as it is: a historical trace, now an ordinary seat the new owner may remove. Like
  // changePermission, no event: nothing subscribes to an ownership change.
  handOverOwnership(to: MemberId): Result<void, SharingError> {
    if (!this.isMember(to)) return err(SharingError.notAMember());
    this.state = { ...this.state, ownerId: to };
    this.memberships = this.memberships.map((m) =>
      m.memberId === to ? m.withPermission("Admin") : m,
    );
    return ok(undefined);
  }

  // Share a copy into this circle, making it visible to the circle's members. A member whose seat
  // may exchange (Exchange or Admin) may share; ViewOnly may not. That the copy is the actor's own
  // is checked by the caller (the aggregate never loads copies). The level counts only at the
  // moment of sharing: a member later moved to ViewOnly keeps the shares they made, and a share
  // ends only when its owner takes it back, leaves the circle or the copy changes hands. Emits
  // CopySharedToCircle; the aggregate holds no copy state (the link lives in a read model fed by
  // the event), so this is a pure authorisation + announcement.
  shareCopy(
    actor: MemberId,
    copyId: CopyId,
    now: Date,
  ): Result<void, SharingError> {
    return this.shareCopies(actor, [copyId], now);
  }

  // shareCopy for several copies at once, under the same seat gate: one CopySharedToCircle per
  // copy, or none at all when the seat may not share (checked even for an empty batch).
  shareCopies(
    actor: MemberId,
    copyIds: readonly CopyId[],
    now: Date,
  ): Result<void, SharingError> {
    const seat = this.memberships.find((m) => m.memberId === actor);
    if (!seat || !canExchangeWithin(seat.permission)) {
      return err(SharingError.cannotShareCopy());
    }

    for (const copyId of copyIds) {
      this.record(new CopySharedToCircle(this.state.id, copyId, now));
    }
    return ok(undefined);
  }

  // Delete the circle. Only the owner may, and only by typing its exact name back (`confirmName`,
  // compared untrimmed). A non-member is told NotAMember (so the transport can answer not-found),
  // a member who isn't the owner NotCircleOwner. Emits CircleDeleted naming every other member,
  // so they can be told after the circle is gone; the repository then deletes it.
  delete(
    actor: MemberId,
    confirmName: string,
    now: Date,
  ): Result<void, SharingError> {
    if (!this.isMember(actor)) return err(SharingError.notAMember());
    if (actor !== this.state.ownerId) return err(SharingError.notCircleOwner());
    if (confirmName !== this.state.name) {
      return err(SharingError.confirmationMismatch());
    }

    const memberIds = this.memberships
      .map((m) => m.memberId)
      .filter((id) => id !== this.state.ownerId);
    this.record(
      new CircleDeleted(
        this.state.id,
        this.state.ownerId,
        memberIds,
        this.state.name,
        now,
      ),
    );
    return ok(undefined);
  }

  pullEvents(): readonly DomainEvent[] {
    const drained = this.events;
    this.events = [];
    return drained;
  }

  static rehydrate(state: CircleState): Circle {
    return new Circle(state, state.memberships.map(Membership.rehydrate));
  }

  toState(): CircleState {
    return {
      ...this.state,
      memberships: this.memberships.map((m) => m.toState()),
    };
  }

  // --- internals ---

  // Membership management is Admin-only. The owner is implicitly Admin, so this also passes for the
  // owner even though their seat is independently guaranteed Admin.
  private requireAdmin(actor: MemberId): Result<void, SharingError> {
    const seat = this.memberships.find((m) => m.memberId === actor);
    if (!seat || !canManageMembers(seat.permission)) {
      return err(SharingError.notCircleAdmin());
    }
    return ok(undefined);
  }

  // An Admin's seat is managed by the owner, or by that Admin themselves (stepping down); another
  // Admin may not touch it. Seats below Admin are open to any Admin (requireAdmin runs first).
  private requireMayManageSeat(
    actor: MemberId,
    target: Membership,
  ): Result<void, SharingError> {
    if (
      target.permission === "Admin" &&
      actor !== this.state.ownerId &&
      actor !== target.memberId
    ) {
      return err(SharingError.notCircleOwner());
    }
    return ok(undefined);
  }

  private seat(
    membershipId: MembershipId,
    memberId: MemberId,
    permission: PermissionLevel,
    now: Date,
  ): Result<void, SharingError> {
    if (this.isMember(memberId)) return err(SharingError.alreadyMember());
    if (this.memberships.length >= MAX_CIRCLE_MEMBERS) {
      return err(SharingError.circleFull());
    }

    this.memberships.push(
      Membership.create(membershipId, memberId, permission, now),
    );
    this.record(new MemberJoinedCircle(this.state.id, memberId, now));
    return ok(undefined);
  }

  private dropMember(
    memberId: MemberId,
    reason: MemberLeftCircleReason,
    now: Date,
  ): void {
    this.memberships = this.memberships.filter((m) => m.memberId !== memberId);
    this.record(new MemberLeftCircle(this.state.id, memberId, reason, now));
  }

  private record(event: DomainEvent): void {
    this.events.push(event);
  }
}

