import { DomainEvent } from "../../shared-kernel";
import { CircleId, CircleInviteId, CopyId, MemberId } from "./ids";

// All Sharing domain events implement DomainEvent (name + occurredAt). They are plain immutable
// records: the Circle aggregate records them; an outbound publisher serialises and dispatches them
// to subscribers (Notifications, Insights, and any read model of who-can-see-what).

// A private group was opened by its owner. Optional in the spec, but emitting it lets read models
// project a circle without reloading the aggregate.
export class CircleCreated implements DomainEvent {
  readonly name = "CircleCreated";
  constructor(
    readonly circleId: CircleId,
    readonly ownerId: MemberId,
    readonly occurredAt: Date,
  ) {}
}

// A member was added to a circle. Drives circle-aware visibility read models and notifications.
export class MemberJoinedCircle implements DomainEvent {
  readonly name = "MemberJoinedCircle";
  constructor(
    readonly circleId: CircleId,
    readonly memberId: MemberId,
    readonly occurredAt: Date,
  ) {}
}

// Why a member stopped being part of a circle: they walked out ("left") or an Admin took them out
// ("removed").
export type MemberLeftCircleReason = "left" | "removed";

// A member stopped being part of a circle, by leaving or by an Admin's removal. Drives the
// circle-copy read model (their shares into the circle are withdrawn) and, later, circle chat and
// invitation flows.
export class MemberLeftCircle implements DomainEvent {
  readonly name = "MemberLeftCircle";
  constructor(
    readonly circleId: CircleId,
    readonly memberId: MemberId,
    readonly reason: MemberLeftCircleReason,
    readonly occurredAt: Date,
  ) {}
}

// A copy was shared into a circle (made visible to that circle's members). Carries the copy id so
// Library/Insights need not reload anything to react.
export class CopySharedToCircle implements DomainEvent {
  readonly name = "CopySharedToCircle";
  constructor(
    readonly circleId: CircleId,
    readonly copyId: CopyId,
    readonly occurredAt: Date,
  ) {}
}

// An Admin invited a member to a circle. Carries `expiresAt` so the backend can schedule the
// invite's expiry without reloading it; drives the invitee's circle_invite_received notification.
export class CircleInviteIssued implements DomainEvent {
  readonly name = "CircleInviteIssued";
  constructor(
    readonly inviteId: CircleInviteId,
    readonly circleId: CircleId,
    readonly inviterId: MemberId,
    readonly inviteeId: MemberId,
    readonly expiresAt: Date,
    readonly occurredAt: Date,
  ) {}
}

// The invitee accepted (their MemberJoinedCircle is recorded by the Circle alongside). Drives the
// inviter's circle_invite_accepted notification.
export class CircleInviteAccepted implements DomainEvent {
  readonly name = "CircleInviteAccepted";
  constructor(
    readonly inviteId: CircleInviteId,
    readonly circleId: CircleId,
    readonly inviteeId: MemberId,
    readonly inviterId: MemberId,
    readonly occurredAt: Date,
  ) {}
}

// The invitee declined. Silent: no notification is mapped for it.
export class CircleInviteDeclined implements DomainEvent {
  readonly name = "CircleInviteDeclined";
  constructor(
    readonly inviteId: CircleInviteId,
    readonly circleId: CircleId,
    readonly inviteeId: MemberId,
    readonly occurredAt: Date,
  ) {}
}

// The inviter or an Admin withdrew a pending invite (`revokedBy`), or the system did because its
// inviter left or lost Admin (`revokedBy` null).
export class CircleInviteRevoked implements DomainEvent {
  readonly name = "CircleInviteRevoked";
  constructor(
    readonly inviteId: CircleInviteId,
    readonly circleId: CircleId,
    readonly revokedBy: MemberId | null,
    readonly occurredAt: Date,
  ) {}
}

// A pending invite reached its expiresAt unanswered.
export class CircleInviteExpired implements DomainEvent {
  readonly name = "CircleInviteExpired";
  constructor(
    readonly inviteId: CircleInviteId,
    readonly circleId: CircleId,
    readonly occurredAt: Date,
  ) {}
}

// The owner deleted the circle. Carries everything its subscribers need, because the circle is
// gone by the time they run: `memberIds` are the members told about it (the owner excluded) and
// `name` is snapshotted for their notification. Drives the inline cleanup (invites, scheduled
// copy-share purge) and the circle_deleted notifications.
export class CircleDeleted implements DomainEvent {
  readonly name = "CircleDeleted";
  constructor(
    readonly circleId: CircleId,
    readonly ownerId: MemberId,
    readonly memberIds: readonly MemberId[],
    readonly circleName: string,
    readonly occurredAt: Date,
  ) {}
}

export type SharingDomainEvent =
  | CircleCreated
  | MemberJoinedCircle
  | MemberLeftCircle
  | CopySharedToCircle
  | CircleInviteIssued
  | CircleInviteAccepted
  | CircleInviteDeclined
  | CircleInviteRevoked
  | CircleInviteExpired
  | CircleDeleted;

src/sharing/domain/exchange-route.ts.source:
import { canExchangeWithin, PermissionLevel } from "./permission-level";

// One way a requester reaches another member's copy. The caller resolves which apply; this module
// only decides whether they allow an exchange request.
//   public       — the owner's profile is public and the copy is open
//   household    — the owner is in the requester's household
//   mutualFollow — the requester and the owner follow each other
//   circle       — a circle that holds the share, both are current members; `level` is the
//                  REQUESTER's permission in that circle
export type ExchangeRoute =
  | { readonly kind: "public" }
  | { readonly kind: "household" }
  | { readonly kind: "mutualFollow" }
  | { readonly kind: "circle"; readonly level: PermissionLevel };

// May the requester ask for an exchange? Yes if ANY route allows it: every non-circle route does,
// and a circle route does when the requester's level there is Exchange or Admin. A ViewOnly seat in
// one circle never cancels another route. No route at all means no.
export const mayExchangeVia = (routes: readonly ExchangeRoute[]): boolean =>
  exchangeAllowedVia(routes) !== null;

// WHICH kind of route allows the request: "direct" when a non-circle route does (they all do),
// "circle" when only Exchange/Admin circle seats do, null when nothing does. Recorded on the request
// so accept knows whether the requester's circle standing is what it rested on.
export const exchangeAllowedVia = (
  routes: readonly ExchangeRoute[],
): "direct" | "circle" | null => {
  if (routes.some((route) => route.kind !== "circle")) return "direct";
  return routes.some(
    (route) => route.kind === "circle" && canExchangeWithin(route.level),
  )
    ? "circle"
    : null;
};

src/sharing/domain/membership.ts.source:
import { MemberId, MembershipId } from "./ids";
import { PermissionLevel } from "./permission-level";

// The persistable shape of a single membership row within a Circle. A child entity of the Circle
// aggregate: it has its own identity (MembershipId) but is only ever reached through its Circle,
// which guards every change so the invariants hold.
export interface MembershipState {
  readonly id: MembershipId;
  readonly memberId: MemberId;
  readonly permission: PermissionLevel;
  readonly joinedAt: Date;
}

// Membership: a member's seat in a circle at a given permission. Immutable; the aggregate replaces
// the whole row (via withPermission) rather than mutating in place, so events stay the only signal
// of change.
export class Membership {
  private constructor(private readonly state: MembershipState) {}

  get id(): MembershipId {
    return this.state.id;
  }

  get memberId(): MemberId {
    return this.state.memberId;
  }

  get permission(): PermissionLevel {
    return this.state.permission;
  }

  get joinedAt(): Date {
    return this.state.joinedAt;
  }

  static create(
    id: MembershipId,
    memberId: MemberId,
    permission: PermissionLevel,
    joinedAt: Date,
  ): Membership {
    return new Membership({ id, memberId, permission, joinedAt });
  }

  // A copy of this membership at a new permission level, preserving identity and join time.
  withPermission(permission: PermissionLevel): Membership {
    return new Membership({ ...this.state, permission });
  }

  static rehydrate(state: MembershipState): Membership {
    return new Membership(state);
  }

  toState(): MembershipState {
    return this.state;
  }
}

src/sharing/domain/permission-level.ts.source:
// What a member is allowed to do within a Circle. A literal union (not a class) because it is a
// plain enumerated capability the boundary passes as a primitive. `ViewOnly` may see circle
// content; `Exchange` may additionally transact within the circle; `Admin` may additionally
// manage membership and permissions. The owner is implicitly `Admin`.
export type PermissionLevel = "ViewOnly" | "Exchange" | "Admin";

// Ordering used for capability checks: a higher rank subsumes the lower ones.
const RANK: Readonly<Record<PermissionLevel, number>> = {
  ViewOnly: 0,
  Exchange: 1,
  Admin: 2,
};

// Admin is the only level that may manage membership/permissions (owner is implicitly Admin).
export const canManageMembers = (level: PermissionLevel): boolean =>
  level === "Admin";

// Exchange and Admin may transact within the circle; ViewOnly may not.
export const canExchangeWithin = (level: PermissionLevel): boolean =>
  RANK[level] >= RANK.Exchange;

src/sharing/domain/visibility-policy.ts.source:
import { CircleId, MemberId } from "./ids";
import {
  isPubliclyViewable,
  permitsTransaction,
  TransactionKind,
  VisibilityScope,
} from "./visibility-scope";

// VisibilityPolicy: the pure, circle-aware decision that unifies the 6-level model. It is a DOMAIN
// SERVICE — it loads nothing. The caller resolves the relevant circle-membership facts (which
// circles the viewer and owner BOTH belong to) and passes them in as `sharedCircles`, so the
// policy stays a total function of its inputs and free of I/O. The two questions it answers:
//
//   canView      — may `viewer` see content owned by `ownerId` at the given `scope`?
//   canTransact  — may `viewer` transact (`kind`) on that content?
//
// Semantics by scope:
//   private      → only the owner (view); nobody else, and no transaction.
//   friendCircle → viewer must share at least one circle with the owner (view); no public transact.
//   visible      → public view; no transaction.
//   lendable/swappable/tradeable → public view; transaction allowed when `kind` matches the scope.
//
// The owner can always see and transact their own content, regardless of scope.
export const VisibilityPolicy = {
  // `sharedCircles` is the set of circles the viewer and owner are BOTH members of (already
  // intersected by the caller). Its emptiness is the only friend-circle fact the policy needs.
  canView(
    viewer: MemberId,
    ownerId: MemberId,
    scope: VisibilityScope,
    sharedCircles: readonly CircleId[],
  ): boolean {
    if (viewer === ownerId) return true;
    if (scope === "private") return false;
    if (scope === "friendCircle") return sharedCircles.length > 0;
    return isPubliclyViewable(scope);
  },

  canTransact(
    viewer: MemberId,
    ownerId: MemberId,
    scope: VisibilityScope,
    sharedCircles: readonly CircleId[],
    kind: TransactionKind,
  ): boolean {
    if (viewer === ownerId) return true;
    // A transaction always presupposes the right to view; private/friendCircle/visible never
    // grant a public transaction (a friendCircle copy is shareable, not tradeable, by this policy).
    if (!this.canView(viewer, ownerId, scope, sharedCircles)) return false;
    return permitsTransaction(scope, kind);
  },
};

src/sharing/domain/visibility-scope.ts.source:
// The unified 6-level visibility model (§1.4) a copy/collection owner attaches to their content.
// Modelled as a literal union with capability helpers rather than a pile of booleans on a row —
// "sharing is a policy, not a pile of flags" (§1.1). The levels, low → high openness:
//
//   private      → only the owner sees it; nobody transacts.
//   friendCircle → only members who share a circle with the owner may see it.
//   visible      → anyone may see it, but nobody may transact (a public showcase).
//   lendable     → publicly visible; may be borrowed (Lend).
//   swappable    → publicly visible; may be swapped (Swap).
//   tradeable    → publicly visible; may be traded/sold (Trade).
export type VisibilityScope =
  | "private"
  | "friendCircle"
  | "visible"
  | "lendable"
  | "swappable"
  | "tradeable";

// The kind of transaction a viewer wants to perform. Mirrors Exchange's kinds; passed as a
// primitive so the policy can gate the higher scopes by transaction kind without importing
// Exchange. `view` is folded into canView, so this union covers only the transacting verbs.
export type TransactionKind = "lend" | "swap" | "trade";

// Scopes that grant a PUBLIC view (no circle membership required). friendCircle and private are
// deliberately absent — they are gated separately by the policy.
const PUBLICLY_VIEWABLE: ReadonlySet<VisibilityScope> = new Set([
  "visible",
  "lendable",
  "swappable",
  "tradeable",
]);

// Which transaction kind each transactable scope permits. `visible` permits viewing but no
// transaction, so it (and the non-public scopes) are absent.
const TRANSACTABLE: Readonly<
  Partial<Record<VisibilityScope, TransactionKind>>
> = {
  lendable: "lend",
  swappable: "swap",
  tradeable: "trade",
};

// True for any scope that lets a non-owner, non-circle viewer see the content.
export const isPubliclyViewable = (scope: VisibilityScope): boolean =>
  PUBLICLY_VIEWABLE.has(scope);

// True iff the scope permits the given transaction kind for anyone allowed to transact. `visible`
// and the non-public scopes never permit a transaction.
export const permitsTransaction = (
  scope: VisibilityScope,
  kind: TransactionKind,
): boolean => TRANSACTABLE[scope] === kind;

src/social/application/use-cases/approve.source:
import {
  Clock,
  DomainEvent,
  DomainEventPublisher,
  err,
  ok,
  Result,
} from "../../../shared-kernel";
import { Follow, SocialError } from "../../domain";
import { SocialApplicationError } from "../errors";
import {
  ApproveFollowRequest,
  ApproveFollowRequestCommand,
  ApproveFollowRequestResult,
} from "../ports/in/approve-follow-request.port";
import { FollowRequestRepository } from "../ports/out/follow-request.repository";
import { FollowRepository } from "../ports/out/follow.repository";
import { FollowIdGenerator } from "../ports/out/id-generators";

export interface ApproveFollowRequestDeps {
  readonly requests: FollowRequestRepository;
  readonly follows: FollowRepository;
  readonly followIds: FollowIdGenerator;
  readonly events: DomainEventPublisher;
  readonly clock: Clock;
}

// Orchestrates BOTH aggregates in one transaction: approve the request, then establish the
// requester→target Follow edge (tolerating an already-existing edge), then publish both event
// batches. The actor ACL (only the target resolves) is checked here — it needs the loaded
// aggregate, not just auth.
export const makeApproveFollowRequest =
  (deps: ApproveFollowRequestDeps): ApproveFollowRequest =>
  async (
    cmd: ApproveFollowRequestCommand,
  ): Promise<
    Result<ApproveFollowRequestResult, SocialError | SocialApplicationError>
  > => {
    const request = await deps.requests.findById(cmd.requestId);
    if (!request) return err(SocialApplicationError.requestNotFound());
    if (request.targetId !== cmd.actorId) {
      return err(SocialApplicationError.notRequestTarget());
    }

    const now = deps.clock.now();
    const approved = request.approve(now);
    if (approved.isErr) return err(approved.error);

    // Establish the edge unless a stray one already exists (duplicate-tolerant).
    const existingEdge = await deps.follows.find(
      request.requesterId,
      request.targetId,
    );
    let edgeEvents: readonly DomainEvent[] = [];
    if (!existingEdge) {
      const edge = Follow.establish({
        id: deps.followIds.next(),
        followerId: request.requesterId,
        followeeId: request.targetId,
        now,
      });
      if (edge.isErr) return err(edge.error);
      await deps.follows.save(edge.value);
      edgeEvents = edge.value.pullEvents();
    }

    await deps.requests.save(request);
    await deps.events.publish([...request.pullEvents(), ...edgeEvents]);

    const alreadyFollowsBack =
      (await deps.follows.find(request.targetId, request.requesterId)) !== null;
    return ok({ requesterId: request.requesterId, alreadyFollowsBack });
  };

src/social/application/use-cases/arrange.source:
import {
  Clock,
  DomainEventPublisher,
  err,
  ok,
  Result,
} from "../../../shared-kernel";
import { SocialError } from "../../domain";
import { SocialApplicationError } from "../errors";
import {
  ArrangeShelf,
  ArrangeShelfCommand,
} from "../ports/in/arrange-shelf.port";
import { ProfileRepository } from "../ports/out/profile.repository";

export interface ArrangeShelfDeps {
  readonly profiles: ProfileRepository;
  readonly events: DomainEventPublisher;
  readonly clock: Clock;
}

// Transaction script: load the member's profile (ProfileNotFound if absent), delegate the
// shelf-arrangement to Profile.arrangeShelf, save, then publish ProfileShelfArranged. Creating
// a profile is a separate flow; this use case only curates an existing one.
export const makeArrangeShelf =
  (deps: ArrangeShelfDeps): ArrangeShelf =>
  async (
    cmd: ArrangeShelfCommand,
  ): Promise<Result<void, SocialError | SocialApplicationError>> => {
    const profile = await deps.profiles.findByMember(cmd.memberId);
    if (!profile) {
      return err(SocialApplicationError.profileNotFound(cmd.memberId));
    }

    // arrangeShelf always succeeds — no domain validation can fail beyond type safety.
    profile.arrangeShelf(cmd.copyIds, deps.clock.now());

    await deps.profiles.save(profile);
    await deps.events.publish(profile.pullEvents());

    return ok(undefined);
  };

src/social/application/use-cases/cancel-.source:
import { Clock, err, ok, Result } from "../../../shared-kernel";
import { SocialApplicationError } from "../errors";
import {
  CancelFollowRequest,
  CancelFollowRequestCommand,
} from "../ports/in/cancel-follow-request.port";
import { FollowRequestRepository } from "../ports/out/follow-request.repository";

export interface CancelFollowRequestDeps {
  readonly requests: FollowRequestRepository;
  readonly clock: Clock;
}

// Withdrawing a request. A still-pending (or stale approved) request is removed outright:
// nothing subscribes to a cancellation and a removed row lets the requester re-request
// immediately. A DECLINED-in-cooldown request must NOT be destroyed — that would defeat the
// silent-decline cooldown — so instead it is stamped cancelledAt (row retained): the read side
// stops masking it as pending, and a re-request inside the cooldown silently resumes the mask.
// The aggregate's status guard decides which path applies. A cancelled decline then answers
// RequestNotFound, to anyone, exactly like a removed pending request, so a second cancel cannot
// tell the requester which path the first one took (SEC-39).
export const makeCancelFollowRequest =
  (deps: CancelFollowRequestDeps): CancelFollowRequest =>
  async (
    cmd: CancelFollowRequestCommand,
  ): Promise<Result<void, SocialApplicationError>> => {
    const request = await deps.requests.findById(cmd.requestId);
    if (!request || request.isCancelled) {
      return err(SocialApplicationError.requestNotFound());
    }
    if (request.requesterId !== cmd.actorId) {
      return err(SocialApplicationError.notRequestOwner());
    }
    const marked = request.markCancelledWhileDeclined(deps.clock.now());
    if (marked.isOk) {
      // Declined-in-cooldown: retain the row with the cancelled mark set.
      await deps.requests.save(request);
    } else {
      // Pending or stale approved: no cooldown record to preserve, so remove outright.
      await deps.requests.remove(request);
    }
    return ok(undefined);
  };

