src/social/domain/activity-feed.ts.source:
// The activity feed read model: a pure projection that folds activity events into a feed sorted
// newest-first. The source events (CompletionRecorded, CopyAcquired, ExchangeCompleted) are
// owned by OTHER contexts, so Social keeps its OWN local anti-corruption shape (ActivityEntry)
// and never depends on those foreign event types. Pure and total — no ports, no I/O.

import { MemberId } from "./ids";

// The kinds of activity Social surfaces in a feed, translated from foreign events at the seam.
// "started" (CompletionStarted) is opt-in + friends-only — that policy lives at the read seam
// (getActivityFeed), not here; the projection stays pure. "acquisitionBatch" is one batch add
// (several CopyAcquired events sharing a batch id) folded into a single entry; its ref is the batch
// id, and it sorts at the batch time like any other entry.
export type ActivityKind =
  "completion" | "acquisition" | "acquisitionBatch" | "exchange" | "started";

// Social's local, anti-corruption view of one piece of activity. `ref` is an opaque pointer back
// to the originating record (e.g. a completion or exchange id) for the UI to deep-link; Social
// does not interpret it.
export interface ActivityEntry {
  readonly memberId: MemberId;
  readonly kind: ActivityKind;
  readonly occurredAt: Date;
  readonly ref: string;
}

export interface BuildActivityFeedOptions {
  // Cap the feed length, keeping the newest entries. Omit for the full feed.
  readonly limit?: number;
}

// Sort entries newest-first and optionally cap the length. Stable for equal timestamps (input
// order is preserved among ties) and total — empty input yields an empty feed.
export const buildActivityFeed = (
  entries: readonly ActivityEntry[],
  options: BuildActivityFeedOptions = {},
): readonly ActivityEntry[] => {
  const sorted = [...entries].sort(
    (a, b) => b.occurredAt.getTime() - a.occurredAt.getTime(),
  );
  return options.limit === undefined ? sorted : sorted.slice(0, options.limit);
};

src/social/domain/comment-rating.ts.source:
import { err, ok, Result } from "../../shared-kernel";
import { SocialError } from "./errors";

// The lowest and highest stars a member may attach to a community comment.
const MIN_STARS = 1;
const MAX_STARS = 5;

// An optional 1–5 star rating value object for a community Comment. Declared independently of
// Solving's StarRating (the boundary passes primitives, so the two structurally identical classes
// never cross) so Social validates its own input without depending on another context.
export class CommentRating {
  private constructor(readonly value: number) {}

  static create(value: number): Result<CommentRating, SocialError> {
    if (!Number.isInteger(value) || value < MIN_STARS || value > MAX_STARS) {
      return err(SocialError.invalidCommentRating(value));
    }
    return ok(new CommentRating(value));
  }

  // Rehydrate a persisted value that was already validated when first stored.
  static fromState(value: number): CommentRating {
    return new CommentRating(value);
  }

  equals(other: CommentRating): boolean {
    return this.value === other.value;
  }
}

