import { Clock, DomainEventPublisher, err, ok } from "../../../shared-kernel";
import { CompletionDeleted, SolvingError } from "../../domain";
import { SolvingApplicationError } from "../errors";
import {
  DeleteCompletion,
  DeleteCompletionCommand,
} from "../ports/in/delete-completion.port";
import { CompletionRepository } from "../ports/out/completion.repository";

export interface DeleteCompletionDeps {
  readonly completions: CompletionRepository;
  readonly events: DomainEventPublisher;
  readonly clock: Clock;
}

// Transaction script: load (→ CompletionNotFound), guard ownership (→ NotCompletionOwner), delete,
// publish CompletionDeleted so the goal-progress reactor recomputes the member's derived progress.
export const makeDeleteCompletion =
  (deps: DeleteCompletionDeps): DeleteCompletion =>
  async (cmd: DeleteCompletionCommand) => {
    const completion = await deps.completions.findById(cmd.completionId);
    if (!completion) {
      return err(SolvingApplicationError.completionNotFound(cmd.completionId));
    }

    if (completion.userId !== cmd.actingMemberId) {
      return err(SolvingError.notCompletionOwner());
    }

    await deps.completions.delete(cmd.completionId);
    await deps.events.publish([
      new CompletionDeleted(
        cmd.completionId,
        completion.userId,
        deps.clock.now(),
      ),
    ]);
    return ok(undefined);
  };

import { err, ok } from "../../../shared-kernel";
import { SolvingApplicationError } from "../errors";
import {
  DeleteCopyReview,
  DeleteCopyReviewCommand,
} from "../ports/in/delete-copy-review.port";
import { CopyReviewRepository } from "../ports/out/review.repositories";

export interface DeleteCopyReviewDeps {
  readonly copyReviews: CopyReviewRepository;
}

// Transaction script: remove the acting member's single star review of the copy outright (no
// tombstone). The copy page computes its average from the remaining reviews on read, so nothing
// else changes and no event is published.
export const makeDeleteCopyReview =
  (deps: DeleteCopyReviewDeps): DeleteCopyReview =>
  async (cmd: DeleteCopyReviewCommand) => {
    const removed = await deps.copyReviews.remove(
      cmd.actingMemberId,
      cmd.copyId,
    );
    if (!removed) {
      return err(SolvingApplicationError.copyReviewNotFound(cmd.copyId));
    }
    return ok(undefined);
  };

import { err, ok } from "../../../shared-kernel";
import { DeleteGoal, DeleteGoalCommand } from "../ports/in/delete-goal.port";
import { GoalRepository } from "../ports/out/goal.repository";
import { loadOwnedGoal } from "./owned-goal";

export interface DeleteGoalDeps {
  readonly goals: GoalRepository;
}

// Transaction script: load the acting member's own goal (GoalNotFound / NotGoalOwner) and delete
// it for good. Nothing else references a goal's progress; a goal_achieved notification about it
// simply resolves as unavailable afterwards.
export const makeDeleteGoal =
  (deps: DeleteGoalDeps): DeleteGoal =>
  async (cmd: DeleteGoalCommand) => {
    const goal = await loadOwnedGoal(
      deps.goals,
      cmd.goalId,
      cmd.actingMemberId,
    );
    if (goal.isErr) return err(goal.error);

    await deps.goals.delete(goal.value.id);
    return ok(undefined);
  };

import { err, ok } from "../../../shared-kernel";
