import { DomainEvent, err, ok, Result } from "../../shared-kernel";
import {
  DatePrecision,
  isPossibleSolveDate,
  MIN_SOLVE_YEAR,
  yearSentinel,
} from "./date-precision";
import { SolvingError } from "./errors";
import {
  CompletionEdited,
  CompletionRecorded,
  CompletionStarted,
} from "./events";
import { CompletionId, CopyId, MemberId, PuzzleDefinitionId } from "./ids";
import { Photo } from "./photo";
import {
  isSpanLongerThanAnySolve,
  MINUTES_PER_DAY,
  SolveDuration,
} from "./solve-duration";

// A completion may hold at most five photos (§1.4).
export const MAX_PHOTOS = 5;

// The longest a solve's notes may be. Checked where notes are written, never on rehydrate.
export const MAX_SOLVE_NOTES_LENGTH = 5_000;

// Edits are only allowed within this window. It is anchored on the solve's end date (see
// completionEditableUntil), which is a calendar date stored as UTC midnight, so a back-dated or
// year-only solve is closed as soon as it is logged.
export const EDIT_WINDOW_MS = 24 * 60 * 60 * 1000;

// A solve date is the member's local calendar date stored as UTC midnight, so their "today" can be
// up to 14 hours ahead of the UTC clock (UTC+14). Anything later is a day that hasn't come anywhere.
const LATEST_LOCAL_TODAY_MS = 14 * 60 * 60 * 1000;

const isAfterToday = (date: Date, now: Date): boolean =>
  date.getTime() > now.getTime() + LATEST_LOCAL_TODAY_MS;

// Input to start(): an in-progress solve (no end yet).
export interface StartCompletionProps {
  readonly id: CompletionId;
  readonly userId: MemberId;
  readonly puzzleDefinitionId?: PuzzleDefinitionId;
  readonly copyId?: CopyId;
  readonly startDate: Date;
  readonly notes?: string;
  readonly photos?: readonly Photo[];
  readonly allPiecesPresent?: boolean;
  readonly now: Date;
}

// Input to record(): an already-finished solve logged after the fact. The date fields depend on
// the precision: "day" needs startDate + endDate, "year" needs year, "unknown" takes neither (the
// sentinel dates are computed here, never supplied).
export interface RecordCompletionProps {
  readonly id: CompletionId;
  readonly userId: MemberId;
  readonly puzzleDefinitionId?: PuzzleDefinitionId;
  readonly copyId?: CopyId;
  readonly datePrecision: DatePrecision;
  readonly startDate?: Date;
  readonly endDate?: Date;
  readonly year?: number;
  // If omitted, the duration is derived from start/end. Refused for "year" and "unknown".
  readonly completionTimeMinutes?: number;
  readonly notes?: string;
  readonly photos?: readonly Photo[];
  readonly allPiecesPresent?: boolean;
  // Logged as part of a batch backfill; carried on CompletionRecorded so the feed can skip it.
  readonly bulk?: boolean;
  readonly now: Date;
}

// The persistable shape, kept close to the `completions` columns so the 2c mapper is a
// near field-for-field translation:
//   userId, puzzleId→puzzleDefinitionId, ownedPuzzleId→copyId, startDate, endDate,
//   completionTimeMinutes, notes, photos[], isCompleted, createdAt, updatedAt.
export interface CompletionState {
  readonly id: CompletionId;
  readonly userId: MemberId;
  readonly puzzleDefinitionId?: PuzzleDefinitionId;
  readonly copyId?: CopyId;
  readonly startDate: Date;
  readonly endDate?: Date;
  readonly completionTimeMinutes?: number;
  readonly notes?: string;
  readonly photos: readonly Photo[];
  readonly allPiecesPresent?: boolean;
  readonly isCompleted: boolean;
  // "year"/"unknown" rows hold sentinel dates and no duration (see record()).
  readonly datePrecision: DatePrecision;
  readonly createdAt: Date;
  readonly updatedAt: Date;
}

// Changes accepted by edit(). An undefined field leaves the current value untouched.
export interface CompletionChanges {
  // An empty string clears the note.
  readonly notes?: string;
  readonly photos?: readonly Photo[];
  readonly startDate?: Date;
  readonly endDate?: Date;
  readonly completionTimeMinutes?: number;
}

// The last instant a completion may still be edited, or undefined when it has no deadline (a
// solve in progress is always editable). The single source of the edit-window rule: edit()
// enforces it and the read side reports it, so the UI never offers an edit the server refuses.
export function completionEditableUntil(
  state: Pick<CompletionState, "isCompleted" | "endDate" | "updatedAt">,
): Date | undefined {
  if (!state.isCompleted) return undefined;
  const reference = state.endDate ?? state.updatedAt;
  return new Date(reference.getTime() + EDIT_WINDOW_MS);
}

// The Completion aggregate root (a SolveSession): a member's record of solving one puzzle. It
// references the puzzle by id (a PuzzleDefinitionId and/or a CopyId) and never loads those
// aggregates. It can be in-progress (no end, isCompleted=false) or done (end + duration).
//
// Invariants: a new completion names a puzzle definition or a copy (at least one, so a solve
// can't be logged against nothing; SEC-30); its dates are ones a solve can have (checked where they
// are supplied, so a row that predates that stays editable); endDate ≥ startDate and not after today;
// the duration is consistent with the recorded end; at most five photos; edits only within 24h of completion (photo attachment is
// exempt — see attachPhotos).
export class Completion {
  private events: DomainEvent[] = [];

  private constructor(private state: CompletionState) {}

  get id(): CompletionId {
    return this.state.id;
  }

  get userId(): MemberId {
    return this.state.userId;
  }

  get isCompleted(): boolean {
    return this.state.isCompleted;
  }

  get photos(): readonly Photo[] {
    return this.state.photos;
  }

  // See completionEditableUntil: undefined while in progress.
  get editableUntil(): Date | undefined {
    return completionEditableUntil(this.state);
  }

  // Begin an in-progress solve. No end/duration yet; records CompletionStarted.
  static start(props: StartCompletionProps): Result<Completion, SolvingError> {
    if (!props.puzzleDefinitionId && !props.copyId) {
      return err(SolvingError.targetRequired());
    }
    if (!isPossibleSolveDate(props.startDate, props.now)) {
      return err(SolvingError.invalidSolveDate());
    }
    if ((props.notes?.length ?? 0) > MAX_SOLVE_NOTES_LENGTH) {
      return err(SolvingError.notesTooLong(MAX_SOLVE_NOTES_LENGTH));
    }
    const photos = props.photos ?? [];
    if (photos.length > MAX_PHOTOS) {
      return err(SolvingError.tooManyPhotos(MAX_PHOTOS));
    }

    const completion = new Completion({
      id: props.id,
      userId: props.userId,
      puzzleDefinitionId: props.puzzleDefinitionId,
      copyId: props.copyId,
      startDate: props.startDate,
      notes: props.notes,
      photos,
      allPiecesPresent: props.allPiecesPresent,
      isCompleted: false,
      datePrecision: "day",
      createdAt: props.now,
      updatedAt: props.now,
    });
    completion.record(
      new CompletionStarted(
        props.id,
        props.userId,
        props.puzzleDefinitionId,
        props.copyId,
        props.startDate,
        props.now,
      ),
    );
    return ok(completion);
  }

  // Log an already-finished solve. Enforces dates that match the precision, endDate ≥ startDate,
  // the photo cap, and a duration consistent with start/end; records CompletionRecorded. A
  // "year"/"unknown" solve gets sentinel dates (start = end) and no duration: the same-day
  // one-day derivation would invent a solve time.
  static record(
    props: RecordCompletionProps,
  ): Result<Completion, SolvingError> {
    if (!props.puzzleDefinitionId && !props.copyId) {
      return err(SolvingError.targetRequired());
    }
    const dates = Completion.resolveRecordDates(props);
    if (dates.isErr) return err(dates.error);
    const { startDate, endDate } = dates.value;
    if ((props.notes?.length ?? 0) > MAX_SOLVE_NOTES_LENGTH) {
      return err(SolvingError.notesTooLong(MAX_SOLVE_NOTES_LENGTH));
    }

    const photos = props.photos ?? [];
    if (photos.length > MAX_PHOTOS) {
      return err(SolvingError.tooManyPhotos(MAX_PHOTOS));
    }

    let minutes: number | undefined;
    if (props.datePrecision === "day") {
      const duration = Completion.resolveDuration(
        startDate,
        endDate,
        props.completionTimeMinutes,
      );
      if (duration.isErr) return err(duration.error);
      minutes = duration.value;
    } else if (props.completionTimeMinutes !== undefined) {
      return err(SolvingError.durationNotAllowed());
    }

    const completion = new Completion({
      id: props.id,
      userId: props.userId,
      puzzleDefinitionId: props.puzzleDefinitionId,
      copyId: props.copyId,
      startDate,
      endDate,
      completionTimeMinutes: minutes,
      notes: props.notes,
      photos,
      allPiecesPresent: props.allPiecesPresent,
      isCompleted: true,
      datePrecision: props.datePrecision,
      createdAt: props.now,
      updatedAt: props.now,
    });
    completion.record(
      new CompletionRecorded(
        props.id,
        props.userId,
        props.puzzleDefinitionId,
        props.copyId,
        startDate,
        endDate,
        minutes,
        props.now,
        props.datePrecision,
        props.bulk,
      ),
    );
    return ok(completion);
  }

  // Finish an in-progress completion. Idempotent guard: finishing an already-finished completion
  // is treated as a no-op so a double-submit can't double-emit CompletionRecorded.
  finish(
    endDate: Date,
    now: Date,
    completionTimeMinutes?: number,
    allPiecesPresent?: boolean,
  ): Result<void, SolvingError> {
    if (this.state.isCompleted) return ok(undefined);
    if (!isPossibleSolveDate(endDate, now)) {
      return err(SolvingError.invalidSolveDate());
    }
    if (endDate.getTime() < this.state.startDate.getTime()) {
      return err(SolvingError.invalidTimeRange());
    }
    if (isAfterToday(endDate, now)) return err(SolvingError.futureEndDate());
    const duration = Completion.resolveDuration(
      this.state.startDate,
      endDate,
      completionTimeMinutes,
    );
    if (duration.isErr) return err(duration.error);

    this.state = {
      ...this.state,
      endDate,
      completionTimeMinutes: duration.value,
      allPiecesPresent: allPiecesPresent ?? this.state.allPiecesPresent,
      isCompleted: true,
      updatedAt: now,
    };
    this.record(
      new CompletionRecorded(
        this.state.id,
        this.state.userId,
        this.state.puzzleDefinitionId,
        this.state.copyId,
        this.state.startDate,
        endDate,
        duration.value,
        now,
      ),
    );
    return ok(undefined);
  }

  // Patch mutable fields. Allowed only within 24h of completion (EditWindowClosed otherwise) and
  // only by the owner (the use case checks ownership; this is the aggregate-level signal). An
  // undefined field in `changes` leaves the current value untouched.
  edit(
    actingMemberId: MemberId,
    changes: CompletionChanges,
    now: Date,
  ): Result<void, SolvingError> {
    if (actingMemberId !== this.state.userId) {
      return err(SolvingError.notCompletionOwner());
    }
    // The edit window (completionEditableUntil) is anchored on the recorded completion. An
    // in-progress completion has no completion instant yet, so it is always editable.
    const editableUntil = this.editableUntil;
    if (editableUntil && now.getTime() > editableUntil.getTime()) {
      return err(SolvingError.editWindowClosed());
    }

    for (const date of [changes.startDate, changes.endDate]) {
      if (date && !isPossibleSolveDate(date, now)) {
        return err(SolvingError.invalidSolveDate());
      }
    }
    if ((changes.notes?.length ?? 0) > MAX_SOLVE_NOTES_LENGTH) {
      return err(SolvingError.notesTooLong(MAX_SOLVE_NOTES_LENGTH));
    }

    // A "year"/"unknown" row's dates are sentinels, not facts. Setting a real date upgrades it to
    // "day", and a single supplied date stands in for the missing one. Without a date, it still
    // cannot take a solve time.
    const datesChanged =
      changes.startDate !== undefined || changes.endDate !== undefined;
    const undated = this.state.datePrecision !== "day";
    if (
      undated &&
      !datesChanged &&
      changes.completionTimeMinutes !== undefined
    ) {
      return err(SolvingError.durationNotAllowed());
    }
    const nextStart =
      changes.startDate ??
      (undated ? changes.endDate : undefined) ??
      this.state.startDate;
    const nextEnd =
      changes.endDate ??
      (undated ? changes.startDate : undefined) ??
      this.state.endDate;
    if (nextEnd && nextEnd.getTime() < nextStart.getTime()) {
      return err(SolvingError.invalidTimeRange());
    }
    if (datesChanged && nextEnd && isAfterToday(nextEnd, now)) {
      return err(SolvingError.futureEndDate());
    }

    const nextPhotos = changes.photos ?? this.state.photos;
    if (nextPhotos.length > MAX_PHOTOS) {
      return err(SolvingError.tooManyPhotos(MAX_PHOTOS));
    }

    let nextDuration = this.state.completionTimeMinutes;
    if (
      changes.completionTimeMinutes !== undefined ||
      changes.startDate !== undefined ||
      changes.endDate !== undefined
    ) {
      if (nextEnd) {
        const duration = Completion.resolveDuration(
          nextStart,
          nextEnd,
          changes.completionTimeMinutes,
        );
        if (duration.isErr) return err(duration.error);
        nextDuration = duration.value;
      } else if (changes.completionTimeMinutes !== undefined) {
        const duration = SolveDuration.ofMinutes(changes.completionTimeMinutes);
        if (duration.isErr) return err(duration.error);
        nextDuration = duration.value.minutes;
      }
    }

    this.state = {
      ...this.state,
      notes:
        changes.notes === undefined
          ? this.state.notes
          : changes.notes || undefined,
      photos: nextPhotos,
      startDate: nextStart,
      endDate: nextEnd,
      completionTimeMinutes: nextDuration,
      datePrecision: datesChanged ? "day" : this.state.datePrecision,
      updatedAt: now,
    };
    this.record(new CompletionEdited(this.state.id, this.state.userId, now));
    return ok(undefined);
  }

  // Append photos. Additive (never removes), owner-only, capped at MAX_PHOTOS. Deliberately NOT
  // window-gated: attaching photos is not a revision of the solve's facts, and a backdated
  // completion's endDate-anchored window is already closed at creation.
  attachPhotos(
    actingMemberId: MemberId,
    photos: readonly Photo[],
    now: Date,
  ): Result<void, SolvingError> {
    if (actingMemberId !== this.state.userId) {
      return err(SolvingError.notCompletionOwner());
    }
    const combined = [...this.state.photos, ...photos];
    if (combined.length > MAX_PHOTOS) {
      return err(SolvingError.tooManyPhotos(MAX_PHOTOS));
    }
    this.state = { ...this.state, photos: combined, updatedAt: now };
    // Reuse CompletionEdited (no feed/notification reactions; the goal reactor's recompute is a
    // no-op here because photos never move a solve); recorded exactly the way edit() records it.
    this.record(new CompletionEdited(this.state.id, this.state.userId, now));
    return ok(undefined);
  }

  // Drain recorded events for the publisher; clears the buffer so a save can't double-emit.
  pullEvents(): readonly DomainEvent[] {
    const drained = this.events;
    this.events = [];
    return drained;
  }

  // Map to/from persistence without the aggregate knowing about any storage technology.
  static rehydrate(state: CompletionState): Completion {
    return new Completion(state);
  }

  toState(): CompletionState {
    return this.state;
  }

  // --- internals ---

  // The start/end a recorded solve is stored with, per its precision (see RecordCompletionProps).
  private static resolveRecordDates(
    props: RecordCompletionProps,
  ): Result<{ startDate: Date; endDate: Date }, SolvingError> {
    const { startDate, endDate, year, now } = props;
    if (props.datePrecision === "day") {
      if (!startDate || !endDate || year !== undefined) {
        return err(SolvingError.invalidDatePrecision());
      }
      if (
        !isPossibleSolveDate(startDate, now) ||
        !isPossibleSolveDate(endDate, now)
      ) {
        return err(SolvingError.invalidSolveDate());
      }
      if (endDate.getTime() < startDate.getTime()) {
        return err(SolvingError.invalidTimeRange());
      }
      if (isAfterToday(endDate, now)) return err(SolvingError.futureEndDate());
      return ok({ startDate, endDate });
    }
    if (startDate || endDate) return err(SolvingError.invalidDatePrecision());
    if (props.datePrecision === "unknown") {
      if (year !== undefined) return err(SolvingError.invalidDatePrecision());
      return ok({ startDate: now, endDate: now });
    }
    if (year === undefined) return err(SolvingError.invalidDatePrecision());
    if (
      !Number.isInteger(year) ||
      year < MIN_SOLVE_YEAR ||
      year > now.getUTCFullYear()
    ) {
      return err(SolvingError.invalidYear(year));
    }
    const at = yearSentinel(year, now);
    return ok({ startDate: at, endDate: at });
  }

  // Reconcile a supplied duration with the start/end span. Returns the resolved minutes. An
  // explicit minutes value must be a valid SolveDuration. An explicit end-before-start is rejected
  // before this helper is called, so the only span-derived cases are start < end (actual span, with
  // no duration when it is too long to be a solve time) and start == end (date-only same-day
  // completion, no explicit time given).
  private static resolveDuration(
    start: Date,
    end: Date,
    minutes?: number,
  ): Result<number | undefined, SolvingError> {
    if (minutes !== undefined) {
      const duration = SolveDuration.ofMinutes(minutes);
      if (duration.isErr) return err(duration.error);
      return ok(duration.value.minutes);
    }
    if (isSpanLongerThanAnySolve(start, end)) return ok(undefined);
    if (end.getTime() > start.getTime()) {
      const duration = SolveDuration.between(start, end);
      if (duration.isErr) return err(duration.error);
      return ok(duration.value.minutes);
    }
    // start == end: date-only same-day completions count as one day (product decision,
    // spec 2026-07-14 Fix 4).
    return ok(MINUTES_PER_DAY);
  }

  private record(event: DomainEvent): void {
    this.events.push(event);
  }
}

