import { MemberId } from "./ids";

// A member's Solving-context preferences. Identified by memberId (one per member). Eventless:
// settings carry no domain events that other contexts react to. `trackCompletionDuration`
// undefined means the member has never chosen: the UI asks for solve times unless it is false,
// and offers to turn them off while it is undefined.
export interface SolvingPreferencesState {
  readonly memberId: MemberId;
  readonly trackCompletionDuration?: boolean;
  // undefined = never chosen. Gates the friend-facing in-progress surfaces; every consumer must
  // test `=== true` (absent behaves as off).
  readonly shareInProgress?: boolean;
  readonly updatedAt: Date;
}

export class SolvingPreferences {
  private constructor(private state: SolvingPreferencesState) {}

  get memberId(): MemberId {
    return this.state.memberId;
  }

  get trackCompletionDuration(): boolean | undefined {
    return this.state.trackCompletionDuration;
  }

  get shareInProgress(): boolean | undefined {
    return this.state.shareInProgress;
  }

  static createDefault(memberId: MemberId, now: Date): SolvingPreferences {
    return new SolvingPreferences({
      memberId,
      trackCompletionDuration: undefined,
      shareInProgress: undefined,
      updatedAt: now,
    });
  }

  setTrackCompletionDuration(enabled: boolean, now: Date): void {
    if (this.state.trackCompletionDuration === enabled) return;
    this.state = {
      ...this.state,
      trackCompletionDuration: enabled,
      updatedAt: now,
    };
  }

  setShareInProgress(enabled: boolean, now: Date): void {
    if (this.state.shareInProgress === enabled) return;
    this.state = { ...this.state, shareInProgress: enabled, updatedAt: now };
  }

  static rehydrate(state: SolvingPreferencesState): SolvingPreferences {
    return new SolvingPreferences(state);
  }

  toState(): SolvingPreferencesState {
    return this.state;
  }
}

src/solving/domain/star-rating.ts.source:
import { err, ok, Result } from "../../shared-kernel";
import { SolvingError } from "./errors";

// The lowest and highest stars a member may award a puzzle.
const MIN_STARS = 1;
const MAX_STARS = 5;

// A 1–5 star rating value object, reused by PuzzleReview. A rating is the member's opinion of
// the PUZZLE (difficulty/quality), not of a trading partner — see the §1.5 homonym table.
export class StarRating {
  private constructor(readonly value: number) {}

  static create(value: number): Result<StarRating, SolvingError> {
    if (!Number.isInteger(value) || value < MIN_STARS || value > MAX_STARS) {
      return err(SolvingError.invalidRating(value));
    }
    return ok(new StarRating(value));
  }

  // Rehydrate a persisted value that was already validated when first stored.
  static fromState(value: number): StarRating {
    return new StarRating(value);
  }

  equals(other: StarRating): boolean {
    return this.value === other.value;
  }
}

src/whats-new/domain/unread.ts.source:
// What's new read rule. An entry is unread for a member when it was published after their account
// was created (older entries count as read: they appear in the list but never as "new") and the
// member has not seen it yet. The seen set holds entry ids; `publishedAt`/`memberCreatedAt` are
// epoch ms.

export interface WhatsNewEntryRef {
  readonly id: string;
  readonly publishedAt: number;
}

export interface WhatsNewReader {
  readonly memberCreatedAt: number;
  readonly seenIds: Iterable<string>;
}

// Ids of the unread entries, in the order given (the manifest is newest first).
export const unreadWhatsNewEntryIds = (
  entries: readonly WhatsNewEntryRef[],
  reader: WhatsNewReader,
): string[] => {
  const seen = new Set(reader.seenIds);
  return entries
    .filter(
      (entry) =>
        entry.publishedAt > reader.memberCreatedAt && !seen.has(entry.id),
    )
    .map((entry) => entry.id);
};

src/catalog/domain/approval.ts.source:
// Moderation lifecycle of a PuzzleDefinition. Only `approved` definitions are publicly
// listable (an application-layer query concern); the aggregate owns the transitions.
export type ApprovalStatus = "pending" | "approved" | "rejected" | "disabled";

// Legal approval moves. A submission starts `pending`; moderation decides it once. An
// approved definition may be reversibly disabled (hidden from public surfaces) and
// re-enabled; `rejected` stays terminal (re-submission would be a new definition).
export const ALLOWED_APPROVAL_TRANSITIONS: Readonly<
  Record<ApprovalStatus, readonly ApprovalStatus[]>
> = {
  pending: ["approved", "rejected"],
  approved: ["disabled"],
  disabled: ["approved"],
  rejected: [],
};

// The statuses in which a definition HOLDS its barcodes: while one exists, no other definition
// may carry the same EAN/UPC/model number. A rejected definition releases them, because
// rejection is terminal (the row can never be listed again) and a held barcode would let junk
// submissions squat real products. Pending holds until an admin decides; disabled was moderated
// once and may be re-enabled, so it keeps its barcodes.
export const BARCODE_HOLDING_STATUSES: readonly ApprovalStatus[] = [
  "pending",
  "approved",
  "disabled",
];

src/catalog/domain/proposal-status.ts.source:
// Lifecycle of a PuzzleChangeProposal. A member files it `pending`; an admin decides it once
// (approved/rejected) or the proposer withdraws it. All non-pending states are terminal —
// a member who wants to try again files a NEW proposal.
export type ProposalStatus = "pending" | "approved" | "rejected" | "withdrawn";

export const ALLOWED_PROPOSAL_TRANSITIONS: Readonly<
  Record<ProposalStatus, readonly ProposalStatus[]>
> = {
  pending: ["approved", "rejected", "withdrawn"],
  approved: [],
  rejected: [],
  withdrawn: [],
};

src/exchange/domain/exchange-kind.ts.source:
// The ubiquitous language of the Exchange context. Each kind carries a distinct
// term requirement (see terms.ts):
//   - swap: puzzle-for-puzzle; the initiator must offer one of their own copies.
//   - sale: money changes hands; a price is required.
//   - lend: temporary transfer; a return date is required.
export type ExchangeKind = "swap" | "sale" | "lend";

// Legacy persisted mapping (the `exchanges.type` column uses the older vocabulary).
// The 1b adapter/mapper translates between these; the domain only speaks the new terms.
//   swap <-> "trade"
//   sale <-> "sale"
//   lend <-> "loan"
export type LegacyExchangeKind = "trade" | "sale" | "loan";

export const EXCHANGE_KINDS: readonly ExchangeKind[] = ["swap", "sale", "lend"];

