import { PuzzleDefinitionId } from "./ids";

// The ACL cache of the Catalog product. This is the ONLY thing a Copy knows about the
// product it instantiates: a denormalised, immutable snapshot taken at acquisition (and
// refreshable via the CatalogSnapshotProvider port). The Library keeps working if the
// Catalog evolves because it never reaches into Catalog tables. (proposal §1.3 relationship 2)
export class CatalogSnapshot {
  private constructor(
    readonly puzzleDefinitionId: PuzzleDefinitionId,
    readonly title: string,
    readonly pieceCount: number,
    readonly brand?: string,
    readonly thumbnail?: string,
  ) {}

  static create(props: {
    readonly puzzleDefinitionId: PuzzleDefinitionId;
    readonly title: string;
    readonly pieceCount: number;
    readonly brand?: string;
    readonly thumbnail?: string;
  }): CatalogSnapshot {
    return new CatalogSnapshot(
      props.puzzleDefinitionId,
      props.title,
      props.pieceCount,
      props.brand,
      props.thumbnail,
    );
  }
}

src/library/domain/condition.ts.source:
// The grading of a physical Copy, matching the persisted `ownedPuzzles.condition` column
// 1:1 (no legacy translation needed). Ordered best→worst so a future condition timeline can
// reason about deterioration.
//   new_sealed -> factory sealed, never opened
//   like_new   -> opened but perfect
//   good / fair / poor -> increasing wear
export type Condition = "new_sealed" | "like_new" | "good" | "fair" | "poor";

export const CONDITIONS: readonly Condition[] = [
  "new_sealed",
  "like_new",
  "good",
  "fair",
  "poor",
];

export const isCondition = (value: string): value is Condition =>
  (CONDITIONS as readonly string[]).includes(value);

