      startDate: tenDaysAgo,
      endDate: tenDaysAgo,
      now: tenDaysAgo,
    });
    if (!recorded.isOk) throw new Error("setup failed");
    const outcome = recorded.value.attachPhotos(ALICE, photos(1), NOW);
    expect(outcome.isOk).toBe(true);
    expect(recorded.value.photos).toHaveLength(1);
  });
});

