    expect(result.isOk).toBe(true);
    if (!result.isOk) return;
    expect(result.value.toState().allPiecesPresent).toBe(true);
  });

  it("finish() sets allPiecesPresent when provided and leaves it otherwise", () => {
    const started = Completion.start({
      id: ID,
      userId: ALICE,
      puzzleDefinitionId: PUZZLE,
      startDate: START,
      now: NOW,
    });
    expect(started.isOk).toBe(true);
    if (!started.isOk) return;
    const c = started.value;
    const outcome = c.finish(END, NOW, undefined, true);
    expect(outcome.isOk).toBe(true);
    expect(c.toState().allPiecesPresent).toBe(true);
  });
});

describe("Completion round-trip", () => {
  it("rehydrates from state without re-emitting events", () => {
    const recorded = recordValid();
    if (!recorded.isOk) throw new Error("setup failed");
    const state = recorded.value.toState();
    const rehydrated = Completion.rehydrate(state);
    expect(rehydrated.toState()).toEqual(state);
    expect(rehydrated.pullEvents()).toEqual([]);
  });
});

// NaN, Infinity and far-off instants used to be stored as they came, and every member who reads the
// solve gets them back. new Date() turns all of them into dates nobody can have solved a puzzle on.
describe("a solve's dates are dates a solve can have", () => {
  const impossible = [
    new Date(Number.NaN),
    new Date(Number.POSITIVE_INFINITY),
    new Date(1e30),
    new Date(-1e15),
    new Date(Date.UTC(1899, 11, 31)),
    new Date(NOW.getTime() + 367 * 24 * 60 * 60 * 1000),
  ];

  it.each(impossible)("start() refuses %s", (startDate) => {
    const r = Completion.start({
      id: ID,
      userId: ALICE,
      puzzleDefinitionId: PUZZLE,
      startDate,
      now: NOW,
    });
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("InvalidSolveDate");
  });

  it.each(impossible)("record() refuses a start of %s", (startDate) => {
    const r = recordValid({ startDate, endDate: startDate });
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("InvalidSolveDate");
  });

  it.each(impossible)("record() refuses an end of %s", (endDate) => {
    const r = recordValid({
      startDate: new Date(Date.UTC(1900, 0, 1)),
      endDate,
    });
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("InvalidSolveDate");
  });

  it.each(impossible)("finish() refuses an end of %s", (endDate) => {
    const started = Completion.start({
      id: ID,
      userId: ALICE,
      puzzleDefinitionId: PUZZLE,
      startDate: new Date(Date.UTC(1900, 0, 1)),
      now: NOW,
    });
    if (!started.isOk) throw new Error("setup failed");
    const r = started.value.finish(endDate, NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("InvalidSolveDate");
    expect(started.value.isCompleted).toBe(false);
  });

  it.each(impossible)("edit() refuses %s, either way round", (date) => {
    const started = Completion.start({
      id: ID,
      userId: ALICE,
      puzzleDefinitionId: PUZZLE,
      startDate: START,
      now: NOW,
    });
    if (!started.isOk) throw new Error("setup failed");
    for (const changes of [{ startDate: date }, { endDate: date }]) {
      const r = started.value.edit(ALICE, changes, NOW);
      expect(r.isErr).toBe(true);
      if (r.isErr) expect(r.error.code).toBe("InvalidSolveDate");
    }
  });

  // A year ahead is only ever a start: a finish can't lie after today (FutureEndDate, below).
  it("accepts the first day of 1900, today, and a start a year ahead", () => {
    for (const startDate of [new Date(Date.UTC(1900, 0, 1)), NOW]) {
      expect(recordValid({ startDate, endDate: startDate }).isOk).toBe(true);
    }
    const started = Completion.start({
      id: ID,
      userId: ALICE,
      puzzleDefinitionId: PUZZLE,
      startDate: new Date(NOW.getTime() + 365 * 24 * 60 * 60 * 1000),
      now: NOW,
    });
    expect(started.isOk).toBe(true);
  });

  it("a stored row that predates the bound can still be edited in its other fields", () => {
    const completion = Completion.rehydrate({
      id: ID,
      userId: ALICE,
      puzzleDefinitionId: PUZZLE,
      startDate: new Date(Number.NaN),
      photos: [],
      isCompleted: false,
      datePrecision: "day",
      createdAt: NOW,
      updatedAt: NOW,
    });
    expect(completion.edit(ALICE, { notes: "Fixed" }, NOW).isOk).toBe(true);
    // And its date can be put right.
    expect(completion.edit(ALICE, { startDate: START }, NOW).isOk).toBe(true);
  });
});

describe("a solve's notes are bounded", () => {
  const tooLong = "x".repeat(MAX_SOLVE_NOTES_LENGTH + 1);

  it("start and record refuse longer notes and take the longest", () => {
    const start = (notes: string) =>
      Completion.start({
        id: ID,
        userId: ALICE,
        puzzleDefinitionId: PUZZLE,
        startDate: START,
        notes,
        now: NOW,
      });
    const refused = [start(tooLong), recordValid({ notes: tooLong })];
    for (const r of refused) {
      expect(r.isErr).toBe(true);
      if (r.isErr) expect(r.error.code).toBe("NotesTooLong");
    }
    const longest = "x".repeat(MAX_SOLVE_NOTES_LENGTH);
    expect(start(longest).isOk).toBe(true);
    expect(recordValid({ notes: longest }).isOk).toBe(true);
  });

  it("edit refuses longer notes and keeps the stored ones", () => {
    const r = recordValid({ notes: "fun" });
    if (!r.isOk) throw new Error("setup failed");
    const edited = r.value.edit(ALICE, { notes: tooLong }, NOW);
    expect(edited.isErr).toBe(true);
    if (edited.isErr) expect(edited.error.code).toBe("NotesTooLong");
    expect(r.value.toState().notes).toBe("fun");
  });
});

// A finish can't lie in the future: it would count toward "this year" and goals before it happened.
// Solve dates are the member's local calendar date stored as UTC midnight, so "today" can be up to
// 14 hours ahead of the UTC clock (UTC+14) and must still pass. A start in the future stays allowed:
// a planned solve in progress has no finish yet.
describe("Completion: a finish date in the future", () => {
  const CLOCK = new Date("2026-06-01T10:00:00Z");
  const TODAY_AT_UTC_PLUS_14 = new Date("2026-06-02T00:00:00Z");
  const DAY_AFTER = new Date("2026-06-03T00:00:00Z");

  const finishable = () => {
    const started = Completion.start({
      id: ID,
      userId: ALICE,
      puzzleDefinitionId: PUZZLE,
      startDate: new Date("2026-05-30T00:00:00Z"),
      now: CLOCK,
    });
    if (!started.isOk) throw new Error("setup failed");
    return started.value;
  };

  it("record refuses it", () => {
    const result = recordValid({
      startDate: new Date("2026-05-30T00:00:00Z"),
      endDate: DAY_AFTER,
      now: CLOCK,
    });
    expect(result.isErr && result.error.code).toBe("FutureEndDate");
  });

  it("record accepts today on the calendar furthest ahead of UTC", () => {
    const result = recordValid({
      startDate: TODAY_AT_UTC_PLUS_14,
      endDate: TODAY_AT_UTC_PLUS_14,
      now: CLOCK,
    });
    expect(result.isOk).toBe(true);
  });

  it("finish refuses it", () => {
    const outcome = finishable().finish(DAY_AFTER, CLOCK);
    expect(outcome.isErr && outcome.error.code).toBe("FutureEndDate");
  });

  it("finish accepts today on the calendar furthest ahead of UTC", () => {
    expect(finishable().finish(TODAY_AT_UTC_PLUS_14, CLOCK).isOk).toBe(true);
  });

  it("edit refuses moving the end into it", () => {
    const recorded = recordValid({
      startDate: new Date("2026-05-30T00:00:00Z"),
      endDate: new Date("2026-06-01T00:00:00Z"),
      now: CLOCK,
    });
    if (!recorded.isOk) throw new Error("setup failed");
    const outcome = recorded.value.edit(ALICE, { endDate: DAY_AFTER }, CLOCK);
    expect(outcome.isErr && outcome.error.code).toBe("FutureEndDate");
  });

  it("start still accepts a start date in the future", () => {
    const started = Completion.start({
      id: ID,
      userId: ALICE,
      puzzleDefinitionId: PUZZLE,
      startDate: DAY_AFTER,
      now: CLOCK,
    });
    expect(started.isOk).toBe(true);
  });

  it("edit still lets an in-progress solve move its start into the future", () => {
    const outcome = finishable().edit(ALICE, { startDate: DAY_AFTER }, CLOCK);
    expect(outcome.isOk).toBe(true);
  });
});

