import { describe, expect, it } from "vitest";
import {
  DomainEvent,
  toCatalogCategoryId,
  toPuzzleDefinitionId,
  toSubmitterId,
} from "../../shared-kernel";
import { ALLOWED_APPROVAL_TRANSITIONS } from "./approval";
import { PuzzleDefinitionRejected, PuzzleDefinitionSubmitted } from "./events";
import { MAX_DIMENSION, MAX_PIECE_COUNT } from "./piece-count";
import {
  PuzzleDefinition,
  SubmitPuzzleDefinitionProps,
} from "./puzzle-definition";

const id = toPuzzleDefinitionId("pd1");
const submitter = toSubmitterId("alice");
const NOW = new Date("2026-06-08T10:00:00Z");
const LATER = new Date("2026-06-09T10:00:00Z");

const names = (events: readonly DomainEvent[]): string[] =>
  events.map((e) => e.name);

const submit = (
  overrides: Partial<SubmitPuzzleDefinitionProps> = {},
): PuzzleDefinition => {
  const r = PuzzleDefinition.submit({
    id,
    title: "Starry Night",
    pieceCount: 1000,
    submittedBy: submitter,
    now: NOW,
    ...overrides,
  });
  if (!r.isOk) throw new Error(`setup failed: ${r.error.message}`);
  return r.value;
};

describe("PuzzleDefinition.submit", () => {
  it("starts pending and records PuzzleDefinitionSubmitted with the submitter", () => {
    const def = submit();
    expect(def.status).toBe("pending");
    const events = def.pullEvents();
    expect(names(events)).toEqual(["PuzzleDefinitionSubmitted"]);
    const submitted = events[0] as PuzzleDefinitionSubmitted;
    expect(submitted.submittedBy).toBe(submitter);
    expect(submitted.occurredAt).toBe(NOW);
  });

  it("trims the title and rejects a blank one", () => {
    expect(submit({ title: "  Trimmed  " }).toState().title).toBe("Trimmed");
    const r = PuzzleDefinition.submit({
      id,
      title: "   ",
      pieceCount: 1000,
      submittedBy: submitter,
      now: NOW,
    });
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("EmptyTitle");
  });

  it.each([0, -5, 3.5])(
    "rejects a non-positive-integer piece count (%s)",
    (value) => {
      const r = PuzzleDefinition.submit({
        id,
        title: "Ok",
        pieceCount: value,
        submittedBy: submitter,
        now: NOW,
      });
      expect(r.isErr).toBe(true);
      if (r.isErr) expect(r.error.code).toBe("InvalidPieceCount");
    },
  );

  it("rejects a malformed barcode", () => {
    const r = PuzzleDefinition.submit({
      id,
      title: "Ok",
      pieceCount: 500,
      submittedBy: submitter,
      now: NOW,
      barcodes: { ean: "not-an-ean" },
    });
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("InvalidBarcode");
  });

  it("flattens validated barcodes into state columns", () => {
    const state = submit({
      barcodes: { ean: "4006381333931", modelNumber: "RV-1" },
    }).toState();
    expect(state.ean).toBe("4006381333931");
    expect(state.modelNumber).toBe("RV-1");
    expect(state.upc).toBeUndefined();
  });

  // publisher (the company, e.g. Jumbo) is distinct from brand (the product line, e.g. Jan
  // van Haasteren) and is copied through the same way.
  it("carries publisher through alongside brand", () => {
    const state = submit({
      brand: "Jan van Haasteren",
      publisher: "Jumbo",
    }).toState();
    expect(state.publisher).toBe("Jumbo");
    expect(state.brand).toBe("Jan van Haasteren");
  });

  // Every field a submission writes is bounded (SEC-26): a definition is read by public browse,
  // the facet streams and the admin queue.
  it.each([
    ["title", { title: "x".repeat(201) }],
    ["description", { description: "x".repeat(5_001) }],
    ["brand", { brand: "x".repeat(101) }],
    ["publisher", { publisher: "x".repeat(101) }],
    ["artist", { artist: "x".repeat(101) }],
    ["series", { series: "x".repeat(101) }],
    ["modelNumber", { barcodes: { modelNumber: "x".repeat(101) } }],
    ["category", { category: toCatalogCategoryId("x".repeat(65)) }],
    ["tags", { tags: Array.from({ length: 21 }, (_, i) => `t${i}`) }],
    ["tag", { tags: ["x".repeat(51)] }],
  ] as const)("refuses an over-long %s with TextTooLong", (_field, extra) => {
    const r = PuzzleDefinition.submit({
      id,
      title: "Ok",
      pieceCount: 500,
      submittedBy: submitter,
      now: NOW,
      ...extra,
    });
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("TextTooLong");
  });

  it("bounds the title after trimming, as it is stored", () => {
    const state = submit({ title: `  ${"x".repeat(200)}  ` }).toState();
    expect(state.title).toHaveLength(200);
  });

  it("accepts every field at its limit", () => {
    const state = submit({
      title: "x".repeat(200),
      description: "x".repeat(5_000),
      brand: "x".repeat(100),
      publisher: "x".repeat(100),
      artist: "x".repeat(100),
      series: "x".repeat(100),
      barcodes: { modelNumber: "x".repeat(100) },
      category: toCatalogCategoryId("x".repeat(64)),
      tags: Array.from({ length: 20 }, () => "x".repeat(50)),
    }).toState();
    expect(state.description).toHaveLength(5_000);
    expect(state.tags).toHaveLength(20);
  });
});

describe("approval lifecycle", () => {
  it("approves a pending definition, recording PuzzleDefinitionApproved", () => {
    const def = submit();
    def.pullEvents();
    const r = def.approve(LATER);
    expect(r.isOk).toBe(true);
    expect(def.status).toBe("approved");
    expect(names(def.pullEvents())).toEqual(["PuzzleDefinitionApproved"]);
    expect(def.toState().updatedAt).toBe(LATER);
  });

  it("rejects a pending definition, recording PuzzleDefinitionRejected", () => {
    const def = submit();
    def.pullEvents();
    const r = def.reject(undefined, LATER);
    expect(r.isOk).toBe(true);
    expect(def.status).toBe("rejected");
    const events = def.pullEvents();
    expect(names(events)).toEqual(["PuzzleDefinitionRejected"]);
    expect((events[0] as PuzzleDefinitionRejected).reason).toBeUndefined();
    expect(events[0].occurredAt).toBe(LATER);
  });

  it("carries the moderator's reason on PuzzleDefinitionRejected", () => {
    const def = submit();
    def.pullEvents();
    def.reject("Duplicate of “Starry Night”", LATER);
    const [event] = def.pullEvents();
    expect(event).toBeInstanceOf(PuzzleDefinitionRejected);
    expect((event as PuzzleDefinitionRejected).reason).toBe(
      "Duplicate of “Starry Night”",
    );
  });

  it("cannot approve an already-approved definition (illegal transition)", () => {
    const def = submit();
    def.approve(NOW);
    const r = def.approve(LATER);
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("IllegalApprovalTransition");
  });

  it("cannot reject an approved definition, nor approve a rejected one", () => {
    const approved = submit();
    approved.approve(NOW);
    expect(approved.reject(undefined, LATER).isErr).toBe(true);

    const rejected = submit();
    rejected.reject(undefined, NOW);
    expect(rejected.approve(LATER).isErr).toBe(true);
  });

  it("rejected is a terminal approval status with no outgoing moves", () => {
    expect(ALLOWED_APPROVAL_TRANSITIONS.rejected).toEqual([]);
  });
});

describe("disable / re-enable lifecycle", () => {
  const approved = (): PuzzleDefinition => {
    const def = submit();
    def.approve(NOW);
    def.pullEvents();
    return def;
  };

  it("disables an approved definition, recording PuzzleDefinitionDisabled", () => {
    const def = approved();
    const r = def.disable(LATER);
    expect(r.isOk).toBe(true);
    expect(def.status).toBe("disabled");
    expect(names(def.pullEvents())).toEqual(["PuzzleDefinitionDisabled"]);
    expect(def.toState().updatedAt).toBe(LATER);
  });

  it("re-enables a disabled definition back to approved, recording PuzzleDefinitionReenabled", () => {
    const def = approved();
    def.disable(NOW);
    def.pullEvents();
    const r = def.reenable(LATER);
    expect(r.isOk).toBe(true);
    expect(def.status).toBe("approved");
    expect(names(def.pullEvents())).toEqual(["PuzzleDefinitionReenabled"]);
    expect(def.toState().updatedAt).toBe(LATER);
  });

  it("cannot disable a pending or rejected definition (illegal transition)", () => {
    const pending = submit();
    const r1 = pending.disable(LATER);
    expect(r1.isErr).toBe(true);
    if (r1.isErr) expect(r1.error.code).toBe("IllegalApprovalTransition");

    const rejected = submit();
    rejected.reject(undefined, NOW);
    const r2 = rejected.disable(LATER);
    expect(r2.isErr).toBe(true);
    if (r2.isErr) expect(r2.error.code).toBe("IllegalApprovalTransition");
  });

  it("cannot disable twice", () => {
    const def = approved();
    def.disable(NOW);
    const again = def.disable(LATER);
    expect(again.isErr).toBe(true);
    if (again.isErr) expect(again.error.code).toBe("IllegalApprovalTransition");
  });

  // reenable is NOT a backdoor approve: even though pending → approved is a legal TABLE move,
  // reenable() itself must only act on a disabled definition.
  it("cannot re-enable a definition that is not disabled", () => {
    const r1 = approved().reenable(LATER);
    expect(r1.isErr).toBe(true);
    if (r1.isErr) expect(r1.error.code).toBe("IllegalApprovalTransition");

    const pending = submit();
    const r2 = pending.reenable(LATER);
    expect(r2.isErr).toBe(true);
    if (r2.isErr) expect(r2.error.code).toBe("IllegalApprovalTransition");
  });

  it("a re-enabled definition can be disabled again (full round-trip)", () => {
    const def = approved();
    expect(def.disable(NOW).isOk).toBe(true);
    expect(def.reenable(NOW).isOk).toBe(true);
    expect(def.disable(LATER).isOk).toBe(true);
    expect(def.status).toBe("disabled");
  });
});

describe("update", () => {
  it("patches descriptive fields and records PuzzleDefinitionUpdated", () => {
    const def = submit();
    def.pullEvents();
    const r = def.update(
      { brand: "Ravensburger", tags: ["art", "van-gogh"] },
      LATER,
    );
    expect(r.isOk).toBe(true);
    expect(def.toState().brand).toBe("Ravensburger");
    expect(def.toState().tags).toEqual(["art", "van-gogh"]);
    expect(names(def.pullEvents())).toEqual(["PuzzleDefinitionUpdated"]);
  });

  it("re-validates patched title, pieceCount and barcodes", () => {
    const def = submit();
    expect(def.update({ title: "  " }, LATER).isErr).toBe(true);
    expect(def.update({ pieceCount: -1 }, LATER).isErr).toBe(true);
    expect(def.update({ barcodes: { upc: "bad" } }, LATER).isErr).toBe(true);
  });

  it("trims and applies a valid title change", () => {
    const def = submit({ title: "Old" });
    const r = def.update({ title: "  New Title  " }, LATER);
    expect(r.isOk).toBe(true);
    expect(def.toState().title).toBe("New Title");
  });

  it("re-flattens validated barcodes into the state columns on update", () => {
    const def = submit();
    const r = def.update(
      { barcodes: { ean: "4006381333931", modelNumber: "  RV-9  " } },
      LATER,
    );
    expect(r.isOk).toBe(true);
    const state = def.toState();
    expect(state.ean).toBe("4006381333931");
    expect(state.modelNumber).toBe("RV-9");
    expect(state.upc).toBeUndefined();
  });

  // Updating with ONLY a UPC must clear ean/modelNumber to undefined via optional chaining
  // (`validated.value.ean?.value`): replacing the whole barcode grouping, not merging it.
  it("replaces the whole barcode grouping, clearing absent identifiers to undefined", () => {
    const def = submit({
      barcodes: { ean: "4006381333931", modelNumber: "RV-1" },
    });
    const r = def.update({ barcodes: { upc: "036000291452" } }, LATER);
    expect(r.isOk).toBe(true);
    const state = def.toState();
    expect(state.upc).toBe("036000291452");
    expect(state.ean).toBeUndefined();
    expect(state.modelNumber).toBeUndefined();
  });

  // Omitting `barcodes` entirely must preserve the previously stored identifiers
  // (the `barcodeFields` default object), not wipe them.
  it("preserves stored barcodes when an update omits the barcodes field", () => {
    const def = submit({ barcodes: { ean: "4006381333931" } });
    def.update({ brand: "Anything" }, LATER);
    expect(def.toState().ean).toBe("4006381333931");
  });

  it("applies a valid pieceCount change", () => {
    const def = submit({ pieceCount: 100 });
    expect(def.update({ pieceCount: 2000 }, LATER).isOk).toBe(true);
    expect(def.toState().pieceCount).toBe(2000);
  });

  // Each descriptive field patches independently via `changes.X ?? state.X`; setting one from
  // an UNSET baseline distinguishes `??` (keeps the new value) from `&&` (would drop it).
  it("sets each previously-unset descriptive field from its change", () => {
    const def = submit({
      title: "Base",
      tags: [],
      // description / artist / series / dimensions / shape / difficulty / category / image
      // are all left undefined so the ?? coalescing is exercised on an unset baseline.
    });
    def.update(
      {
        description: "A scene",
        artist: "An Artist",
        series: "A Series",
        image: "ref://img",
        dimensions: { width: 50, height: 70, unit: "cm" },
        shape: "round",
        difficulty: "hard",
        category: toCatalogCategoryId("cat1"),
      },
      LATER,
    );
    const state = def.toState();
    expect(state.description).toBe("A scene");
    expect(state.artist).toBe("An Artist");
    expect(state.series).toBe("A Series");
    expect(state.image).toBe("ref://img");
    expect(state.dimensions).toEqual({ width: 50, height: 70, unit: "cm" });
    expect(state.shape).toBe("round");
    expect(state.difficulty).toBe("hard");
    expect(state.category).toBe("cat1");
  });

  it("preserves existing fields when a change omits them", () => {
    const def = submit({ brand: "Keep", artist: "Keep Artist" });
    def.update({ description: "added" }, LATER);
    const state = def.toState();
    expect(state.brand).toBe("Keep");
    expect(state.artist).toBe("Keep Artist");
  });

  it("leaves approval status untouched", () => {
    const def = submit();
    def.approve(NOW);
    def.update({ brand: "X" }, LATER);
    expect(def.status).toBe("approved");
  });

  // publisher patches independently via `changes.publisher ?? state.publisher`, same as brand:
  // an omitted publisher on a later update leaves the previously set value unchanged.
  it("sets publisher from a patch, then leaves it unchanged when a later update omits it", () => {
    const def = submit();
    def.update({ publisher: "Jumbo" }, LATER);
    expect(def.toState().publisher).toBe("Jumbo");

    def.update({ title: "Renamed" }, LATER);
    expect(def.toState().publisher).toBe("Jumbo");
  });

  it("refuses new over-long text with TextTooLong and leaves the definition unchanged", () => {
    const def = submit({ brand: "Jumbo" });
    def.pullEvents();
    for (const changes of [
      { title: "x".repeat(201) },
      { description: "x".repeat(5_001) },
      { brand: "x".repeat(101) },
      { barcodes: { modelNumber: "x".repeat(101) } },
      { category: toCatalogCategoryId("x".repeat(65)) },
      { tags: Array.from({ length: 21 }, (_, i) => `t${i}`) },
      { tags: ["x".repeat(51)] },
    ]) {
      const r = def.update(changes, LATER);
      expect(r.isErr).toBe(true);
      if (r.isErr) expect(r.error.code).toBe("TextTooLong");
    }
    expect(def.toState().brand).toBe("Jumbo");
    expect(def.pullEvents()).toHaveLength(0);
  });

  // Rows stored before the bounds existed are grandfathered: an update is only refused for text
  // it changes, so restating a stored over-long value (as the edit forms do) still saves.
  describe("a definition stored before the text bounds", () => {
    const legacy = () =>
      PuzzleDefinition.rehydrate({
        ...submit().toState(),
        title: "t".repeat(300),
        description: "d".repeat(10_000),
        brand: "b".repeat(150),
        tags: Array.from({ length: 30 }, (_, i) => `tag${i}`),
        modelNumber: "m".repeat(150),
      });

    it("updates another field and keeps its long text", () => {
      const def = legacy();
      const r = def.update({ pieceCount: 2000 }, LATER);
      expect(r.isOk).toBe(true);
      expect(def.toState().pieceCount).toBe(2000);
      expect(def.toState().description).toHaveLength(10_000);
    });

    it("accepts its stored long values restated unchanged", () => {
      const def = legacy();
      const state = def.toState();
      const r = def.update(
        {
          title: state.title,
          description: state.description,
          brand: state.brand,
          tags: [...(state.tags ?? [])],
          barcodes: { modelNumber: state.modelNumber },
          series: "Short series",
        },
        LATER,
      );
      expect(r.isOk).toBe(true);
      expect(def.toState().series).toBe("Short series");
    });

    it("refuses a changed value that is still too long", () => {
      const def = legacy();
      const r = def.update({ description: "e".repeat(10_000) }, LATER);
      expect(r.isErr).toBe(true);
      if (r.isErr) expect(r.error.code).toBe("TextTooLong");
    });
  });
});

describe("searchableText (derived projection)", () => {
  it("joins title, brand, artist, series and tags, skipping empties", () => {
    const def = submit({
      title: "Starry Night",
      brand: "Ravensburger",
      artist: "Van Gogh",
      series: "Masterpieces",
      tags: ["art", "night"],
    });
    expect(def.searchableText()).toBe(
      "Starry Night Ravensburger Van Gogh Masterpieces art night",
    );
  });

  it("omits the tags segment entirely when no tags are set", () => {
    // tags left undefined exercises the `this.state.tags ?? []` fallback in searchableText.
    const def = submit({ title: "Solo", brand: "Brand" });
    expect(def.searchableText()).toBe("Solo Brand");
  });

  // An empty-string field is filtered out (length > 0, not >= 0): no stray separators appear.
  it("excludes present-but-empty fields rather than emitting blank gaps", () => {
    const def = submit({
      title: "Title",
      brand: "",
      artist: "Artist",
      series: "",
      tags: ["", "tag"],
    });
    expect(def.searchableText()).toBe("Title Artist tag");
  });

  it("folds accents, so searching 'cafe' finds 'Café'", () => {
    expect(submit({ title: "Café", tags: ["été"] }).searchableText()).toBe(
      "Cafe ete",
    );
  });

  it("reflects updates and is never part of persisted state", () => {
    const def = submit({ title: "A", tags: [] });
    expect(def.searchableText()).toBe("A");
    def.update({ brand: "B" }, LATER);
    expect(def.searchableText()).toBe("A B");
    expect("searchableText" in def.toState()).toBe(false);
  });

  it("includes publisher alongside brand", () => {
    const def = submit({
      title: "Roadworks",
      publisher: "Jumbo",
      brand: "Jan van Haasteren",
    });
    expect(def.searchableText()).toContain("Jumbo");
    expect(def.searchableText()).toContain("Jan van Haasteren");
  });
});

describe("rehydrate / toState round-trip", () => {
  it("rehydrates without re-recording events", () => {
    const original = submit({ barcodes: { ean: "4006381333931" } });
    const state = original.toState();
    const restored = PuzzleDefinition.rehydrate(state);
    expect(restored.pullEvents()).toHaveLength(0);
    expect(restored.toState()).toEqual(state);
    expect(restored.status).toBe("pending");
  });

  it("a rehydrated definition can still be approved", () => {
    const restored = PuzzleDefinition.rehydrate(submit().toState());
    expect(restored.approve(LATER).isOk).toBe(true);
    expect(restored.status).toBe("approved");
  });
});

// v.number() takes NaN, Infinity, negatives and 1e300 alike, and 1e300 is an integer too. All of them
// used to reach the catalog page every visitor reads.
describe("a definition's numbers stay within reason", () => {
  const refused = (props: Partial<SubmitPuzzleDefinitionProps>) =>
    PuzzleDefinition.submit({
      id,
      title: "Starry Night",
      pieceCount: 1000,
      submittedBy: submitter,
      now: NOW,
      ...props,
    });

  it.each([MAX_PIECE_COUNT + 1, 1e300, Number.MAX_VALUE])(
    "refuses %p pieces, on a submit and on an update",
    (pieceCount) => {
      const submitted = refused({ pieceCount });
      expect(submitted.isErr).toBe(true);
      if (submitted.isErr) {
        expect(submitted.error.code).toBe("InvalidPieceCount");
      }
      const updated = submit().update({ pieceCount }, LATER);
      expect(updated.isErr).toBe(true);
    },
  );

  it("accepts the largest piece count", () => {
    expect(refused({ pieceCount: MAX_PIECE_COUNT }).isOk).toBe(true);
  });

  it.each([
    0,
    -1,
    Number.NaN,
    Number.POSITIVE_INFINITY,
    1e300,
    MAX_DIMENSION + 1,
  ])("refuses a side of %p, on a submit and on an update", (side) => {
    for (const dimensions of [
      { width: side, height: 50, unit: "cm" as const },
      { width: 70, height: side, unit: "in" as const },
    ]) {
      const submitted = refused({ dimensions });
      expect(submitted.isErr).toBe(true);
      if (submitted.isErr) {
        expect(submitted.error.code).toBe("InvalidDimensions");
      }
      const updated = submit().update({ dimensions }, LATER);
      expect(updated.isErr).toBe(true);
      if (updated.isErr) expect(updated.error.code).toBe("InvalidDimensions");
    }
  });

  it("accepts real dimensions, fractions included", () => {
    const dimensions = { width: 68.5, height: 48.2, unit: "cm" as const };
    const r = refused({ dimensions });
    expect(r.isOk).toBe(true);
    if (r.isOk) expect(r.value.toState().dimensions).toEqual(dimensions);
  });
});

