import { beforeEach, describe, expect, it } from "vitest";
import {
  toCircleId,
  toCircleInviteId,
  toMemberId,
} from "../../../shared-kernel";
import {
  CIRCLE_INVITE_TTL_MS,
  CircleId,
  CircleInviteId,
  MAX_CIRCLE_MEMBERS,
} from "../../domain";
import {
  FixedClock,
  InMemoryCircleInviteRepository,
  InMemoryCircleRepository,
  RecordingEventPublisher,
  SequentialCircleIdGenerator,
  SequentialCircleInviteIdGenerator,
  SequentialMembershipIdGenerator,
  StubInvitePolicy,
} from "../testing";
import { makeAcceptCircleInvite } from "./accept-circle-invite";
import { makeAddMember } from "./add-member";
import { makeChangePermission } from "./change-permission";
import { makeCreateCircle } from "./create-circle";
import { makeDeclineCircleInvite } from "./decline-circle-invite";
import { makeExpireCircleInvite } from "./expire-circle-invite";
import { makeInviteToCircle } from "./invite-to-circle";
import { makeRemoveMember } from "./remove-member";
import { makeRevokeCircleInvite } from "./revoke-circle-invite";
import { makeWithdrawInvitesFrom } from "./withdraw-invites-from";

const owner = toMemberId("owner");
const admin = toMemberId("admin");
const member = toMemberId("member");
const invitee = toMemberId("invitee");
const stranger = toMemberId("stranger");
const NOW = new Date("2026-06-08T10:00:00Z");
const later = (ms: number) => new Date(NOW.getTime() + ms);

const codeOf = (result: { isErr: boolean; error?: { code: string } }) =>
  result.isErr ? result.error?.code : undefined;

describe("Sharing circle-invite use cases", () => {
  let circles: InMemoryCircleRepository;
  let invites: InMemoryCircleInviteRepository;
  let policy: StubInvitePolicy;
  let membershipIds: SequentialMembershipIdGenerator;
  let events: RecordingEventPublisher;
  let clock: FixedClock;
  let deps: Parameters<typeof makeAcceptCircleInvite>[0] &
    Parameters<typeof makeInviteToCircle>[0];

  let circleId: CircleId;

  const invite = (
    inviteeId = invitee,
    actorId = owner,
    permission: "ViewOnly" | "Exchange" | "Admin" = "Exchange",
  ) => makeInviteToCircle(deps)({ circleId, actorId, inviteeId, permission });

  const invited = async (inviteeId = invitee, actorId = owner) => {
    const result = await invite(inviteeId, actorId);
    if (!result.isOk) throw new Error(`setup: invite failed ${codeOf(result)}`);
    events.published.length = 0;
    return result.value;
  };

  const accept = (inviteId: CircleInviteId, actorId = invitee) =>
    makeAcceptCircleInvite(deps)({ actorId, inviteId });
  const decline = (inviteId: CircleInviteId, actorId = invitee) =>
    makeDeclineCircleInvite(deps)({ actorId, inviteId });
  const revoke = (inviteId: CircleInviteId, actorId: typeof owner) =>
    makeRevokeCircleInvite(deps)({ actorId, inviteId });
  const expire = (inviteId: CircleInviteId) =>
    makeExpireCircleInvite(deps)({ inviteId });

  beforeEach(async () => {
    circles = new InMemoryCircleRepository();
    invites = new InMemoryCircleInviteRepository();
    policy = new StubInvitePolicy();
    membershipIds = new SequentialMembershipIdGenerator();
    events = new RecordingEventPublisher();
    clock = new FixedClock(NOW);
    deps = {
      circles,
      invites,
      policy,
      inviteIds: new SequentialCircleInviteIdGenerator(),
      membershipIds,
      events,
      clock,
    };

    const created = await makeCreateCircle({
      circles,
      circleIds: new SequentialCircleIdGenerator(),
      membershipIds,
      events,
      clock,
    })({ ownerId: owner, name: "Family" });
    if (!created.isOk) throw new Error("setup: create failed");
    circleId = created.value;
    const add = makeAddMember({ circles, membershipIds, events, clock });
    await add({
      circleId,
      actorId: owner,
      memberId: admin,
      permission: "Admin",
    });
    await add({
      circleId,
      actorId: owner,
      memberId: member,
      permission: "ViewOnly",
    });
    for (const inviter of [owner, admin, member]) {
      policy.allowContact(inviter, invitee);
    }
    events.published.length = 0;
  });

  describe("makeInviteToCircle", () => {
    it("issues a pending invite and publishes CircleInviteIssued", async () => {
      const result = await invite();

      expect(result.isOk).toBe(true);
      if (!result.isOk) return;
      const stored = await invites.findById(result.value);
      expect(stored?.toState()).toMatchObject({
        circleId,
        inviterId: owner,
        inviteeId: invitee,
        permission: "Exchange",
        status: "pending",
        createdAt: NOW,
        expiresAt: later(CIRCLE_INVITE_TTL_MS),
      });
      expect(events.names()).toEqual(["CircleInviteIssued"]);
    });

    it("lets any Admin invite", async () => {
      expect((await invite(invitee, admin)).isOk).toBe(true);
    });

    it("refuses a non-admin member", async () => {
      expect(codeOf(await invite(invitee, member))).toBe("NotCircleAdmin");
      expect(invites.all()).toEqual([]);
    });

    it("answers a non-member or an unknown circle with CircleNotFound", async () => {
      expect(codeOf(await invite(invitee, stranger))).toBe("CircleNotFound");
      const missing = await makeInviteToCircle(deps)({
        circleId: toCircleId("nope"),
        actorId: owner,
        inviteeId: invitee,
        permission: "ViewOnly",
      });
      expect(codeOf(missing)).toBe("CircleNotFound");
    });

    it("refuses an existing member, the actor included", async () => {
      expect(codeOf(await invite(member))).toBe("AlreadyMember");
      expect(codeOf(await invite(owner))).toBe("AlreadyMember");
    });

    it("refuses an uncontactable or blocked member with the same CannotInvite", async () => {
      expect(codeOf(await invite(stranger))).toBe("CannotInvite");
      policy.block(owner, invitee);
      expect(codeOf(await invite(invitee))).toBe("CannotInvite");
      expect(invites.all()).toEqual([]);
      expect(events.published).toEqual([]);
    });

    it("refuses even when an old invite is pending if the contact rule now fails", async () => {
      await invited();
      policy.block(invitee, owner);
      expect(codeOf(await invite())).toBe("CannotInvite");
    });

    it("returns the open invite on a repeat, issuing nothing", async () => {
      const first = await invited();
      const again = await invite(invitee, admin);

      expect(again.isOk && again.value).toBe(first);
      expect(invites.all()).toHaveLength(1);
      expect(events.published).toEqual([]);
    });

    it("expires a stale pending invite and issues a fresh one", async () => {
      const first = await invited();
      clock.set(later(CIRCLE_INVITE_TTL_MS));

      const again = await invite();

      expect(again.isOk).toBe(true);
      if (!again.isOk) return;
      expect(again.value).not.toBe(first);
      expect((await invites.findById(first))?.status).toBe("expired");
      expect((await invites.findById(again.value))?.status).toBe("pending");
      expect(events.names()).toEqual([
        "CircleInviteExpired",
        "CircleInviteIssued",
      ]);
    });

    it("holds off a re-invite for 7 days after a decline or revoke, with CannotInvite", async () => {
      const WEEK = 7 * 24 * 60 * 60 * 1000;
      const declined = await invited();
      await decline(declined);
      expect(codeOf(await invite(invitee, admin))).toBe("CannotInvite");

      const other = toMemberId("other");
      policy.allowContact(owner, other);
      await revoke(await invited(other), owner);
      expect(codeOf(await invite(other))).toBe("CannotInvite");

      clock.set(later(WEEK));
      expect((await invite()).isOk).toBe(true);
      expect((await invite(other)).isOk).toBe(true);
    });

    it("does not hold off after an expiry", async () => {
      const first = await invited();
      clock.set(later(CIRCLE_INVITE_TTL_MS));
      await expire(first);
      expect((await invite()).isOk).toBe(true);
    });

    it("counts open invites against the member cap", async () => {
      // 3 members; fill the remaining seats with open invites.
      const free = MAX_CIRCLE_MEMBERS - 3;
      for (let i = 1; i < free; i += 1) {
        const other = toMemberId(`other-${i}`);
        policy.allowContact(owner, other);
        await invited(other);
      }
      // The last free seat can still be offered.
      expect((await invite()).isOk).toBe(true);

      const extra = toMemberId("extra");
      policy.allowContact(owner, extra);
      expect(codeOf(await invite(extra))).toBe("CircleFull");
    });

    it("does not count expired or decided invites against the cap", async () => {
      const free = MAX_CIRCLE_MEMBERS - 3;
      const ids: CircleInviteId[] = [];
      for (let i = 1; i <= free; i += 1) {
        const other = toMemberId(`other-${i}`);
        policy.allowContact(owner, other);
        ids.push(await invited(other));
      }
      await decline(ids[0], toMemberId("other-1"));
      expect((await invite()).isOk).toBe(true);

      clock.set(later(CIRCLE_INVITE_TTL_MS));
      const extra = toMemberId("extra");
      policy.allowContact(owner, extra);
      expect((await invite(extra)).isOk).toBe(true);
    });
  });

  describe("makeAcceptCircleInvite", () => {
    it("seats the invitee at the invite's permission and publishes both events", async () => {
      const inviteId = await invited();

      const result = await accept(inviteId);

      expect(result.isOk && result.value).toBe(circleId);
      const circle = await circles.findById(circleId);
      expect(
        circle?.members.find((m) => m.memberId === invitee)?.permission,
      ).toBe("Exchange");
      expect((await invites.findById(inviteId))?.status).toBe("accepted");
      expect(events.names()).toEqual([
        "CircleInviteAccepted",
        "MemberJoinedCircle",
      ]);
    });

    it("answers an unknown invite and someone else's invite with InviteNotFound", async () => {
      const inviteId = await invited();
      expect(codeOf(await accept(toCircleInviteId("nope")))).toBe(
        "InviteNotFound",
      );
      expect(codeOf(await accept(inviteId, owner))).toBe("InviteNotFound");
      expect((await invites.findById(inviteId))?.status).toBe("pending");
    });

    it("refuses after expiry, and an already-decided invite", async () => {
      const inviteId = await invited();
      clock.set(later(CIRCLE_INVITE_TTL_MS));
      expect(codeOf(await accept(inviteId))).toBe("InviteExpired");

      clock.set(NOW);
      await decline(inviteId);
      expect(codeOf(await accept(inviteId))).toBe("InviteNotPending");
    });

    it("refuses generically when the pair is now blocked, persisting nothing", async () => {
      const inviteId = await invited();
      policy.block(invitee, owner);

      expect(codeOf(await accept(inviteId))).toBe("InviteNotFound");
      expect((await circles.findById(circleId))?.isMember(invitee)).toBe(false);
      expect((await invites.findById(inviteId))?.status).toBe("pending");
      expect(events.published).toEqual([]);
    });

    // A third party's invite must not seat someone next to a member they blocked, or who blocked
    // them: every current member counts, not only the inviter.
    it.each([
      ["the invitee blocked a plain member", invitee, member],
      ["a plain member blocked the invitee", member, invitee],
      ["another Admin blocked the invitee", admin, invitee],
    ])(
      "refuses generically when %s, persisting nothing",
      async (_case, blocker, blocked) => {
        const inviteId = await invited();
        policy.block(blocker, blocked);

        expect(codeOf(await accept(inviteId))).toBe("InviteNotFound");
        expect((await circles.findById(circleId))?.isMember(invitee)).toBe(
          false,
        );
        expect((await invites.findById(inviteId))?.status).toBe("pending");
        expect(events.published).toEqual([]);
      },
    );

    it("still seats the invitee across blocks that don't involve them, or with someone outside the circle", async () => {
      const inviteId = await invited();
      policy.block(admin, member);
      policy.block(invitee, stranger);

      expect((await accept(inviteId)).isOk).toBe(true);
      expect((await circles.findById(circleId))?.isMember(invitee)).toBe(true);
    });

    it("refuses generically when the inviter is no longer an Admin", async () => {
      const inviteId = await invited(invitee, admin);
      await makeChangePermission({ circles, events })({
        circleId,
        actorId: owner,
        memberId: admin,
        permission: "ViewOnly",
      });

      expect(codeOf(await accept(inviteId))).toBe("InviteNotFound");
      expect((await circles.findById(circleId))?.isMember(invitee)).toBe(false);
    });

    it("refuses generically when the inviter left the circle", async () => {
      const inviteId = await invited(invitee, admin);
      await makeRemoveMember({ circles, events, clock })({
        circleId,
        actorId: owner,
        memberId: admin,
      });

      expect(codeOf(await accept(inviteId))).toBe("InviteNotFound");
    });

    it("refuses generically when the circle is gone", async () => {
      const inviteId = await invited();
      const orphan = new InMemoryCircleRepository();
      const result = await makeAcceptCircleInvite({ ...deps, circles: orphan })(
        { actorId: invitee, inviteId },
      );
      expect(codeOf(result)).toBe("InviteNotFound");
    });

    it("refuses with CircleFull when the circle filled up meanwhile", async () => {
      const inviteId = await invited();
      const add = makeAddMember({ circles, membershipIds, events, clock });
      for (let i = 1; i <= MAX_CIRCLE_MEMBERS - 3; i += 1) {
        await add({
          circleId,
          actorId: owner,
          memberId: toMemberId(`seat-${i}`),
          permission: "ViewOnly",
        });
      }

      expect(codeOf(await accept(inviteId))).toBe("CircleFull");
      expect((await invites.findById(inviteId))?.status).toBe("pending");
    });
  });

  describe("makeDeclineCircleInvite", () => {
    it("declines and publishes CircleInviteDeclined", async () => {
      const inviteId = await invited();

      expect((await decline(inviteId)).isOk).toBe(true);
      expect((await invites.findById(inviteId))?.status).toBe("declined");
      expect(events.names()).toEqual(["CircleInviteDeclined"]);
    });

    it("answers an unknown or foreign invite with InviteNotFound", async () => {
      const inviteId = await invited();
      expect(codeOf(await decline(toCircleInviteId("nope")))).toBe(
        "InviteNotFound",
      );
      expect(codeOf(await decline(inviteId, owner))).toBe("InviteNotFound");
    });

    it("refuses an already-decided invite", async () => {
      const inviteId = await invited();
      await decline(inviteId);
      events.published.length = 0;
      expect(codeOf(await decline(inviteId))).toBe("InviteNotPending");
      expect(events.published).toEqual([]);
    });
  });

  describe("makeRevokeCircleInvite", () => {
    it("lets the inviter revoke and publishes CircleInviteRevoked", async () => {
      const inviteId = await invited(invitee, admin);

      expect((await revoke(inviteId, admin)).isOk).toBe(true);
      expect((await invites.findById(inviteId))?.status).toBe("revoked");
      expect(events.names()).toEqual(["CircleInviteRevoked"]);
    });

    it("lets another Admin revoke", async () => {
      const inviteId = await invited(invitee, owner);
      expect((await revoke(inviteId, admin)).isOk).toBe(true);
    });

    it("answers a non-admin, the invitee and an unknown id with InviteNotFound", async () => {
      const inviteId = await invited();
      expect(codeOf(await revoke(inviteId, member))).toBe("InviteNotFound");
      expect(codeOf(await revoke(inviteId, invitee))).toBe("InviteNotFound");
      expect(codeOf(await revoke(toCircleInviteId("nope"), owner))).toBe(
        "InviteNotFound",
      );
      expect((await invites.findById(inviteId))?.status).toBe("pending");
    });

    it("answers an invite whose circle is gone with InviteNotFound", async () => {
      const inviteId = await invited();
      const result = await makeRevokeCircleInvite({
        ...deps,
        circles: new InMemoryCircleRepository(),
      })({ actorId: owner, inviteId });
      expect(codeOf(result)).toBe("InviteNotFound");
    });

    it("only revokes while pending", async () => {
      const inviteId = await invited();
      await decline(inviteId);
      events.published.length = 0;
      expect(codeOf(await revoke(inviteId, owner))).toBe("InviteNotPending");
      expect(events.published).toEqual([]);
    });
  });

  describe("makeWithdrawInvitesFrom", () => {
    const withdraw = (inviterId: typeof owner) =>
      makeWithdrawInvitesFrom(deps)({ circleId, inviterId });

    it("withdraws only that inviter's pending invites, publishing one revoke each", async () => {
      const other = toMemberId("other");
      policy.allowContact(admin, other);
      const fromAdmin = await invited(invitee, admin);
      const fromAdminToo = await invited(other, admin);
      const third = toMemberId("third");
      policy.allowContact(owner, third);
      const fromOwner = await invited(third, owner);

      expect(await withdraw(admin)).toBe(2);

      for (const id of [fromAdmin, fromAdminToo]) {
        expect((await invites.findById(id))?.status).toBe("revoked");
      }
      expect((await invites.findById(fromOwner))?.status).toBe("pending");
      expect(events.names()).toEqual([
        "CircleInviteRevoked",
        "CircleInviteRevoked",
      ]);
      // The withdrawn invitee can be invited again straight away.
      expect((await invite(invitee, owner)).isOk).toBe(true);
    });

    it("leaves decided invites alone and publishes nothing when none are pending", async () => {
      const declined = await invited(invitee, admin);
      await decline(declined);
      events.published.length = 0;

      expect(await withdraw(admin)).toBe(0);
      expect((await invites.findById(declined))?.status).toBe("declined");
      expect(events.published).toEqual([]);
    });
  });

  describe("makeExpireCircleInvite", () => {
    it("flips a due pending invite to expired and publishes CircleInviteExpired", async () => {
      const inviteId = await invited();
      clock.set(later(CIRCLE_INVITE_TTL_MS));

      expect(await expire(inviteId)).toBe(true);
      expect((await invites.findById(inviteId))?.status).toBe("expired");
      expect(events.names()).toEqual(["CircleInviteExpired"]);
    });

    it("is a no-op for an unknown, decided or not-yet-due invite", async () => {
      expect(await expire(toCircleInviteId("nope"))).toBe(false);

      const early = await invited();
      expect(await expire(early)).toBe(false);
      expect((await invites.findById(early))?.status).toBe("pending");

      await accept(early);
      clock.set(later(CIRCLE_INVITE_TTL_MS));
      events.published.length = 0;
      expect(await expire(early)).toBe(false);
      expect((await invites.findById(early))?.status).toBe("accepted");
      expect(events.published).toEqual([]);
    });
  });
});

src/exchange/domain/exchange.spec.ts.source:
import { beforeEach, describe, expect, it } from "vitest";
import {
  DomainEvent,
  toCopyId,
  toExchangeId,
  toMemberId,
} from "../../shared-kernel";
import {
  ExchangeCancelled,
  ExchangeCompleted,
  ExchangeProposed,
  OwnershipTransferred,
  PossessionTransferred,
} from "./events";
import { Exchange, ProposeProps } from "./exchange";
import { ExchangeTermsInput, Money } from "./terms";

const exchangeId = toExchangeId("ex1");
const alice = toMemberId("alice"); // initiator
const bob = toMemberId("bob"); // recipient
const requested = toCopyId("requested");
const offered = toCopyId("offered");
const NOW = new Date("2026-06-08T10:00:00Z");
const LATER = new Date("2026-06-09T10:00:00Z");

const price = (): Money => {
  const m = Money.create(2500, "EUR");
  if (!m.isOk) throw new Error("setup");
  return m.value;
};

const propose = (
  terms: ExchangeTermsInput,
  overrides: Partial<ProposeProps> = {},
): Exchange => {
  const result = Exchange.propose({
    id: exchangeId,
    initiator: alice,
    recipient: bob,
    requestedCopyId: requested,
    terms,
    now: NOW,
    ...overrides,
  });
  if (!result.isOk) throw new Error(`setup failed: ${result.error.message}`);
  return result.value;
};

const swapTerms: ExchangeTermsInput = { kind: "swap", offeredCopyId: offered };
const saleTerms = (): ExchangeTermsInput => ({ kind: "sale", price: price() });
const lendTerms: ExchangeTermsInput = { kind: "lend", returnDate: LATER };

const names = (events: readonly DomainEvent[]): string[] =>
  events.map((e) => e.name);

// Drive an exchange to `accepted` and clear the proposal/accept events.
const accepted = (terms: ExchangeTermsInput = swapTerms): Exchange => {
  const ex = propose(terms);
  const r = ex.accept(bob, NOW);
  expect(r.isOk).toBe(true);
  ex.pullEvents();
  return ex;
};

describe("Exchange.propose", () => {
  it("rejects a self-exchange (initiator === recipient)", () => {
    const result = Exchange.propose({
      id: exchangeId,
      initiator: alice,
      recipient: alice,
      requestedCopyId: requested,
      terms: swapTerms,
      now: NOW,
    });
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("SelfExchange");
  });

  it.each<[string, ExchangeTermsInput]>([
    ["swap without offered copy", { kind: "swap" }],
    ["sale without price", { kind: "sale" }],
  ])("rejects %s with MissingTerms", (_label, terms) => {
    const result = Exchange.propose({
      id: exchangeId,
      initiator: alice,
      recipient: bob,
      requestedCopyId: requested,
      terms,
      now: NOW,
    });
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("MissingTerms");
  });

  it("starts proposed and records ExchangeProposed carrying parties and kind", () => {
    const ex = propose(swapTerms);
    expect(ex.status).toBe("proposed");
    expect(ex.kind).toBe("swap");
    const events = ex.pullEvents();
    expect(names(events)).toEqual(["ExchangeProposed"]);
    const proposed = events[0] as ExchangeProposed;
    expect(proposed.initiator).toBe(alice);
    expect(proposed.recipient).toBe(bob);
    expect(proposed.kind).toBe("swap");
    expect(proposed.occurredAt).toBe(NOW);
  });

  it("captures kind-specific terms into state, tagged with the matching kind", () => {
    const swap = propose(swapTerms).toState();
    expect(swap.kind).toBe("swap");
    expect(swap.offeredCopyId).toBe(offered);

    const sale = propose(saleTerms()).toState();
    expect(sale.kind).toBe("sale");
    expect(sale.price?.amountCents).toBe(2500);

    const lend = propose(lendTerms).toState();
    expect(lend.kind).toBe("lend");
    expect(lend.returnDate).toBe(LATER);
  });

  it("records who owned the offered copy for a swap, and only for a swap", () => {
    const carol = toMemberId("carol"); // alice's housemate, owner of the offered copy
    expect(
      propose(swapTerms, { offeredCopyOwnerId: carol }).toState()
        .offeredCopyOwnerId,
    ).toBe(carol);

    const sale = propose(saleTerms(), { offeredCopyOwnerId: carol }).toState();
    expect(sale).not.toHaveProperty("offeredCopyOwnerId");
    const lend = propose(lendTerms, { offeredCopyOwnerId: carol }).toState();
    expect(lend).not.toHaveProperty("offeredCopyOwnerId");
    // Not supplied (as on a row proposed before it was recorded): absent, never a guess.
    expect(propose(swapTerms).toState()).not.toHaveProperty(
      "offeredCopyOwnerId",
    );
  });
});

describe("accept", () => {
  it("lets the recipient accept a proposed exchange", () => {
    const ex = propose(swapTerms);
    ex.pullEvents();
    const r = ex.accept(bob, LATER);
    expect(r.isOk).toBe(true);
    expect(ex.status).toBe("accepted");
    expect(names(ex.pullEvents())).toEqual(["ExchangeAccepted"]);
  });

  it("rejects acceptance by the initiator (wrong party)", () => {
    const ex = propose(swapTerms);
    const r = ex.accept(alice, NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) {
      expect(r.error.code).toBe("WrongParty");
      // The action name is interpolated into the message; assert it so the per-action
      // string passed to requireParty is pinned (each guard names its own action).
      expect(r.error.message).toBe("Acting member may not accept");
    }
    expect(ex.status).toBe("proposed");
  });

  it("rejects acceptance by an unrelated member", () => {
    const ex = propose(swapTerms);
    const r = ex.accept(toMemberId("eve"), NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("WrongParty");
  });

  it("rejects accept from a non-proposed status (illegal transition)", () => {
    const ex = accepted();
    const r = ex.accept(bob, NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("IllegalTransition");
  });
});

describe("decline", () => {
  it("lets the recipient decline, moving to rejected", () => {
    const ex = propose(swapTerms);
    ex.pullEvents();
    const r = ex.decline(bob, NOW);
    expect(r.isOk).toBe(true);
    expect(ex.status).toBe("rejected");
    expect(names(ex.pullEvents())).toEqual(["ExchangeRejected"]);
  });

  it("rejects decline by the initiator", () => {
    const ex = propose(swapTerms);
    const r = ex.decline(alice, NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) {
      expect(r.error.code).toBe("WrongParty");
      expect(r.error.message).toBe("Acting member may not decline");
    }
  });

  it("cannot decline an already accepted exchange", () => {
    const ex = accepted();
    const r = ex.decline(bob, NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("IllegalTransition");
  });
});

describe("cancel", () => {
  it("lets the initiator cancel a proposed exchange", () => {
    const ex = propose(swapTerms);
    ex.pullEvents();
    const r = ex.cancel(alice, NOW);
    expect(r.isOk).toBe(true);
    expect(ex.status).toBe("cancelled");
    expect(names(ex.pullEvents())).toEqual(["ExchangeCancelled"]);
  });

  it("lets the initiator cancel an accepted exchange", () => {
    const ex = accepted();
    const r = ex.cancel(alice, NOW);
    expect(r.isOk).toBe(true);
    expect(ex.status).toBe("cancelled");
  });

  it("lets the recipient call off an accepted exchange", () => {
    const ex = accepted();
    const r = ex.cancel(bob, NOW);
    expect(r.isOk).toBe(true);
    expect(ex.status).toBe("cancelled");
    expect(names(ex.pullEvents())).toEqual(["ExchangeCancelled"]);
  });

  it.each([
    ["the initiator", alice],
    ["the recipient", bob],
  ])("names %s as the member who cancelled", (_, by) => {
    const ex = accepted();
    ex.cancel(by, NOW);
    const [event] = ex.pullEvents();
    expect(event).toBeInstanceOf(ExchangeCancelled);
    expect((event as ExchangeCancelled).cancelledBy).toBe(by);
    expect(event?.occurredAt).toBe(NOW);
  });

  it("rejects cancel of a pending request by the recipient (they decline it)", () => {
    const ex = propose(swapTerms);
    const r = ex.cancel(bob, NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) {
      expect(r.error.code).toBe("WrongParty");
      expect(r.error.message).toBe("Acting member may not cancel");
    }
    expect(ex.status).toBe("proposed");
  });

  it("rejects cancel of an accepted exchange by a non-party", () => {
    const ex = accepted();
    const r = ex.cancel(toMemberId("eve"), NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("WrongParty");
    expect(ex.status).toBe("accepted");
  });

  it("the recipient can't cancel a completed exchange", () => {
    const ex = accepted();
    ex.confirmCompletion(alice, NOW);
    ex.confirmCompletion(bob, NOW);
    const r = ex.cancel(bob, NOW);
    expect(r.isErr).toBe(true);
    expect(ex.status).toBe("completed");
  });

  it("cannot cancel a completed exchange", () => {
    const ex = accepted();
    ex.confirmCompletion(alice, NOW);
    ex.confirmCompletion(bob, NOW);
    const r = ex.cancel(alice, NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("IllegalTransition");
  });
});

describe("confirmCompletion (dual confirmation)", () => {
  it("a single confirmation does NOT complete the exchange", () => {
    const ex = accepted();
    const r = ex.confirmCompletion(alice, NOW);
    expect(r.isOk).toBe(true);
    expect(ex.status).toBe("accepted");
    expect(ex.pullEvents()).toHaveLength(0);
    expect(ex.toState().initiatorConfirmationTimestamp).toBe(NOW);
    expect(ex.toState().recipientConfirmationTimestamp).toBeUndefined();
  });

  it("both confirmations (any order) complete the exchange", () => {
    const ex = accepted();
    ex.confirmCompletion(bob, NOW);
    expect(ex.status).toBe("accepted");
    const r = ex.confirmCompletion(alice, LATER);
    expect(r.isOk).toBe(true);
    expect(ex.status).toBe("completed");
  });

  it("a repeated confirmation by the same party does not complete", () => {
    const ex = accepted();
    ex.confirmCompletion(alice, NOW);
    const r = ex.confirmCompletion(alice, LATER);
    expect(r.isOk).toBe(true);
    expect(ex.status).toBe("accepted");
  });

  it("rejects confirmation by an unrelated member", () => {
    const ex = accepted();
    const r = ex.confirmCompletion(toMemberId("eve"), NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) {
      expect(r.error.code).toBe("WrongParty");
      expect(r.error.message).toBe("Acting member may not confirm completion");
    }
  });

  it("cannot confirm completion from a proposed exchange (illegal transition)", () => {
    const ex = propose(swapTerms);
    const r = ex.confirmCompletion(alice, NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) {
      expect(r.error.code).toBe("IllegalTransition");
      expect(r.error.message).toBe(
        "Cannot transition from proposed to completed",
      );
    }
  });
});

describe("settlement events", () => {
  it("a swap transfers BOTH copies: requested→initiator, offered→recipient", () => {
    const ex = accepted(swapTerms);
    ex.confirmCompletion(alice, NOW);
    ex.confirmCompletion(bob, LATER);
    const events = ex.pullEvents();
    expect(names(events)).toEqual([
      "ExchangeCompleted",
      "OwnershipTransferred",
      "OwnershipTransferred",
    ]);
    const transfers = events.filter(
      (e): e is OwnershipTransferred => e.name === "OwnershipTransferred",
    );
    expect(transfers).toHaveLength(2);
    expect(transfers[0]).toMatchObject({ copyId: requested, newOwner: alice });
    expect(transfers[1]).toMatchObject({ copyId: offered, newOwner: bob });
  });

  // Library refuses a transfer whose copy no longer belongs to the expected previous owner, so a
  // settlement never moves a copy away from someone the deal wasn't made with.
  it("each transfer names the owner the deal was made with as the expected previous owner", () => {
    const carol = toMemberId("carol"); // alice's housemate, whose copy alice offered
    const ex = propose(swapTerms, { offeredCopyOwnerId: carol });
    ex.accept(bob, NOW);
    ex.confirmCompletion(alice, NOW);
    ex.confirmCompletion(bob, LATER);
    const transfers = ex
      .pullEvents()
      .filter(
        (e): e is OwnershipTransferred => e.name === "OwnershipTransferred",
      );
    expect(transfers[0]).toMatchObject({
      copyId: requested,
      expectedPreviousOwner: bob,
    });
    expect(transfers[1]).toMatchObject({
      copyId: offered,
      expectedPreviousOwner: carol,
    });
  });

  it("a sale transfers ONLY the requested copy to the initiator", () => {
    const ex = accepted(saleTerms());
    ex.confirmCompletion(alice, NOW);
    ex.confirmCompletion(bob, LATER);
    const transfers = ex
      .pullEvents()
      .filter(
        (e): e is OwnershipTransferred => e.name === "OwnershipTransferred",
      );
    expect(transfers).toHaveLength(1);
    expect(transfers[0]).toMatchObject({ copyId: requested, newOwner: alice });
  });

  it("a lend hands POSSESSION (not ownership) of the requested copy to the initiator", () => {
    const ex = accepted(lendTerms);
    ex.confirmCompletion(alice, NOW);
    ex.confirmCompletion(bob, LATER);
    const events = ex.pullEvents();
    expect(
      events.filter((e) => e.name === "OwnershipTransferred"),
    ).toHaveLength(0);
    const possession = events.filter(
      (e): e is PossessionTransferred => e.name === "PossessionTransferred",
    );
    expect(possession).toHaveLength(1);
    expect(possession[0]).toMatchObject({
      copyId: requested,
      borrower: alice,
      lender: bob, // Library opens the loan only while the recipient still owns the copy
    });
  });

  // The second transfer is guarded by `kind === "swap" && offeredCopyId`. Rehydrating
  // hand-crafted states isolates each half of that guard (states unreachable via propose()).
  const settle = (ex: Exchange): readonly OwnershipTransferred[] => {
    ex.confirmCompletion(alice, NOW);
    ex.confirmCompletion(bob, LATER);
    return ex
      .pullEvents()
      .filter(
        (e): e is OwnershipTransferred => e.name === "OwnershipTransferred",
      );
  };

  const acceptedState = (
    over: Partial<ReturnType<Exchange["toState"]>>,
  ): Exchange => {
    const base = accepted(swapTerms).toState();
    return Exchange.rehydrate({ ...base, ...over });
  };

  it("does NOT transfer an offered copy when the kind is not swap, even if one is present", () => {
    // kind=sale but offeredCopyId set: the `kind === \"swap\"` half must gate it out, so the
    // `&&`→`||` and `if (true)` mutants (which would emit a second transfer) die here.
    const ex = acceptedState({
      kind: "sale",
      offeredCopyId: offered,
      price: price(),
    });
    const transfers = settle(ex);
    expect(transfers).toHaveLength(1);
    expect(transfers[0]).toMatchObject({ copyId: requested, newOwner: alice });
  });

  it("does NOT transfer a second copy for a swap missing its offered copy", () => {
    // kind=swap but no offeredCopyId: the `offeredCopyId` half must gate it out, so the
    // `if (true)` mutant dies here.
    const ex = acceptedState({ kind: "swap", offeredCopyId: undefined });
    expect(settle(ex)).toHaveLength(1);
  });

  it("an offered copy whose owner was never recorded names no expected previous owner", () => {
    // A swap proposed before the owner was recorded: Library then transfers without the check.
    const transfers = settle(accepted(swapTerms));
    expect(transfers[1]?.copyId).toBe(offered);
    expect(transfers[1]?.expectedPreviousOwner).toBeUndefined();
  });

  it("records ExchangeCompleted exactly once on settlement", () => {
    const ex = accepted(saleTerms());
    ex.confirmCompletion(alice, NOW);
    ex.confirmCompletion(bob, LATER);
    const completed = ex
      .pullEvents()
      .filter((e) => e.name === "ExchangeCompleted");
    expect(completed).toHaveLength(1);
    expect(completed[0]).toBeInstanceOf(ExchangeCompleted);
  });
});

describe("raiseDispute", () => {
  it("either party can dispute an accepted exchange", () => {
    const exByRecipient = accepted();
    expect(exByRecipient.raiseDispute(bob, NOW).isOk).toBe(true);
    expect(exByRecipient.status).toBe("disputed");

    const exByInitiator = accepted();
    expect(exByInitiator.raiseDispute(alice, NOW).isOk).toBe(true);
    expect(exByInitiator.status).toBe("disputed");
    expect(names(exByInitiator.pullEvents())).toEqual(["DisputeRaised"]);
  });

  it("a completed exchange can still be disputed", () => {
    const ex = accepted();
    ex.confirmCompletion(alice, NOW);
    ex.confirmCompletion(bob, LATER);
    ex.pullEvents();
    const r = ex.raiseDispute(alice, LATER);
    expect(r.isOk).toBe(true);
    expect(ex.status).toBe("disputed");
  });

  it("rejects a dispute from an unrelated member", () => {
    const ex = accepted();
    const r = ex.raiseDispute(toMemberId("eve"), NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) {
      expect(r.error.code).toBe("WrongParty");
      expect(r.error.message).toBe("Acting member may not raise a dispute");
    }
  });

  it("cannot dispute a proposed exchange (illegal transition)", () => {
    const ex = propose(swapTerms);
    const r = ex.raiseDispute(alice, NOW);
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("IllegalTransition");
  });
});

describe("terminal states reject all moves", () => {
  let rejected: Exchange;
  let cancelled: Exchange;

  beforeEach(() => {
    rejected = propose(swapTerms);
    rejected.decline(bob, NOW);
    cancelled = propose(swapTerms);
    cancelled.cancel(alice, NOW);
  });

  it("a rejected exchange cannot be accepted or cancelled", () => {
    expect(rejected.accept(bob, NOW).isErr).toBe(true);
    expect(rejected.cancel(alice, NOW).isErr).toBe(true);
  });

  it("a cancelled exchange cannot be accepted or disputed", () => {
    expect(cancelled.accept(bob, NOW).isErr).toBe(true);
    expect(cancelled.raiseDispute(alice, NOW).isErr).toBe(true);
  });
});

describe("rehydrate / toState round-trip", () => {
  it("rehydrates from a persisted state without re-recording events", () => {
    const original = propose(saleTerms());
    const state = original.toState();
    const restored = Exchange.rehydrate(state);
    expect(restored.pullEvents()).toHaveLength(0);
    expect(restored.toState()).toEqual(state);
    expect(restored.status).toBe("proposed");
  });

  it("a rehydrated accepted exchange can still be driven to completion", () => {
    const ex = accepted(lendTerms);
    const restored = Exchange.rehydrate(ex.toState());
    restored.confirmCompletion(alice, NOW);
    const r = restored.confirmCompletion(bob, LATER);
    expect(r.isOk).toBe(true);
    expect(restored.status).toBe("completed");
  });
});

describe("pullEvents", () => {
  it("clears the buffer so events are not emitted twice", () => {
    const ex = propose(swapTerms);
    expect(ex.pullEvents()).toHaveLength(1);
    expect(ex.pullEvents()).toHaveLength(0);
  });
});

