// packages/domain/src/catalog/domain/extract-puzzle-draft.spec.ts
import { describe, expect, it } from "vitest";
import { extractPuzzleDraft } from "./extract-puzzle-draft";
import type { RawProductPage } from "./puzzle-import-draft";

const empty: RawProductPage = { ogImages: [], jsonLdProducts: [] };
const SRC = "https://shop.example.com/p/1";

describe("extractPuzzleDraft", () => {
  it("prefers JSON-LD Product fields (tier 1)", () => {
    const raw: RawProductPage = {
      ...empty,
      ogTitle: "OG fallback title",
      ogImages: ["https://img/og.jpg"],
      jsonLdProducts: [
        {
          name: "Ravensburger Mountain Vista 1000 pieces",
          brand: "Ravensburger",
          description: "A scenic 1000 piece puzzle",
          image: "https://img/product.jpg",
          gtin13: "4005556150007",
        },
      ],
    };
    const d = extractPuzzleDraft(raw, SRC);
    expect(d.title).toBe("Ravensburger Mountain Vista");
    expect(d.brand).toBe("Ravensburger");
    // JSON-LD image is first; OG image appended after (deduped).
    expect(d.images).toEqual(["https://img/product.jpg", "https://img/og.jpg"]);
    expect(d.imageUrl).toBe("https://img/product.jpg");
    expect(d.imageUrl).toBe(d.images[0]);
    expect(d.ean).toBe("4005556150007");
    expect(d.upc).toBeUndefined();
    expect(d.pieceCount).toBe(1000);
    expect(d.sourceUrl).toBe(SRC);
  });

  it("falls back to OpenGraph then <title> (tiers 2-3)", () => {
    expect(
      extractPuzzleDraft(
        {
          ...empty,
          ogTitle: "OG Puzzle 500 stukjes",
          ogImages: ["https://img/og.jpg"],
        },
        SRC,
      ).title,
    ).toBe("OG");
    expect(
      extractPuzzleDraft({ ...empty, basicTitle: "Basic 750 Teile" }, SRC)
        .title,
    ).toBe("Basic");
  });

  it("parses multilingual piece counts incl. thousands separators", () => {
    const pc = (title: string) =>
      extractPuzzleDraft({ ...empty, basicTitle: title }, SRC).pieceCount;
    expect(pc("Puzzle 1000 pieces")).toBe(1000);
    expect(pc("Legpuzzel 1.000 stukjes")).toBe(1000);
    expect(pc("Puzzle 1,500 pcs")).toBe(1500);
    expect(pc("Puzzle 500 Teile")).toBe(500);
    expect(pc("Rompecabezas 2000 piezas")).toBe(2000);
    expect(pc("No count here")).toBeUndefined();
  });

  it("maps gtin12 to upc", () => {
    const d = extractPuzzleDraft(
      { ...empty, jsonLdProducts: [{ name: "X", gtin12: "036000291452" }] },
      SRC,
    );
    expect(d.upc).toBe("036000291452");
    expect(d.ean).toBeUndefined();
  });

  it("returns an empty title when nothing is extractable", () => {
    expect(extractPuzzleDraft(empty, SRC).title).toBe("");
  });

  it("collects multiple JSON-LD images then OG images, deduped, capped at 8", () => {
    const raw: RawProductPage = {
      ...empty,
      ogImages: [
        "https://img/og1.jpg",
        "https://img/product-a.jpg", // duplicate of JSON-LD; should be dropped
        "https://img/og2.jpg",
      ],
      jsonLdProducts: [
        {
          name: "Puzzle",
          image: ["https://img/product-a.jpg", "https://img/product-b.jpg"],
        },
      ],
    };
    const d = extractPuzzleDraft(raw, SRC);
    // JSON-LD images come first; OG images follow with duplicates removed.
    expect(d.images).toEqual([
      "https://img/product-a.jpg",
      "https://img/product-b.jpg",
      "https://img/og1.jpg",
      "https://img/og2.jpg",
    ]);
    expect(d.imageUrl).toBe(d.images[0]);
  });

  it("excludes non-http(s) URLs and imageUrl is undefined when no images present", () => {
    const d = extractPuzzleDraft(empty, SRC);
    expect(d.images).toEqual([]);
    expect(d.imageUrl).toBeUndefined();
  });

  // --- Targeted mutation-killing tests below ---

  const pcFromTitle = (title: string) =>
    extractPuzzleDraft({ ...empty, basicTitle: title }, SRC).pieceCount;

  describe("piece-count bounds (parsePieceCount L18)", () => {
    // Lower bound `n >= 1`: 0 must be rejected. Kills `n >= 1` -> true and the
    // `... || n <= 100000` logical mutant (which would let 0 through via the OR).
    it("rejects a zero count", () => {
      expect(pcFromTitle("Puzzle 0 pieces")).toBeUndefined();
    });

    // `n >= 1` boundary: exactly 1 must be ACCEPTED. Kills the `n > 1` equality mutant.
    it("accepts a count of exactly 1", () => {
      expect(pcFromTitle("Puzzle 1 piece")).toBe(1);
    });

    // Upper bound `n <= 100000` boundary: exactly 100000 must be ACCEPTED.
    // Kills the `n < 100000` equality mutant.
    it("accepts a count of exactly 100000", () => {
      expect(pcFromTitle("Puzzle 100000 pieces")).toBe(100000);
    });

    // Upper bound: above the cap must be rejected. Kills `n <= 100000` -> true and the
    // `Number.isFinite(n) || n >= 1` logical mutant (which drops the upper bound entirely).
    it("rejects a count above 100000", () => {
      expect(pcFromTitle("Puzzle 200000 pieces")).toBeUndefined();
    });
  });

  describe("piece-count regex (PIECE_COUNT_RE L12)", () => {
    // `\s` inside the digit class: a space-separated thousands group must parse.
    // Kills `[\d.,\S]` (which would no longer accept the space).
    it("parses space-separated thousands", () => {
      expect(pcFromTitle("Puzzle 10 000 pieces")).toBe(10000);
    });

    // `\s*` (zero-or-more) between number and unit: no space must still match.
    // Kills `\s` (exactly one required space).
    it("parses a count with no space before the unit", () => {
      expect(pcFromTitle("Puzzle 1000pieces")).toBe(1000);
    });

    // Optional trailing `s` in `pieces?`: singular "piece" must match.
    // Kills `pieces` (mandatory plural).
    it("parses a singular 'piece' unit", () => {
      expect(pcFromTitle("Puzzle 500 piece")).toBe(500);
    });

    // Second alternation `\d` (single-digit fallback): a lone digit + unit must match.
    // Kills `\D` in the second alternative.
    it("parses a single-digit count", () => {
      expect(pcFromTitle("Puzzle 5 pcs")).toBe(5);
    });

    // First-alternative trailing `\d`: a multi-digit count ending in a digit must parse
    // as a whole. Kills `\D` at the end of the first alternative (which would force the
    // single-digit fallback and mis-capture).
    it("parses a two-digit count keeping both digits", () => {
      expect(pcFromTitle("Puzzle 24 pieces")).toBe(24);
    });

    // French accented unit `pi[eè]ces`: "pièces" must match.
    // Kills `pi[^eè]ces` (negated class no longer matches è).
    it("parses the French accented 'pièces' unit", () => {
      expect(pcFromTitle("Casse-tête 1000 pièces")).toBe(1000);
    });
  });

  describe("image URL filtering (HTTP_RE L31 + typeof guard L40)", () => {
    // `^` anchor: a scheme embedded mid-string must NOT count as http(s).
    // Kills `/https?:\/\//` (no anchor), which would match "https://" inside the string.
    it("rejects a URL where http(s) appears only mid-string", () => {
      const d = extractPuzzleDraft(
        { ...empty, ogImages: ["data:https://evil/x.png"] },
        SRC,
      );
      expect(d.images).toEqual([]);
      expect(d.imageUrl).toBeUndefined();
    });

    // Optional `s` in `https?`: a plain http:// URL must be accepted.
    // Kills `/^https:\/\//` (https-only).
    it("accepts a plain http:// image URL", () => {
      const d = extractPuzzleDraft(
        { ...empty, ogImages: ["http://img/plain.jpg"] },
        SRC,
      );
      expect(d.images).toEqual(["http://img/plain.jpg"]);
    });

    // `typeof url === "string"` guard + the `&&` chain: a non-http string must be excluded.
    // Kills `typeof url === "string"` -> true and the `|| HTTP_RE.test(url)` logical mutant
    // (an OR would admit this string via the truthy typeof check).
    it("excludes a non-http(s) string URL such as ftp://", () => {
      const d = extractPuzzleDraft(
        { ...empty, ogImages: ["ftp://img/x.jpg", "https://img/ok.jpg"] },
        SRC,
      );
      expect(d.images).toEqual(["https://img/ok.jpg"]);
    });

    // `typeof url === "string"` guard against a non-string candidate (an ImageObject can
    // leak a non-string into the JSON-LD image array at runtime). A number must be excluded.
    // Kills the `typeof url === "string"` -> true conditional mutant.
    it("excludes a non-string image candidate", () => {
      const raw = {
        ...empty,
        jsonLdProducts: [
          {
            name: "Puzzle",
            // Deliberately malformed: a non-string slips into the image array.
            image: [42 as unknown as string, "https://img/ok.jpg"],
          },
        ],
      } as RawProductPage;
      const d = extractPuzzleDraft(raw, SRC);
      expect(d.images).toEqual(["https://img/ok.jpg"]);
    });
  });

  describe("toImageArray null handling (L24)", () => {
    // When the JSON-LD product has no image, only the OG images survive — never a sentinel
    // or an `undefined` entry. Kills `if (image == null)` -> false (which yields `[undefined]`)
    // and the `["Stryker was here"]` array-declaration mutant.
    it("uses only OG images when the product has no image field", () => {
      const d = extractPuzzleDraft(
        {
          ...empty,
          ogImages: ["https://img/og.jpg"],
          jsonLdProducts: [{ name: "Puzzle" }],
        },
        SRC,
      );
      expect(d.images).toEqual(["https://img/og.jpg"]);
      expect(d.images).not.toContain("Stryker was here");
      expect(d.images.every((u) => typeof u === "string")).toBe(true);
    });
  });

  describe("image cap (result.length < MAX_IMAGES L43)", () => {
    // Exactly 9 distinct http images: only the first 8 are kept (cap is 8).
    // Kills `< MAX_IMAGES` -> `<= MAX_IMAGES` (would keep 9) and `-> true` (no cap).
    it("caps the image list at 8 and drops the 9th", () => {
      const nine = Array.from({ length: 9 }, (_, i) => `https://img/${i}.jpg`);
      const d = extractPuzzleDraft({ ...empty, ogImages: nine }, SRC);
      expect(d.images).toHaveLength(8);
      expect(d.images).toEqual(nine.slice(0, 8));
      expect(d.images).not.toContain("https://img/8.jpg");
    });
  });

  describe("gtin length-based barcode mapping (L57 / L60)", () => {
    // A 13-char `gtin` (no explicit gtin13) maps to ean. Kills `gtin?.length === 13` -> false.
    it("maps a 13-digit gtin to ean", () => {
      const d = extractPuzzleDraft(
        { ...empty, jsonLdProducts: [{ name: "X", gtin: "4005556150007" }] },
        SRC,
      );
      expect(d.ean).toBe("4005556150007");
      expect(d.upc).toBeUndefined();
    });

    // A 12-char `gtin` (no explicit gtin12) maps to upc. Kills `gtin?.length === 12` -> false.
    it("maps a 12-digit gtin to upc", () => {
      const d = extractPuzzleDraft(
        { ...empty, jsonLdProducts: [{ name: "X", gtin: "036000291452" }] },
        SRC,
      );
      expect(d.upc).toBe("036000291452");
      expect(d.ean).toBeUndefined();
    });

    // A gtin of some other length maps to neither (guards that the length checks are real).
    it("ignores a gtin of non-12/13 length", () => {
      const d = extractPuzzleDraft(
        { ...empty, jsonLdProducts: [{ name: "X", gtin: "12345" }] },
        SRC,
      );
      expect(d.ean).toBeUndefined();
      expect(d.upc).toBeUndefined();
    });
  });

  describe("clean() trimming (L65)", () => {
    // Surrounding whitespace on brand must be trimmed. Kills `value?.trim()` -> `value`.
    it("trims surrounding whitespace from brand", () => {
      const d = extractPuzzleDraft(
        {
          ...empty,
          jsonLdProducts: [{ name: "Puzzle", brand: "  Ravensburger  " }],
        },
        SRC,
      );
      expect(d.brand).toBe("Ravensburger");
    });

    // A whitespace-only brand collapses to undefined (trimmed -> "" -> undefined).
    // Also kills `value?.trim()` -> `value` (which leaves a truthy "   " and returns it).
    it("treats a whitespace-only brand as undefined", () => {
      const d = extractPuzzleDraft(
        { ...empty, jsonLdProducts: [{ name: "Puzzle", brand: "   " }] },
        SRC,
      );
      expect(d.brand).toBeUndefined();
    });

    // Surrounding whitespace on description must be trimmed.
    it("trims surrounding whitespace from description", () => {
      const d = extractPuzzleDraft(
        {
          ...empty,
          jsonLdProducts: [{ name: "Puzzle", description: "  A nice scene  " }],
        },
        SRC,
      );
      expect(d.description).toBe("A nice scene");
    });
  });

  describe("description tier fallback (?? chain L84)", () => {
    // Only basicDescription present: description must equal it.
    // Kills `(product?.description ?? raw.ogDescription) && raw.basicDescription`
    // (the AND yields undefined because the left side is undefined).
    it("falls back to basicDescription when higher tiers are absent", () => {
      const d = extractPuzzleDraft(
        { ...empty, basicTitle: "T", basicDescription: "Basic desc" },
        SRC,
      );
      expect(d.description).toBe("Basic desc");
    });

    // Only ogDescription present: description must equal it.
    // Kills `product?.description && raw.ogDescription`
    // (the AND yields undefined because product description is absent).
    it("falls back to ogDescription when product description is absent", () => {
      const d = extractPuzzleDraft(
        { ...empty, ogTitle: "T", ogDescription: "OG desc" },
        SRC,
      );
      expect(d.description).toBe("OG desc");
    });

    // Product description wins over the lower tiers.
    it("prefers the product description over og/basic", () => {
      const d = extractPuzzleDraft(
        {
          ...empty,
          ogDescription: "OG desc",
          basicDescription: "Basic desc",
          jsonLdProducts: [{ name: "P", description: "Product desc" }],
        },
        SRC,
      );
      expect(d.description).toBe("Product desc");
    });
  });

  describe("piece-count parsed across title AND description (L89)", () => {
    // The count lives ONLY in the description; it must still be found because the parser
    // runs over `${rawTitle} ${description}`. Kills `description ?? ""` -> `description && ""`
    // (the AND collapses the description to "" and the count is lost).
    it("finds the piece count when it is only in the description", () => {
      const d = extractPuzzleDraft(
        {
          ...empty,
          basicTitle: "Mountain Scene",
          basicDescription: "Beautiful 1500 pieces jigsaw",
        },
        SRC,
      );
      expect(d.pieceCount).toBe(1500);
    });
  });

  describe("imageAlts (pickAlts)", () => {
    it("carries alt text for surviving images, keyed by URL", () => {
      const d = extractPuzzleDraft(
        {
          ...empty,
          ogImages: ["https://img/a.jpg", "https://img/b.jpg"],
          imageAlts: {
            "https://img/a.jpg": "Box front",
            "https://img/b.jpg": "Box back",
          },
        },
        SRC,
      );
      expect(d.imageAlts).toEqual({
        "https://img/a.jpg": "Box front",
        "https://img/b.jpg": "Box back",
      });
    });

    it("drops alt entries whose image was filtered out (non-http / capped)", () => {
      // The ftp URL is dropped from `images`, so its alt must not appear in the draft.
      const d = extractPuzzleDraft(
        {
          ...empty,
          ogImages: ["ftp://img/bad.jpg", "https://img/ok.jpg"],
          imageAlts: {
            "ftp://img/bad.jpg": "Dropped",
            "https://img/ok.jpg": "Kept",
          },
        },
        SRC,
      );
      expect(d.images).toEqual(["https://img/ok.jpg"]);
      expect(d.imageAlts).toEqual({ "https://img/ok.jpg": "Kept" });
    });

    it("is undefined when the page carries no alt map", () => {
      const d = extractPuzzleDraft(
        { ...empty, ogImages: ["https://img/a.jpg"] },
        SRC,
      );
      expect(d.imageAlts).toBeUndefined();
    });

    it("is undefined when no surviving image has alt text", () => {
      const d = extractPuzzleDraft(
        {
          ...empty,
          ogImages: ["https://img/a.jpg"],
          imageAlts: { "https://img/other.jpg": "Not in the set" },
        },
        SRC,
      );
      expect(d.imageAlts).toBeUndefined();
    });
  });
});

describe("buildImages format filtering", () => {
  it("drops candidates with extensions the import action always rejects", () => {
    const draft = extractPuzzleDraft(
      {
        ...empty,
        ogImages: [
          "https://cdn.shop.example/logo.svg",
          "https://cdn.shop.example/box.jpg",
          "https://cdn.shop.example/fav.ico?v=3",
          "https://cdn.shop.example/i/no-extension",
        ],
      },
      "https://shop.example/puzzle",
    );
    expect(draft.images).toEqual([
      "https://cdn.shop.example/box.jpg",
      "https://cdn.shop.example/i/no-extension",
    ]);
    expect(draft.imageUrl).toBe("https://cdn.shop.example/box.jpg");
  });
});

src/exchange/application/use-cases/propo.source:
import { beforeEach, describe, expect, it } from "vitest";
import { toCopyId, toMemberId } from "../../../shared-kernel";
import { ExchangeTermsInput, Money } from "../../domain";
import { CopyView } from "../ports/out/copy.port";
import {
  FakeCopyPort,
  FakeExchangeEligibilityPort,
  FixedClock,
  InMemoryExchangeRepository,
  RecordingEventPublisher,
  SequentialIdGenerator,
} from "../testing";
import {
  isLentOut,
  makeProposeExchange,
  mayOfferCopy,
} from "./propose-exchange";

const alice = toMemberId("alice"); // initiator
const bob = toMemberId("bob"); // recipient
const requestedId = toCopyId("requested");
const offeredId = toCopyId("offered");
const NOW = new Date("2026-06-08T10:00:00Z");

const price = (): Money => {
  const m = Money.create(2500, "EUR");
  if (!m.isOk) throw new Error("setup");
  return m.value;
};

// A copy with all availability flags off; tests turn on exactly what they need.
const copy = (
  over: Partial<CopyView> & Pick<CopyView, "id" | "ownerId">,
): CopyView => ({
  availability: { forTrade: false, forSale: false, forLend: false },
  ...over,
});

describe("makeProposeExchange", () => {
  let repo: InMemoryExchangeRepository;
  let copies: FakeCopyPort;
  let events: RecordingEventPublisher;
  let eligibility: FakeExchangeEligibilityPort;
  let propose: ReturnType<typeof makeProposeExchange>;

  beforeEach(() => {
    repo = new InMemoryExchangeRepository();
    copies = new FakeCopyPort();
    events = new RecordingEventPublisher();
    eligibility = new FakeExchangeEligibilityPort();
    propose = makeProposeExchange({
      exchanges: repo,
      copies,
      eligibility,
      ids: new SequentialIdGenerator(),
      events,
      clock: new FixedClock(NOW),
    });
  });

  const swapTerms: ExchangeTermsInput = {
    kind: "swap",
    offeredCopyId: offeredId,
  };
  const saleTerms = (): ExchangeTermsInput => ({
    kind: "sale",
    price: price(),
  });
  const lendTerms: ExchangeTermsInput = {
    kind: "lend",
    returnDate: new Date("2026-06-20T10:00:00Z"),
  };

  it("proposes a swap, saving state and publishing ExchangeProposed", async () => {
    copies
      .seed(
        copy({
          id: requestedId,
          ownerId: bob,
          availability: { forTrade: true, forSale: false, forLend: false },
        }),
      )
      .seed(copy({ id: offeredId, ownerId: alice }));

    const result = await propose({
      initiatorId: alice,
      recipientId: bob,
      kind: "swap",
      requestedCopyId: requestedId,
      terms: swapTerms,
    });

    expect(result.isOk).toBe(true);
    expect(repo.size()).toBe(1);
    expect(events.names()).toEqual(["ExchangeProposed"]);
  });

  it("rejects a duplicate active proposal for the same requested copy", async () => {
    copies
      .seed(
        copy({
          id: requestedId,
          ownerId: bob,
          availability: { forTrade: true, forSale: false, forLend: false },
        }),
      )
      .seed(copy({ id: offeredId, ownerId: alice }));
    const cmd = {
      initiatorId: alice,
      recipientId: bob,
      kind: "swap" as const,
      requestedCopyId: requestedId,
      terms: swapTerms,
    };
    expect((await propose(cmd)).isOk).toBe(true);

    const second = await propose(cmd);
    expect(second.isErr).toBe(true);
    if (second.isErr) expect(second.error.code).toBe("DuplicateProposal");
    expect(repo.size()).toBe(1); // no second exchange written
  });

  it("rejects when the requested copy does not exist", async () => {
    const result = await propose({
      initiatorId: alice,
      recipientId: bob,
      kind: "sale",
      requestedCopyId: requestedId,
      terms: saleTerms(),
    });
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("CopyNotFound");
    expect(events.published).toHaveLength(0);
  });

  // The CORRECTED availability direction: available ⇒ ok, unavailable ⇒ reject.
  describe("availability is checked per kind (corrected direction)", () => {
    it.each<["swap" | "sale" | "lend", keyof CopyView["availability"]]>([
      ["swap", "forTrade"],
      ["sale", "forSale"],
      ["lend", "forLend"],
    ])("%s proceeds only when %s is true", async (kind, flag) => {
      const terms: ExchangeTermsInput =
        kind === "swap" ? swapTerms : kind === "sale" ? saleTerms() : lendTerms;

      // available ⇒ ok
      const available = new FakeCopyPort()
        .seed(
          copy({
            id: requestedId,
            ownerId: bob,
            availability: {
              forTrade: false,
              forSale: false,
              forLend: false,
              [flag]: true,
            },
          }),
        )
        .seed(copy({ id: offeredId, ownerId: alice }));
      const okEvents = new RecordingEventPublisher();
      const proposeOk = makeProposeExchange({
        exchanges: new InMemoryExchangeRepository(),
        copies: available,
        eligibility: new FakeExchangeEligibilityPort(),
        ids: new SequentialIdGenerator(),
        events: okEvents,
        clock: new FixedClock(NOW),
      });
      const okRes = await proposeOk({
        initiatorId: alice,
        recipientId: bob,
        kind,
        requestedCopyId: requestedId,
        terms,
      });
      expect(okRes.isOk).toBe(true);
      expect(okEvents.names()).toEqual(["ExchangeProposed"]);

      // unavailable ⇒ reject
      const unavailable = new FakeCopyPort()
        .seed(copy({ id: requestedId, ownerId: bob }))
        .seed(copy({ id: offeredId, ownerId: alice }));
      const proposeReject = makeProposeExchange({
        exchanges: new InMemoryExchangeRepository(),
        copies: unavailable,
        eligibility: new FakeExchangeEligibilityPort(),
        ids: new SequentialIdGenerator(),
        events: new RecordingEventPublisher(),
        clock: new FixedClock(NOW),
      });
      const rejectRes = await proposeReject({
        initiatorId: alice,
        recipientId: bob,
        kind,
        requestedCopyId: requestedId,
        terms,
      });
      expect(rejectRes.isErr).toBe(true);
      if (rejectRes.isErr)
        expect(rejectRes.error.code).toBe("CopyNotAvailable");
    });
  });

  it("rejects with NotPermittedInCircle when the eligibility port refuses", async () => {
    copies.seed(
      copy({
        id: requestedId,
        ownerId: bob,
        availability: { forTrade: false, forSale: true, forLend: false },
      }),
    );
    eligibility.deny();

    const result = await propose({
      initiatorId: alice,
      recipientId: bob,
      kind: "sale",
      requestedCopyId: requestedId,
      terms: saleTerms(),
    });

    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("NotPermittedInCircle");
    expect(repo.size()).toBe(0);
    expect(events.published).toHaveLength(0);
  });

  it.each(["direct", "circle"] as const)(
    "records that the initiator was eligible via %s",
    async (via) => {
      copies.seed(
        copy({
          id: requestedId,
          ownerId: bob,
          availability: { forTrade: false, forSale: true, forLend: false },
        }),
      );
      eligibility.allowVia(via);

      const result = await propose({
        initiatorId: alice,
        recipientId: bob,
        kind: "sale",
        requestedCopyId: requestedId,
        terms: saleTerms(),
      });

      if (!result.isOk) throw new Error("expected ok");
      expect((await repo.findById(result.value))?.toState().eligibleVia).toBe(
        via,
      );
    },
  );

  it("rejects a swap whose offered copy is not owned by the initiator", async () => {
    copies
      .seed(
        copy({
          id: requestedId,
          ownerId: bob,
          availability: { forTrade: true, forSale: false, forLend: false },
        }),
      )
      .seed(copy({ id: offeredId, ownerId: bob })); // offered owned by recipient, not initiator

    const result = await propose({
      initiatorId: alice,
      recipientId: bob,
      kind: "swap",
      requestedCopyId: requestedId,
      terms: swapTerms,
    });
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("OfferedCopyNotOwned");
  });

  it("accepts a swap offering a household copy the initiator co-manages", async () => {
    const carol = toMemberId("carol"); // alice's household mate, owner of the offered copy
    copies
      .seed(
        copy({
          id: requestedId,
          ownerId: bob,
          availability: { forTrade: true, forSale: false, forLend: false },
        }),
      )
      .seed(copy({ id: offeredId, ownerId: carol, coManagerIds: [alice] }));

    const result = await propose({
      initiatorId: alice,
      recipientId: bob,
      kind: "swap",
      requestedCopyId: requestedId,
      terms: swapTerms,
    });
    expect(result.isOk).toBe(true);
  });

  // Settlement later checks the offered copy still has this owner (settlement-guard), so a swap
  // can't move a copy that changed hands since, nor one whose owner is no longer the one offered.
  it.each([
    ["the initiator's own copy", "alice", []],
    ["a housemate's co-managed copy", "carol", ["alice"]],
  ])(
    "records who owned the offered copy when the swap was proposed: %s",
    async (_label, owner, coManagers) => {
      copies
        .seed(
          copy({
            id: requestedId,
            ownerId: bob,
            availability: { forTrade: true, forSale: false, forLend: false },
          }),
        )
        .seed(
          copy({
            id: offeredId,
            ownerId: toMemberId(owner),
            coManagerIds: coManagers.map(toMemberId),
          }),
        );

      const result = await propose({
        initiatorId: alice,
        recipientId: bob,
        kind: "swap",
        requestedCopyId: requestedId,
        terms: swapTerms,
      });

      if (!result.isOk) throw new Error("expected ok");
      expect(
        (await repo.findById(result.value))?.toState().offeredCopyOwnerId,
      ).toBe(toMemberId(owner));
    },
  );

  it("records no offered owner for a sale", async () => {
    copies.seed(
      copy({
        id: requestedId,
        ownerId: bob,
        availability: { forTrade: false, forSale: true, forLend: false },
      }),
    );

    const result = await propose({
      initiatorId: alice,
      recipientId: bob,
      kind: "sale",
      requestedCopyId: requestedId,
      terms: saleTerms(),
    });

    if (!result.isOk) throw new Error("expected ok");
    expect((await repo.findById(result.value))?.toState()).not.toHaveProperty(
      "offeredCopyOwnerId",
    );
  });

  it("rejects a swap offering a copy the initiator neither owns nor co-manages", async () => {
    const carol = toMemberId("carol");
    copies
      .seed(
        copy({
          id: requestedId,
          ownerId: bob,
          availability: { forTrade: true, forSale: false, forLend: false },
        }),
      )
      .seed(copy({ id: offeredId, ownerId: carol, coManagerIds: [] }));

    const result = await propose({
      initiatorId: alice,
      recipientId: bob,
      kind: "swap",
      requestedCopyId: requestedId,
      terms: swapTerms,
    });
    expect(result.isErr && result.error.code).toBe("OfferedCopyNotOwned");
  });

  it("rejects a swap offering the recipient's own copy back, even when co-managed", async () => {
    copies
      .seed(
        copy({
          id: requestedId,
          ownerId: bob,
          availability: { forTrade: true, forSale: false, forLend: false },
        }),
      )
      .seed(copy({ id: offeredId, ownerId: bob, coManagerIds: [alice] }));

    const result = await propose({
      initiatorId: alice,
      recipientId: bob,
      kind: "swap",
      requestedCopyId: requestedId,
      terms: swapTerms,
    });
    expect(result.isErr && result.error.code).toBe("OfferedCopyNotOwned");
  });

  it("rejects a swap whose offered copy does not exist", async () => {
    copies.seed(
      copy({
        id: requestedId,
        ownerId: bob,
        availability: { forTrade: true, forSale: false, forLend: false },
      }),
    );

    const result = await propose({
      initiatorId: alice,
      recipientId: bob,
      kind: "swap",
      requestedCopyId: requestedId,
      terms: swapTerms,
    });
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("CopyNotFound");
  });

  // A copy out on loan is at the borrower's: it can't be asked for, nor offered, until it is back.
  describe("a copy out on loan", () => {
    const eve = toMemberId("eve"); // the borrower

    it("rejects asking for it with CopyNotAvailable, even while it is still offered", async () => {
      copies.seed(
        copy({
          id: requestedId,
          ownerId: bob,
          heldBy: eve,
          availability: { forTrade: false, forSale: true, forLend: true },
        }),
      );
      const result = await propose({
        initiatorId: alice,
        recipientId: bob,
        kind: "sale",
        requestedCopyId: requestedId,
        terms: saleTerms(),
      });
      expect(result.isErr && result.error.code).toBe("CopyNotAvailable");
      expect(events.published).toHaveLength(0);
      expect(repo.size()).toBe(0);
    });

    it("rejects offering it in a swap with CopyReserved", async () => {
      copies
        .seed(
          copy({
            id: requestedId,
            ownerId: bob,
            availability: { forTrade: true, forSale: false, forLend: false },
          }),
        )
        .seed(copy({ id: offeredId, ownerId: alice, heldBy: eve }));
      const result = await propose({
        initiatorId: alice,
        recipientId: bob,
        kind: "swap",
        requestedCopyId: requestedId,
        terms: swapTerms,
      });
      expect(result.isErr && result.error.code).toBe("CopyReserved");
      if (result.isErr) expect(result.error.message).toContain(offeredId);
      expect(events.published).toHaveLength(0);
    });
  });

  it("rejects when the requested copy is not owned by the named recipient", async () => {
    // carol owns the requested copy, but the proposal names bob as the recipient.
    const carol = toMemberId("carol");
    copies
      .seed(
        copy({
          id: requestedId,
          ownerId: carol,
          availability: { forTrade: false, forSale: true, forLend: false },
        }),
      )
      .seed(copy({ id: offeredId, ownerId: alice }));

    const result = await propose({
      initiatorId: alice,
      recipientId: bob,
      kind: "sale",
      requestedCopyId: requestedId,
      terms: saleTerms(),
    });
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("RecipientNotOwner");
    expect(events.published).toHaveLength(0);
  });

  it("delegates self-exchange rejection to the aggregate", async () => {
    copies.seed(
      copy({
        id: requestedId,
        ownerId: alice,
        availability: { forTrade: false, forSale: true, forLend: false },
      }),
    );

    const result = await propose({
      initiatorId: alice,
      recipientId: alice,
      kind: "sale",
      requestedCopyId: requestedId,
      terms: saleTerms(),
    });
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("SelfExchange");
    expect(events.published).toHaveLength(0);
  });
});

describe("mayOfferCopy", () => {
  const carol = toMemberId("carol"); // a third member

  it("allows a copy the initiator owns", () => {
    expect(
      mayOfferCopy(copy({ id: offeredId, ownerId: alice }), alice, bob),
    ).toBe(true);
  });

  it("allows a household copy the initiator co-manages", () => {
    const c = copy({ id: offeredId, ownerId: carol, coManagerIds: [alice] });
    expect(mayOfferCopy(c, alice, bob)).toBe(true);
  });

  it("rejects a copy the initiator neither owns nor co-manages", () => {
    expect(
      mayOfferCopy(copy({ id: offeredId, ownerId: carol }), alice, bob),
    ).toBe(false);
  });

  it("rejects the recipient's own copy, even when co-managed", () => {
    const c = copy({ id: offeredId, ownerId: bob, coManagerIds: [alice] });
    expect(mayOfferCopy(c, alice, bob)).toBe(false);
  });
});

describe("isLentOut", () => {
  it("is false for a copy with no recorded holder (held by its owner)", () => {
    expect(isLentOut(copy({ id: offeredId, ownerId: alice }))).toBe(false);
  });

  it("is false for a copy held by its owner", () => {
    expect(
      isLentOut(copy({ id: offeredId, ownerId: alice, heldBy: alice })),
    ).toBe(false);
  });

  it("is true for a copy someone else holds", () => {
    expect(
      isLentOut(copy({ id: offeredId, ownerId: alice, heldBy: bob })),
    ).toBe(true);
  });
});

src/solving/application/use-cases/goal-u.source:
import { beforeEach, describe, expect, it } from "vitest";
import {
  toGoalId,
  toMemberId,
  toPuzzleDefinitionId,
} from "../../../shared-kernel";
import { Goal, GoalId } from "../../domain";
import {
  FixedClock,
  InMemoryCompletionRepository,
  InMemoryGoalRepository,
  RecordingEventPublisher,
  SequentialCompletionIdGenerator,
  SequentialGoalIdGenerator,
} from "../testing";
import { makeCreateGoal } from "./create-goal";
import { makeDeleteGoal } from "./delete-goal";
import { makeRecomputeGoalProgress } from "./recompute-goal-progress";
import { makeRecordCompletion } from "./record-completion";
import { makeSetGoalArchived } from "./set-goal-archived";
import { makeUpdateGoal } from "./update-goal";

const ALICE = toMemberId("alice");
const BOB = toMemberId("bob");
const PUZZLE = toPuzzleDefinitionId("puzzle-1");
const START = new Date("2026-06-01T10:00:00Z");
const END = new Date("2026-06-01T11:30:00Z");
const NOW = new Date("2026-06-01T12:00:00Z");
const LATER = new Date("2026-06-03T12:00:00Z");
const THIS_YEAR = {
  startDate: new Date("2026-01-01T00:00:00Z"),
  targetDate: new Date("2026-12-31T00:00:00Z"),
};

describe("Goal use cases", () => {
  let goals: InMemoryGoalRepository;
  let completions: InMemoryCompletionRepository;
  let events: RecordingEventPublisher;
  let clock: FixedClock;
  let completionIds: SequentialCompletionIdGenerator;
  let goalIds: SequentialGoalIdGenerator;

  beforeEach(() => {
    goals = new InMemoryGoalRepository();
    completions = new InMemoryCompletionRepository();
    events = new RecordingEventPublisher();
    clock = new FixedClock(NOW);
    completionIds = new SequentialCompletionIdGenerator();
    goalIds = new SequentialGoalIdGenerator();
  });

  const createGoal = () =>
    makeCreateGoal({ goals, completions, ids: goalIds, events, clock });

  const recompute = () =>
    makeRecomputeGoalProgress({ goals, completions, events, clock });

  const record = () =>
    makeRecordCompletion({ completions, ids: completionIds, events, clock });

  // A finished solve dated to the day; by default today, inside a goal created today.
  const recordCompletion = async (
    startDate: Date = START,
    endDate: Date = END,
  ) => {
    const r = await record()({
      userId: ALICE,
      puzzleDefinitionId: PUZZLE,
      startDate,
      endDate,
    });
    if (!r.isOk) throw new Error("setup failed");
  };

  const recordYearOnly = async (year: number) => {
    const r = await record()({
      userId: ALICE,
      puzzleDefinitionId: PUZZLE,
      datePrecision: "year",
      year,
    });
    if (!r.isOk) throw new Error("setup failed");
  };

  const seedGoal = async (
    target: number,
    period: { startDate?: Date; targetDate?: Date } = {},
  ): Promise<GoalId> => {
    const result = await createGoal()({
      userId: ALICE,
      title: `Solve ${target}`,
      targetCompletions: target,
      ...period,
    });
    if (!result.isOk) throw new Error("setup failed");
    return result.value;
  };

  const stored = async (id: GoalId) => {
    const goal = await goals.findById(id);
    if (!goal) throw new Error("goal missing");
    return goal;
  };

  describe("createGoal", () => {
    it("persists a goal and publishes GoalCreated", async () => {
      const result = await createGoal()({
        userId: ALICE,
        title: "Solve 2",
        targetCompletions: 2,
      });
      expect(result.isOk).toBe(true);
      expect(goals.size()).toBe(1);
      expect(events.names()).toEqual(["GoalCreated"]);
    });

    it("rejects a non-positive target with InvalidGoalTarget", async () => {
      const result = await createGoal()({
        userId: ALICE,
        title: "bad",
        targetCompletions: 0,
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("InvalidGoalTarget");
      expect(goals.size()).toBe(0);
    });

    it("rejects a period that ends before it starts with InvalidGoalPeriod", async () => {
      const result = await createGoal()({
        userId: ALICE,
        title: "bad",
        targetCompletions: 3,
        startDate: THIS_YEAR.targetDate,
        targetDate: THIS_YEAR.startDate,
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("InvalidGoalPeriod");
      expect(goals.size()).toBe(0);
    });

    it("keeps its period", async () => {
      const id = await seedGoal(3, THIS_YEAR);
      expect((await stored(id)).toState()).toMatchObject(THIS_YEAR);
    });

    it("does not count solves from before it started: 30 earlier solves give 0/10", async () => {
      for (let day = 1; day <= 30; day++) {
        const finished = new Date(Date.UTC(2026, 3, day, 20));
        await recordCompletion(finished, finished);
      }
      await recordYearOnly(2025);

      const id = await seedGoal(10);
      expect((await stored(id)).currentCompletions).toBe(0);

      // The next solve brings it to 1/10, not 31/10, and announces nothing yet.
      await recordCompletion();
      events.published.length = 0;
      await recompute()({ userId: ALICE });
      expect((await stored(id)).currentCompletions).toBe(1);
      expect(events.names()).toEqual(["GoalProgressed"]);
    });

    it("starts a this-year goal at this year's solves, silently", async () => {
      await recordCompletion(
        new Date("2026-02-01T10:00:00Z"),
        new Date("2026-02-01T12:00:00Z"),
      );
      await recordCompletion(
        new Date("2026-03-01T10:00:00Z"),
        new Date("2026-03-01T12:00:00Z"),
      );
      await recordYearOnly(2026);
      await recordCompletion(
        new Date("2025-12-31T10:00:00Z"),
        new Date("2025-12-31T12:00:00Z"),
      );
      await recordYearOnly(2025);
      const undated = await record()({
        userId: ALICE,
        puzzleDefinitionId: PUZZLE,
        datePrecision: "unknown",
      });
      expect(undated.isOk).toBe(true);
      events.published.length = 0;

      const id = await seedGoal(3, THIS_YEAR);
      const goal = await stored(id);
      expect(goal.currentCompletions).toBe(3);
      expect(goal.isAchieved).toBe(true);
      // Already met at creation: no GoalProgressed, no GoalAchieved.
      expect(events.names()).toEqual(["GoalCreated"]);
    });

    it("counts only the creator's solves", async () => {
      const r = await record()({
        userId: BOB,
        puzzleDefinitionId: PUZZLE,
        startDate: START,
        endDate: END,
      });
      expect(r.isOk).toBe(true);
      const id = await seedGoal(3);
      expect((await stored(id)).currentCompletions).toBe(0);
    });
  });

  describe("recomputeGoalProgress (derived from completions)", () => {
    it("derives current progress from the solves in the goal's period and publishes GoalProgressed", async () => {
      const goalId = await seedGoal(2);
      await recordCompletion();
      events.published.length = 0;

      const result = await recompute()({ userId: ALICE });
      expect(result.isOk).toBe(true);
      expect(events.names()).toEqual(["GoalProgressed"]);

      const goal = await stored(goalId);
      expect(goal.currentCompletions).toBe(1);
      expect(goal.isAchieved).toBe(false);
    });

    it("fires GoalAchieved once when the count crosses the target", async () => {
      await seedGoal(2);
      await recordCompletion();
      await recordCompletion();
      events.published.length = 0;

      await recompute()({ userId: ALICE });
      expect(events.names()).toEqual(["GoalProgressed", "GoalAchieved"]);
    });

    it("does not re-fire GoalAchieved on a later recompute past the target", async () => {
      await seedGoal(2);
      await recordCompletion();
      await recordCompletion();
      await recompute()({ userId: ALICE }); // achieved here
      await recordCompletion(); // now 3
      events.published.length = 0;
      await recompute()({ userId: ALICE });
      expect(events.names()).toEqual(["GoalProgressed"]);
      expect(events.countOf("GoalAchieved")).toBe(0);
    });

    it("is a no-op (no events, no publish) when the count is unchanged", async () => {
      await seedGoal(2);
      await recordCompletion();
      await recompute()({ userId: ALICE });
      events.published.length = 0;
      events.batches.length = 0;
      await recompute()({ userId: ALICE }); // still 1
      expect(events.published).toHaveLength(0);
      // publish is not even called when a goal records no events.
      expect(events.batches).toHaveLength(0);
    });

    it("gives each goal the count of its own period", async () => {
      const thisYear = await seedGoal(5, THIS_YEAR);
      const fromToday = await seedGoal(5);
      await recordCompletion(
        new Date("2026-02-01T10:00:00Z"),
        new Date("2026-02-01T12:00:00Z"),
      );
      await recordCompletion();

      await recompute()({ userId: ALICE });
      expect((await stored(thisYear)).currentCompletions).toBe(2);
      expect((await stored(fromToday)).currentCompletions).toBe(1);
    });

    it("skips inactive goals (no progress derived for them)", async () => {
      const inactiveId = toGoalId("inactive-1");
      await goals.save(
        Goal.rehydrate({
          id: inactiveId,
          userId: ALICE,
          title: "retired",
          targetCompletions: 2,
          currentCompletions: 0,
          isActive: false,
          createdAt: START,
          updatedAt: START,
        }),
      );
      await recordCompletion();
      events.published.length = 0;

      await recompute()({ userId: ALICE });

      expect((await stored(inactiveId)).currentCompletions).toBe(0); // untouched
      expect(events.published).toHaveLength(0);
    });

    it("ignores undated solves and year-only solves from other years (decision 4)", async () => {
      const goalId = await seedGoal(5);
      await recordCompletion();
      await recordYearOnly(2026);
      await recordYearOnly(2023);
      await record()({
        userId: ALICE,
        puzzleDefinitionId: PUZZLE,
        datePrecision: "unknown",
      });

      await recompute()({ userId: ALICE });
      expect((await stored(goalId)).currentCompletions).toBe(2);
    });
  });

  describe("updateGoal", () => {
    const update = () => makeUpdateGoal({ goals, completions, clock });

    it("replaces the definition and recounts for the new period without announcing anything", async () => {
      await recordCompletion(
        new Date("2026-02-01T10:00:00Z"),
        new Date("2026-02-01T12:00:00Z"),
      );
      await recordCompletion(
        new Date("2026-03-01T10:00:00Z"),
        new Date("2026-03-01T12:00:00Z"),
      );
      const id = await seedGoal(5);
      expect((await stored(id)).currentCompletions).toBe(0);
      events.published.length = 0;
      clock.set(LATER);

      const result = await update()({
        actingMemberId: ALICE,
        goalId: id,
        title: "Two this year",
        targetCompletions: 2,
        ...THIS_YEAR,
      });
      expect(result.isOk).toBe(true);
      const goal = await stored(id);
      expect(goal.toState()).toMatchObject({
        title: "Two this year",
        targetCompletions: 2,
        currentCompletions: 2,
        updatedAt: LATER,
        ...THIS_YEAR,
      });
      expect(goal.isAchieved).toBe(true);
      expect(events.published).toHaveLength(0);
    });

    it("recounts an archived goal without restoring it", async () => {
      await recordCompletion(
        new Date("2026-02-01T10:00:00Z"),
        new Date("2026-02-01T12:00:00Z"),
      );
      const id = await seedGoal(5);
      await makeSetGoalArchived({ goals, completions, clock })({
        actingMemberId: ALICE,
        goalId: id,
        archived: true,
      });

      await update()({
        actingMemberId: ALICE,
        goalId: id,
        title: "Five",
        targetCompletions: 5,
        ...THIS_YEAR,
      });
      const goal = await stored(id);
      expect(goal.isActive).toBe(false);
      expect(goal.currentCompletions).toBe(1);
    });

    it("refuses another member's goal with NotGoalOwner and keeps it", async () => {
      const id = await seedGoal(5);
      const before = (await stored(id)).toState();
      const result = await update()({
        actingMemberId: BOB,
        goalId: id,
        title: "Mine now",
        targetCompletions: 1,
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("NotGoalOwner");
      expect((await stored(id)).toState()).toEqual(before);
    });

    it("reports GoalNotFound for an unknown goal", async () => {
      const result = await update()({
        actingMemberId: ALICE,
        goalId: toGoalId("missing"),
        title: "x",
        targetCompletions: 1,
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("GoalNotFound");
    });

    it("rejects an invalid target with InvalidGoalTarget and keeps the goal", async () => {
      const id = await seedGoal(5);
      const before = (await stored(id)).toState();
      const result = await update()({
        actingMemberId: ALICE,
        goalId: id,
        title: "x",
        targetCompletions: 2.5,
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("InvalidGoalTarget");
      expect((await stored(id)).toState()).toEqual(before);
    });
  });

  describe("setGoalArchived", () => {
    const setArchived = () =>
      makeSetGoalArchived({ goals, completions, clock });

    it("archives the goal, which then stops following new solves", async () => {
      const id = await seedGoal(5);
      clock.set(LATER);
      const result = await setArchived()({
        actingMemberId: ALICE,
        goalId: id,
        archived: true,
      });
      expect(result.isOk).toBe(true);
      const goal = await stored(id);
      expect(goal.isActive).toBe(false);
      expect(goal.toState().updatedAt).toBe(LATER);

      await recordCompletion();
      await recompute()({ userId: ALICE });
      expect((await stored(id)).currentCompletions).toBe(0);
    });

    it("restores the goal and silently counts the solves it missed", async () => {
      const id = await seedGoal(1);
      await setArchived()({
        actingMemberId: ALICE,
        goalId: id,
        archived: true,
      });
      await recordCompletion();
      await recompute()({ userId: ALICE });
      events.published.length = 0;

      const result = await setArchived()({
        actingMemberId: ALICE,
        goalId: id,
        archived: false,
      });
      expect(result.isOk).toBe(true);
      const goal = await stored(id);
      expect(goal.isActive).toBe(true);
      expect(goal.currentCompletions).toBe(1);
      expect(events.published).toHaveLength(0);
    });

    it("refuses another member's goal with NotGoalOwner", async () => {
      const id = await seedGoal(5);
      const result = await setArchived()({
        actingMemberId: BOB,
        goalId: id,
        archived: true,
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("NotGoalOwner");
      expect((await stored(id)).isActive).toBe(true);
    });

    it("reports GoalNotFound for an unknown goal", async () => {
      const result = await setArchived()({
        actingMemberId: ALICE,
        goalId: toGoalId("missing"),
        archived: true,
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("GoalNotFound");
    });
  });

  describe("deleteGoal", () => {
    const remove = () => makeDeleteGoal({ goals });

    it("deletes the owner's goal", async () => {
      const id = await seedGoal(5);
      const result = await remove()({ actingMemberId: ALICE, goalId: id });
      expect(result.isOk).toBe(true);
      expect(await goals.findById(id)).toBeNull();
    });

    it("refuses another member's goal with NotGoalOwner and keeps it", async () => {
      const id = await seedGoal(5);
      const result = await remove()({ actingMemberId: BOB, goalId: id });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("NotGoalOwner");
      expect(goals.size()).toBe(1);
    });

    it("reports GoalNotFound for an unknown goal", async () => {
      const result = await remove()({
        actingMemberId: ALICE,
        goalId: toGoalId("missing"),
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("GoalNotFound");
    });
  });
});

