import { beforeEach, describe, expect, it } from "vitest";
import { toCircleId, toCopyId, toMemberId } from "../../../shared-kernel";
import { CircleId } from "../../domain";
import {
  FixedClock,
  InMemoryCircleRepository,
  RecordingEventPublisher,
  SequentialCircleIdGenerator,
  SequentialMembershipIdGenerator,
} from "../testing";
import { makeAddMember } from "./add-member";
import { makeChangePermission } from "./change-permission";
import { makeCreateCircle } from "./create-circle";
import { makeDeleteCircle } from "./delete-circle";
import { makeLeaveCircle } from "./leave-circle";
import { makeRemoveMember } from "./remove-member";
import { makeShareCopyToCircle } from "./share-copy-to-circle";

const owner = toMemberId("owner");
const alice = toMemberId("alice");
const bob = toMemberId("bob");
const missingCircle = toCircleId("nope");
const copyId = toCopyId("copy-1");
const NOW = new Date("2026-06-08T10:00:00Z");

describe("Sharing circle use cases", () => {
  let circles: InMemoryCircleRepository;
  let membershipIds: SequentialMembershipIdGenerator;
  let events: RecordingEventPublisher;
  let clock: FixedClock;

  let createCircle: ReturnType<typeof makeCreateCircle>;
  let addMember: ReturnType<typeof makeAddMember>;
  let removeMember: ReturnType<typeof makeRemoveMember>;
  let leaveCircle: ReturnType<typeof makeLeaveCircle>;
  let deleteCircle: ReturnType<typeof makeDeleteCircle>;
  let changePermission: ReturnType<typeof makeChangePermission>;
  let shareCopy: ReturnType<typeof makeShareCopyToCircle>;

  beforeEach(() => {
    circles = new InMemoryCircleRepository();
    membershipIds = new SequentialMembershipIdGenerator();
    events = new RecordingEventPublisher();
    clock = new FixedClock(NOW);

    createCircle = makeCreateCircle({
      circles,
      circleIds: new SequentialCircleIdGenerator(),
      membershipIds,
      events,
      clock,
    });
    addMember = makeAddMember({ circles, membershipIds, events, clock });
    removeMember = makeRemoveMember({ circles, events, clock });
    leaveCircle = makeLeaveCircle({ circles, events, clock });
    deleteCircle = makeDeleteCircle({ circles, events, clock });
    changePermission = makeChangePermission({ circles, events });
    shareCopy = makeShareCopyToCircle({ circles, events, clock });
  });

  // Helper: create a circle and return its id.
  const openCircle = async (): Promise<CircleId> => {
    const result = await createCircle({ ownerId: owner, name: "Family" });
    if (!result.isOk) throw new Error("setup: create failed");
    return result.value;
  };

  describe("makeCreateCircle", () => {
    it("creates a circle owned by the actor and publishes CircleCreated", async () => {
      const result = await createCircle({ ownerId: owner, name: "Family" });

      expect(result.isOk).toBe(true);
      expect(circles.size()).toBe(1);
      if (result.isOk) {
        const circle = await circles.findById(result.value);
        expect(circle?.ownerId).toBe(owner);
        expect(circle?.isMember(owner)).toBe(true);
      }
      expect(events.names()).toEqual(["CircleCreated"]);
    });

    it("refuses an invalid name with InvalidCircleName, saving and publishing nothing", async () => {
      const result = await createCircle({ ownerId: owner, name: "   " });

      expect(result.isErr && result.error.code).toBe("InvalidCircleName");
      expect(circles.size()).toBe(0);
      expect(events.names()).toEqual([]);
    });
  });

  describe("makeAddMember", () => {
    it("adds a member by an admin and publishes MemberJoinedCircle", async () => {
      const circleId = await openCircle();
      events.published.length = 0;

      const result = await addMember({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "ViewOnly",
      });

      expect(result.isOk).toBe(true);
      expect((await circles.findById(circleId))?.isMember(alice)).toBe(true);
      expect(events.names()).toEqual(["MemberJoinedCircle"]);
    });

    it("returns CircleNotFound for an unknown circle", async () => {
      const result = await addMember({
        circleId: missingCircle,
        actorId: owner,
        memberId: alice,
        permission: "ViewOnly",
      });

      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("CircleNotFound");
    });

    it("rejects a non-admin actor and writes nothing", async () => {
      const circleId = await openCircle();
      await addMember({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "ViewOnly",
      });
      events.published.length = 0;

      const result = await addMember({
        circleId,
        actorId: alice, // only ViewOnly
        memberId: bob,
        permission: "ViewOnly",
      });

      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("NotCircleAdmin");
      expect((await circles.findById(circleId))?.isMember(bob)).toBe(false);
      expect(events.published).toHaveLength(0);
    });

    it("rejects adding an existing member", async () => {
      const circleId = await openCircle();
      await addMember({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "ViewOnly",
      });

      const result = await addMember({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "Admin",
      });

      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("AlreadyMember");
    });
  });

  describe("makeRemoveMember", () => {
    it("removes a member by an admin and publishes MemberLeftCircle", async () => {
      const circleId = await openCircle();
      await addMember({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "ViewOnly",
      });
      events.published.length = 0;

      const result = await removeMember({
        circleId,
        actorId: owner,
        memberId: alice,
      });

      expect(result.isOk).toBe(true);
      expect((await circles.findById(circleId))?.isMember(alice)).toBe(false);
      expect(events.names()).toEqual(["MemberLeftCircle"]);
      expect(events.published[0]).toMatchObject({
        memberId: alice,
        reason: "removed",
        occurredAt: NOW,
      });
    });

    it("refuses to remove the owner", async () => {
      const circleId = await openCircle();

      const result = await removeMember({
        circleId,
        actorId: owner,
        memberId: owner,
      });

      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("CannotRemoveOwner");
    });

    it("returns CircleNotFound for an unknown circle", async () => {
      const result = await removeMember({
        circleId: missingCircle,
        actorId: owner,
        memberId: alice,
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("CircleNotFound");
    });
  });

  describe("makeLeaveCircle", () => {
    it("takes the member out and publishes MemberLeftCircle", async () => {
      const circleId = await openCircle();
      await addMember({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "ViewOnly",
      });
      events.published.length = 0;

      const result = await leaveCircle({ circleId, memberId: alice });

      expect(result.isOk).toBe(true);
      expect((await circles.findById(circleId))?.isMember(alice)).toBe(false);
      expect(events.names()).toEqual(["MemberLeftCircle"]);
      expect(events.published[0]).toMatchObject({
        circleId,
        memberId: alice,
        reason: "left",
        occurredAt: NOW,
      });
    });

    it("refuses the owner and writes nothing", async () => {
      const circleId = await openCircle();
      events.published.length = 0;

      const result = await leaveCircle({ circleId, memberId: owner });

      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("OwnerCannotLeave");
      expect((await circles.findById(circleId))?.isMember(owner)).toBe(true);
      expect(events.published).toHaveLength(0);
    });

    it("rejects a non-member", async () => {
      const circleId = await openCircle();

      const result = await leaveCircle({ circleId, memberId: bob });

      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("NotAMember");
    });

    it("returns CircleNotFound for an unknown circle", async () => {
      const result = await leaveCircle({
        circleId: missingCircle,
        memberId: alice,
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("CircleNotFound");
    });
  });

  describe("makeDeleteCircle", () => {
    it("deletes the circle and publishes CircleDeleted naming the other members", async () => {
      const circleId = await openCircle();
      await addMember({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "ViewOnly",
      });
      events.published.length = 0;

      const result = await deleteCircle({
        circleId,
        actorId: owner,
        confirmName: "Family",
      });

      expect(result.isOk).toBe(true);
      expect(await circles.findById(circleId)).toBeNull();
      expect(circles.size()).toBe(0);
      expect(events.names()).toEqual(["CircleDeleted"]);
      expect(events.published[0]).toMatchObject({
        circleId,
        ownerId: owner,
        memberIds: [alice],
        circleName: "Family",
        occurredAt: NOW,
      });
    });

    it.each([
      ["a member who is not the owner", alice, "Family", "NotCircleOwner"],
      ["a non-member", bob, "Family", "NotAMember"],
      [
        "the owner with the wrong name",
        owner,
        "family",
        "ConfirmationMismatch",
      ],
    ] as const)(
      "refuses %s and keeps the circle",
      async (_label, actorId, confirmName, code) => {
        const circleId = await openCircle();
        await addMember({
          circleId,
          actorId: owner,
          memberId: alice,
          permission: "Admin",
        });
        events.published.length = 0;

        const result = await deleteCircle({ circleId, actorId, confirmName });

        expect(result.isErr).toBe(true);
        if (result.isErr) expect(result.error.code).toBe(code);
        expect(await circles.findById(circleId)).not.toBeNull();
        expect(events.published).toHaveLength(0);
      },
    );

    it("returns CircleNotFound for an unknown circle", async () => {
      const result = await deleteCircle({
        circleId: missingCircle,
        actorId: owner,
        confirmName: "Family",
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("CircleNotFound");
    });
  });

  describe("makeChangePermission", () => {
    it("changes a member's permission by an admin", async () => {
      const circleId = await openCircle();
      await addMember({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "ViewOnly",
      });

      const result = await changePermission({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "Exchange",
      });

      expect(result.isOk).toBe(true);
      const circle = await circles.findById(circleId);
      expect(
        circle?.members.find((m) => m.memberId === alice)?.permission,
      ).toBe("Exchange");
    });

    it("rejects a no-op permission change", async () => {
      const circleId = await openCircle();
      await addMember({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "ViewOnly",
      });

      const result = await changePermission({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "ViewOnly",
      });

      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("DuplicatePermission");
    });

    it("returns CircleNotFound for an unknown circle", async () => {
      const result = await changePermission({
        circleId: missingCircle,
        actorId: owner,
        memberId: alice,
        permission: "Admin",
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("CircleNotFound");
    });
  });

  describe("makeShareCopyToCircle", () => {
    it("shares a copy by an admin and publishes CopySharedToCircle", async () => {
      const circleId = await openCircle();
      events.published.length = 0;

      const result = await shareCopy({ circleId, actorId: owner, copyId });

      expect(result.isOk).toBe(true);
      expect(events.names()).toEqual(["CopySharedToCircle"]);
    });

    it("shares a copy by an Exchange member", async () => {
      const circleId = await openCircle();
      await addMember({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "Exchange",
      });
      events.published.length = 0;

      const result = await shareCopy({ circleId, actorId: alice, copyId });

      expect(result.isOk).toBe(true);
      expect(events.names()).toEqual(["CopySharedToCircle"]);
    });

    it("rejects a ViewOnly actor", async () => {
      const circleId = await openCircle();
      await addMember({
        circleId,
        actorId: owner,
        memberId: alice,
        permission: "ViewOnly",
      });
      events.published.length = 0;

      const result = await shareCopy({ circleId, actorId: alice, copyId });

      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("CannotShareCopy");
      expect(events.published).toHaveLength(0);
    });

    it("returns CircleNotFound for an unknown circle", async () => {
      const result = await shareCopy({
        circleId: missingCircle,
        actorId: owner,
        copyId,
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("CircleNotFound");
    });
  });

  describe("listForMember", () => {
    it("returns every circle a member belongs to (the VisibilityPolicy wiring seam)", async () => {
      const first = await openCircle();
      const second = await openCircle();
      await addMember({
        circleId: first,
        actorId: owner,
        memberId: alice,
        permission: "ViewOnly",
      });

      const ownerCircles = await circles.listForMember(owner);
      const aliceCircles = await circles.listForMember(alice);

      expect(ownerCircles.map((c) => c.id).sort()).toEqual(
        [first, second].sort(),
      );
      expect(aliceCircles.map((c) => c.id)).toEqual([first]);
    });
  });
});

src/library/application/use-cases/loan-u.source:
import { beforeEach, describe, expect, it } from "vitest";
import {
  err,
  toCopyId,
  toLoanId,
  toOwnerId,
  toPuzzleDefinitionId,
} from "../../../shared-kernel";
import {
  CatalogSnapshot,
  Copy,
  CopyId,
  LibraryError,
  Loan,
  LoanId,
} from "../../domain";
import {
  FakeCopyManagerPolicy,
  FixedClock,
  InMemoryCopyRepository,
  InMemoryLoanRepository,
  RecordingEventPublisher,
  SequentialLoanIdGenerator,
} from "../testing";
import { makeOpenLoan } from "./open-loan";
import { makeRecallLoan } from "./recall-loan";
import { makeReturnLoan } from "./return-loan";

const owner = toOwnerId("alice");
const borrower = toOwnerId("bob");
const carol = toOwnerId("carol");
const definitionId = toPuzzleDefinitionId("def1");
const NOW = new Date("2026-06-08T10:00:00Z");
const LATER = new Date("2026-06-20T10:00:00Z");

const snapshot = (): CatalogSnapshot =>
  CatalogSnapshot.create({
    puzzleDefinitionId: definitionId,
    title: "Owl",
    pieceCount: 500,
  });

describe("loan use cases", () => {
  let copies: InMemoryCopyRepository;
  let loans: InMemoryLoanRepository;
  let events: RecordingEventPublisher;
  let ids: SequentialLoanIdGenerator;
  let copyId: CopyId;

  beforeEach(async () => {
    copies = new InMemoryCopyRepository();
    loans = new InMemoryLoanRepository();
    events = new RecordingEventPublisher();
    ids = new SequentialLoanIdGenerator();
    const acquired = Copy.acquire({
      id: toCopyId("copy-seed"),
      ownerId: owner,
      snapshot: snapshot(),
      condition: "good",
      now: NOW,
    });
    if (!acquired.isOk) throw new Error("setup");
    copyId = acquired.value.id;
    await copies.save(acquired.value);
  });

  const open = () =>
    makeOpenLoan({
      copies,
      loans,
      ids,
      events,
      clock: new FixedClock(NOW),
    });

  describe("makeOpenLoan", () => {
    it("opens a loan, moves possession to the borrower, keeps ownership", async () => {
      const result = await open()({ copyId, borrowerId: borrower });
      expect(result.isOk).toBe(true);
      expect(events.names()).toEqual(["LoanOpened", "CopyLentOut"]);
      const copy = await copies.findById(copyId);
      expect(copy?.heldBy).toBe(borrower);
      expect(copy?.ownerId).toBe(owner);
    });

    it("rejects an unknown copy", async () => {
      const result = await open()({
        copyId: toCopyId("ghost"),
        borrowerId: borrower,
      });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("CopyNotFound");
    });

    it("rejects lending a copy to its own owner (CannotLendToSelf)", async () => {
      const result = await open()({ copyId, borrowerId: owner });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("CannotLendToSelf");
      expect(events.published).toHaveLength(0);
    });

    // The settled lend names its lender; the loan opens only while they still own the copy.
    it("opens the loan when the lender still owns the copy", async () => {
      const result = await open()({
        copyId,
        borrowerId: borrower,
        lender: owner,
      });
      if (!result.isOk) throw new Error("expected ok");
      const loan = await loans.findById(result.value);
      expect(loan?.toState().lenderId).toBe(owner);
    });

    it("refuses with OwnershipChanged once someone else owns the copy, opening nothing", async () => {
      const result = await open()({
        copyId,
        borrowerId: borrower,
        lender: toOwnerId("carol"),
      });
      expect(result.isErr && result.error.code).toBe("OwnershipChanged");
      expect(events.published).toHaveLength(0);
      expect((await copies.findById(copyId))?.heldBy).toBe(owner);
      expect(loans.size()).toBe(0);
    });

    // One open loan per copy: a copy already out is not lent again until it comes back.
    it("refuses with AlreadyLentOut while another loan on the copy is open, opening nothing", async () => {
      await open()({ copyId, borrowerId: borrower });
      const published = events.published.length;
      const result = await open()({ copyId, borrowerId: carol, lender: owner });
      expect(result.isErr && result.error.code).toBe("AlreadyLentOut");
      expect(loans.size()).toBe(1);
      expect((await copies.findById(copyId))?.heldBy).toBe(borrower);
      expect(events.published).toHaveLength(published);
    });

    it("refuses with AlreadyLentOut while someone else holds the copy, even without an open loan", async () => {
      const copy = await copies.findById(copyId);
      if (!copy) throw new Error("setup");
      copy.lendOut(borrower, NOW);
      await copies.save(copy);
      const result = await open()({ copyId, borrowerId: carol });
      expect(result.isErr && result.error.code).toBe("AlreadyLentOut");
      expect(loans.size()).toBe(0);
      expect((await copies.findById(copyId))?.heldBy).toBe(borrower);
      expect(events.published).toHaveLength(0);
    });

    // A loan left open by rows from before these rules: its borrower no longer has the copy.
    const leftOpenBy = async (lenderId: typeof owner) => {
      const stale = Loan.open({
        id: toLoanId("loan-left-open"),
        copyId,
        lenderId,
        borrowerId: carol,
        now: NOW,
      });
      if (!stale.isOk) throw new Error("setup");
      await loans.save(stale.value);
    };

    it("refuses with AlreadyLentOut while the owner's own loan on it is open, even with the copy at home", async () => {
      await leftOpenBy(owner);
      const result = await open()({
        copyId,
        borrowerId: borrower,
        lender: owner,
      });
      expect(result.isErr && result.error.code).toBe("AlreadyLentOut");
      expect(loans.size()).toBe(1);
      expect((await copies.findById(copyId))?.heldBy).toBe(owner);
      expect(events.published).toHaveLength(0);
    });

    // A loan a former owner left open (a transfer before transfers ended loans) is stale: it never
    // stops the current owner lending their copy.
    it("lends the copy although a former owner's loan on it is still open", async () => {
      await leftOpenBy(toOwnerId("dave"));
      const result = await open()({
        copyId,
        borrowerId: borrower,
        lender: owner,
      });
      expect(result.isOk).toBe(true);
      expect((await copies.findById(copyId))?.heldBy).toBe(borrower);
      expect(await loans.findOpenByCopy(copyId)).toHaveLength(2);
    });

    it("lends the copy again once the earlier loan is closed", async () => {
      const first = await open()({ copyId, borrowerId: borrower });
      if (!first.isOk) throw new Error("setup");
      await makeReturnLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
      })({ loanId: first.value, actingMemberId: borrower });
      const second = await open()({ copyId, borrowerId: carol });
      expect(second.isOk).toBe(true);
      expect((await copies.findById(copyId))?.heldBy).toBe(carol);
      expect(await loans.findOpenByCopy(copyId)).toHaveLength(1);
    });
  });

  describe("closing a loan (return / recall)", () => {
    let loanId: LoanId;

    beforeEach(async () => {
      const opened = await open()({ copyId, borrowerId: borrower });
      if (opened.isOk) loanId = opened.value;
    });

    it("the borrower returns the loan -> possession back to the owner", async () => {
      const result = await makeReturnLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
      })({ loanId, actingMemberId: borrower });
      expect(result.isOk).toBe(true);
      expect((await copies.findById(copyId))?.heldBy).toBe(owner);
      expect(events.names()).toEqual(
        expect.arrayContaining(["LoanClosed", "CopyReturnedToOwner"]),
      );
    });

    it("still closes the loan when the copy no longer exists", async () => {
      await copies.remove(copyId);
      const result = await makeReturnLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
      })({ loanId, actingMemberId: borrower });
      expect(result.isOk).toBe(true);
      // Exactly the loan close is published — no copy events when the copy is gone.
      expect(events.names()).toEqual([
        "LoanOpened",
        "CopyLentOut",
        "LoanClosed",
      ]);
    });

    it("recall still closes the loan when the copy no longer exists", async () => {
      await copies.remove(copyId);
      const result = await makeRecallLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
      })({ loanId, actingMemberId: owner });
      expect(result.isOk).toBe(true);
      expect(events.names()).toEqual([
        "LoanOpened",
        "CopyLentOut",
        "LoanClosed",
      ]);
    });

    it("a non-borrower cannot return", async () => {
      const result = await makeReturnLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
      })({ loanId, actingMemberId: owner });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("NotBorrower");
    });

    it("the owner recalls the loan -> possession back to the owner", async () => {
      const result = await makeRecallLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
      })({ loanId, actingMemberId: owner });
      expect(result.isOk).toBe(true);
      expect((await copies.findById(copyId))?.heldBy).toBe(owner);
      expect(events.names()).toEqual(
        expect.arrayContaining(["LoanClosed", "CopyReturnedToOwner"]),
      );
    });

    it("a policy-approved household manager may recall on the lender's behalf", async () => {
      const managers = new FakeCopyManagerPolicy();
      const mate = toOwnerId("mate");
      managers.allow(copyId, mate);
      const result = await makeRecallLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
        managers,
      })({ loanId, actingMemberId: mate });
      expect(result.isOk).toBe(true);
      expect((await copies.findById(copyId))?.heldBy).toBe(owner);
      expect((await loans.findById(loanId))?.toState().lenderId).toBe(owner);
    });

    it("the borrower cannot recall even with a policy wired", async () => {
      const managers = new FakeCopyManagerPolicy();
      managers.allow(copyId, toOwnerId("mate"));
      const result = await makeRecallLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
        managers,
      })({ loanId, actingMemberId: borrower });
      expect(result.isErr && result.error.code).toBe("NotLender");
    });

    it("a non-owner cannot recall", async () => {
      const result = await makeRecallLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
      })({ loanId, actingMemberId: borrower });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("NotLender");
    });

    it("rejects closing an unknown loan", async () => {
      const result = await makeReturnLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
      })({ loanId: toLoanId("ghost"), actingMemberId: borrower });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("LoanNotFound");
    });

    it("rejects recalling an unknown loan", async () => {
      const result = await makeRecallLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
      })({ loanId: toLoanId("ghost"), actingMemberId: owner });
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("LoanNotFound");
    });

    // A loan whose borrower no longer holds the copy (an older loan left open beside a newer one)
    // closes without taking the copy away from whoever holds it now.
    const nowHeldByCarol = async () => {
      const copy = await copies.findById(copyId);
      if (!copy) throw new Error("setup");
      copy.returnToOwner(NOW);
      copy.lendOut(carol, NOW);
      copy.pullEvents();
      await copies.save(copy);
      return events.published.length;
    };

    it("returning a loan whose borrower no longer holds the copy closes it and leaves possession alone", async () => {
      const published = await nowHeldByCarol();
      const result = await makeReturnLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
      })({ loanId, actingMemberId: borrower });
      expect(result.isOk).toBe(true);
      expect((await loans.findById(loanId))?.status).toBe("returned");
      expect((await copies.findById(copyId))?.heldBy).toBe(carol);
      expect(events.names().slice(published)).toEqual(["LoanClosed"]);
    });

    it("recalling a loan whose borrower no longer holds the copy closes it and leaves possession alone", async () => {
      const published = await nowHeldByCarol();
      const result = await makeRecallLoan({
        loans,
        copies,
        events,
        clock: new FixedClock(LATER),
      })({ loanId, actingMemberId: owner });
      expect(result.isOk).toBe(true);
      expect((await loans.findById(loanId))?.status).toBe("recalled");
      expect((await copies.findById(copyId))?.heldBy).toBe(carol);
      expect(events.names().slice(published)).toEqual(["LoanClosed"]);
    });

    // returnToOwner returns a Result; both close use cases must propagate a failure rather than
    // silently swallow it and still report ok. Wrap the repo so the loaded copy fails to return.
    const failingReturnCopies = (): InMemoryCopyRepository => {
      const wrapped = copies;
      return {
        ...wrapped,
        findById: async (id: CopyId) => {
          const copy = await wrapped.findById(id);
          if (copy) {
            copy.returnToOwner = () => err(LibraryError.notOwner("return"));
          }
          return copy;
        },
      } as InMemoryCopyRepository;
    };

    it("propagates a returnToOwner failure on return (does not report ok)", async () => {
      const result = await makeReturnLoan({
        loans,
        copies: failingReturnCopies(),
        events,
        clock: new FixedClock(LATER),
      })({ loanId, actingMemberId: borrower });
      expect(result.isErr).toBe(true);
    });

    it("propagates a returnToOwner failure on recall (does not report ok)", async () => {
      const result = await makeRecallLoan({
        loans,
        copies: failingReturnCopies(),
        events,
        clock: new FixedClock(LATER),
      })({ loanId, actingMemberId: owner });
      expect(result.isErr).toBe(true);
    });
  });
});

