import { describe, expect, it } from "vitest";
import { toId, toMemberId } from "../../shared-kernel";
import { Household } from "./household";
import { HouseholdId } from "./ids";

const id = toId<"HouseholdId">("household-1") as HouseholdId;
const ann = toMemberId("ann");
const bob = toMemberId("bob");
const cat = toMemberId("cat");
const t0 = new Date("2026-10-01T00:00:00Z");
const t1 = new Date("2026-10-02T00:00:00Z");
const t2 = new Date("2026-10-03T00:00:00Z");

const founded = (): Household => {
  const h = Household.found({ id, founderId: ann, now: t0 });
  h.pullEvents();
  return h;
};

describe("Household.found", () => {
  it("makes the founder the sole admin and records HouseholdFounded", () => {
    const h = Household.found({ id, founderId: ann, now: t0 });
    expect(h.members).toEqual([{ memberId: ann, role: "admin", joinedAt: t0 }]);
    expect(h.isAdmin(ann)).toBe(true);
    expect(h.pullEvents().map((e) => e.name)).toEqual(["HouseholdFounded"]);
  });
});

describe("Household.admit", () => {
  it("adds a plain member and records HouseholdMemberJoined", () => {
    const h = founded();
    expect(h.admit(bob, t1).isOk).toBe(true);
    expect(h.isMember(bob)).toBe(true);
    expect(h.isAdmin(bob)).toBe(false);
    expect(h.members).toContainEqual({
      memberId: bob,
      role: "member",
      joinedAt: t1,
    });
    expect(h.pullEvents().map((e) => e.name)).toEqual([
      "HouseholdMemberJoined",
    ]);
  });

  it("rejects admitting an existing member", () => {
    const h = founded();
    const result = h.admit(ann, t1);
    expect(result.isErr && result.error.code).toBe("AlreadyMember");
  });
});

describe("Household.leave", () => {
  it("rejects a non-member", () => {
    const result = founded().leave(bob, t1);
    expect(result.isErr && result.error.code).toBe("NotAMember");
  });

  it("removes a plain member without dissolving", () => {
    const h = founded();
    h.admit(bob, t1);
    h.pullEvents();
    const result = h.leave(bob, t2);
    expect(result.isOk && result.value).toEqual({ dissolved: false });
    expect(h.isMember(bob)).toBe(false);
    expect(h.pullEvents().map((e) => e.name)).toEqual(["HouseholdMemberLeft"]);
  });

  it("promotes the longest-standing remaining member when the admin leaves", () => {
    const h = founded();
    h.admit(cat, t2);
    h.admit(bob, t1);
    expect(h.leave(ann, t2).isOk).toBe(true);
    expect(h.isAdmin(bob)).toBe(true);
    expect(h.isAdmin(cat)).toBe(false);
  });

  it("keeps the admin and promotes no one when a plain member leaves", () => {
    // The admin is not the longest-standing member, so a needless promotion would be visible.
    const h = Household.rehydrate({
      id,
      members: [
        { memberId: bob, role: "member", joinedAt: t0 },
        { memberId: ann, role: "admin", joinedAt: t1 },
        { memberId: cat, role: "member", joinedAt: t2 },
      ],
      createdAt: t0,
    });
    expect(h.leave(cat, t2).isOk).toBe(true);
    expect(h.members).toEqual([
      { memberId: bob, role: "member", joinedAt: t0 },
      { memberId: ann, role: "admin", joinedAt: t1 },
    ]);
  });

  it("promotes the senior member even when they are not listed last", () => {
    const h = founded();
    h.admit(bob, t1);
    h.admit(cat, t2);
    expect(h.leave(ann, t2).isOk).toBe(true);
    expect(h.isAdmin(bob)).toBe(true);
    expect(h.isAdmin(cat)).toBe(false);
  });

  it("promotes the earlier-listed member when join times tie", () => {
    const h = founded();
    h.admit(bob, t1);
    h.admit(cat, t1);
    expect(h.leave(ann, t2).isOk).toBe(true);
    expect(h.isAdmin(bob)).toBe(true);
    expect(h.isAdmin(cat)).toBe(false);
  });

  it("dissolves when the last member leaves", () => {
    const h = founded();
    const result = h.leave(ann, t1);
    expect(result.isOk && result.value).toEqual({ dissolved: true });
    expect(h.members).toEqual([]);
    expect(h.pullEvents().map((e) => e.name)).toEqual([
      "HouseholdMemberLeft",
      "HouseholdDissolved",
    ]);
  });
});

describe("Household.remove", () => {
  it("lets the admin remove another member", () => {
    const h = founded();
    h.admit(bob, t1);
    h.pullEvents();
    expect(h.remove(ann, bob, t2).isOk).toBe(true);
    expect(h.isMember(bob)).toBe(false);
    expect(h.pullEvents().map((e) => e.name)).toEqual([
      "HouseholdMemberRemoved",
    ]);
  });

  it("rejects a non-admin remover", () => {
    const h = founded();
    h.admit(bob, t1);
    h.admit(cat, t1);
    const result = h.remove(bob, cat, t2);
    expect(result.isErr && result.error.code).toBe("NotHouseholdAdmin");
  });

  it("rejects the admin removing themselves (they leave instead)", () => {
    const result = founded().remove(ann, ann, t1);
    expect(result.isErr && result.error.code).toBe("CannotRemoveSelf");
  });

  it("rejects removing a non-member", () => {
    const result = founded().remove(ann, bob, t1);
    expect(result.isErr && result.error.code).toBe("NotAMember");
  });
});

describe("Household.setDefaultCopyPermission", () => {
  it("starts without a household default", () => {
    expect(founded().toState().defaultCopyPermission).toBeUndefined();
  });

  it("lets the admin set the default, reporting whether it changed, without events", () => {
    const h = founded();
    expect(h.setDefaultCopyPermission(ann, "view")).toEqual({
      isOk: true,
      isErr: false,
      value: { changed: true },
    });
    expect(h.toState().defaultCopyPermission).toBe("view");
    expect(h.setDefaultCopyPermission(ann, "view")).toEqual({
      isOk: true,
      isErr: false,
      value: { changed: false },
    });
    expect(h.setDefaultCopyPermission(ann, "manage")).toEqual({
      isOk: true,
      isErr: false,
      value: { changed: true },
    });
    expect(h.toState().defaultCopyPermission).toBe("manage");
    expect(h.pullEvents()).toEqual([]);
  });

  it("treats an unset default as manage when deciding whether it changed", () => {
    expect(founded().setDefaultCopyPermission(ann, "manage")).toEqual({
      isOk: true,
      isErr: false,
      value: { changed: false },
    });
  });

  it("rejects a non-admin member and an outsider", () => {
    const h = founded();
    h.admit(bob, t1);
    for (const actor of [bob, cat]) {
      const result = h.setDefaultCopyPermission(actor, "view");
      expect(result.isErr && result.error.code).toBe("NotHouseholdAdmin");
    }
    expect(h.toState().defaultCopyPermission).toBeUndefined();
  });

  it("keeps the default across member changes and rehydration", () => {
    const h = founded();
    h.setDefaultCopyPermission(ann, "view");
    h.admit(bob, t1);
    h.leave(ann, t2);
    expect(
      Household.rehydrate(h.toState()).toState().defaultCopyPermission,
    ).toBe("view");
  });
});

src/insights/collection-breakdown.spec.t.source:
import { describe, expect, it } from "vitest";
import {
  computeCollectionBreakdown,
  OTHER_BUCKET,
  UNKNOWN_BUCKET,
  type CopyBreakdownInput,
} from "./collection-breakdown";

const copy = (over: Partial<CopyBreakdownInput>): CopyBreakdownInput => ({
  ...over,
});

describe("computeCollectionBreakdown", () => {
  it("names its unknown and long-tail buckets with sentinels, never with English words", () => {
    // The web translates these two strings; they are part of the query's wire contract.
    expect(UNKNOWN_BUCKET).toBe("__unknown");
    expect(OTHER_BUCKET).toBe("__other");
  });

  it("returns empty distributions for no copies", () => {
    expect(computeCollectionBreakdown([])).toEqual({
      byPieceCount: [],
      byBrand: [],
      byDifficulty: [],
      byCondition: [],
    });
  });

  describe("piece-count bucketing", () => {
    it("places counts at the inclusive-lower / exclusive-upper bucket edges", () => {
      const { byPieceCount } = computeCollectionBreakdown([
        copy({ pieceCount: 99 }), // < 100
        copy({ pieceCount: 100 }), // 100-299 (lower edge)
        copy({ pieceCount: 299 }), // 100-299 (upper edge)
        copy({ pieceCount: 300 }), // 300-499 (lower edge)
        copy({ pieceCount: 500 }), // 500-999
        copy({ pieceCount: 999 }), // 500-999
        copy({ pieceCount: 1000 }), // 1000-1999
        copy({ pieceCount: 2000 }), // 2000+
      ]);
      expect(byPieceCount).toEqual([
        { label: "< 100", value: 1 },
        { label: "100-299", value: 2 },
        { label: "300-499", value: 1 },
        { label: "500-999", value: 2 },
        { label: "1000-1999", value: 1 },
        { label: "2000+", value: 1 },
      ]);
    });

    it("emits buckets in ascending range order and drops empty buckets", () => {
      const { byPieceCount } = computeCollectionBreakdown([
        copy({ pieceCount: 2500 }),
        copy({ pieceCount: 50 }),
      ]);
      expect(byPieceCount.map((e) => e.label)).toEqual(["< 100", "2000+"]);
    });

    it("buckets missing or non-finite piece counts as unknown, listed last", () => {
      const { byPieceCount } = computeCollectionBreakdown([
        copy({ pieceCount: 500 }),
        copy({ pieceCount: undefined }),
        copy({ pieceCount: Number.NaN }),
        // Infinity satisfies `>= 2000`, so only the finite guard keeps it out of the 2000+ bucket.
        copy({ pieceCount: Number.POSITIVE_INFINITY }),
      ]);
      expect(byPieceCount).toEqual([
        { label: "500-999", value: 1 },
        { label: UNKNOWN_BUCKET, value: 3 },
      ]);
    });
  });

  describe("facet distributions (difficulty / condition)", () => {
    it("counts values, sorting by value desc then label asc", () => {
      const { byDifficulty } = computeCollectionBreakdown([
        copy({ difficulty: "hard" }),
        copy({ difficulty: "easy" }),
        copy({ difficulty: "easy" }),
        copy({ difficulty: "medium" }),
      ]);
      expect(byDifficulty).toEqual([
        { label: "easy", value: 2 },
        { label: "hard", value: 1 },
        { label: "medium", value: 1 },
      ]);
    });

    it("maps missing or blank values to the unknown bucket, listed last even when largest", () => {
      const { byCondition } = computeCollectionBreakdown([
        copy({ condition: "good" }),
        copy({ condition: undefined }),
        copy({ condition: "   " }),
      ]);
      expect(byCondition).toEqual([
        { label: "good", value: 1 },
        { label: UNKNOWN_BUCKET, value: 2 },
      ]);
    });

    it("leaves the unknown bucket out when every copy has a value", () => {
      const { byDifficulty } = computeCollectionBreakdown([
        copy({ difficulty: "easy" }),
      ]);
      expect(byDifficulty).toEqual([{ label: "easy", value: 1 }]);
    });
  });

  describe("brand top-N with Other collapse", () => {
    const brandCopies = (
      counts: Record<string, number>,
    ): CopyBreakdownInput[] =>
      Object.entries(counts).flatMap(([brand, n]) =>
        Array.from({ length: n }, () => copy({ brand })),
      );

    it("keeps every brand when distinct brands <= topN (no Other)", () => {
      const { byBrand } = computeCollectionBreakdown(
        brandCopies({ A: 3, B: 1 }),
        2,
      );
      expect(byBrand).toEqual([
        { label: "A", value: 3 },
        { label: "B", value: 1 },
      ]);
      expect(byBrand.some((e) => e.label === OTHER_BUCKET)).toBe(false);
    });

    it("collapses the tail beyond topN into a single Other appended last", () => {
      const { byBrand } = computeCollectionBreakdown(
        brandCopies({ A: 5, B: 4, C: 3, D: 2, E: 1 }),
        2,
      );
      expect(byBrand).toEqual([
        { label: "A", value: 5 },
        { label: "B", value: 4 },
        // C + D + E folded into Other.
        { label: OTHER_BUCKET, value: 6 },
      ]);
      expect(byBrand[byBrand.length - 1]?.label).toBe(OTHER_BUCKET);
    });

    it("does not collapse when distinct brands exactly equal topN", () => {
      const { byBrand } = computeCollectionBreakdown(
        brandCopies({ A: 2, B: 2 }),
        2,
      );
      expect(byBrand.some((e) => e.label === OTHER_BUCKET)).toBe(false);
      expect(byBrand).toHaveLength(2);
    });

    it("ranks only real brands: copies without one never take a top-N slot", () => {
      const { byBrand } = computeCollectionBreakdown(
        [
          ...brandCopies({ A: 1, B: 1 }),
          copy({ brand: undefined }),
          copy({ brand: undefined }),
          copy({ brand: "  " }),
        ],
        2,
      );
      expect(byBrand).toEqual([
        { label: "A", value: 1 },
        { label: "B", value: 1 },
        { label: UNKNOWN_BUCKET, value: 3 },
      ]);
    });

    it("lists the unknown bucket after Other", () => {
      const { byBrand } = computeCollectionBreakdown(
        [
          ...brandCopies({ A: 5, B: 4, C: 3 }),
          ...Array.from({ length: 9 }, () => copy({})),
        ],
        2,
      );
      expect(byBrand).toEqual([
        { label: "A", value: 5 },
        { label: "B", value: 4 },
        { label: OTHER_BUCKET, value: 3 },
        { label: UNKNOWN_BUCKET, value: 9 },
      ]);
    });

    it("keeps the six biggest brands by default, the chart's series cap", () => {
      const { byBrand } = computeCollectionBreakdown(
        brandCopies({ A: 7, B: 6, C: 5, D: 4, E: 3, F: 2, G: 1 }),
      );
      expect(byBrand).toEqual([
        { label: "A", value: 7 },
        { label: "B", value: 6 },
        { label: "C", value: 5 },
        { label: "D", value: 4 },
        { label: "E", value: 3 },
        { label: "F", value: 2 },
        { label: OTHER_BUCKET, value: 1 },
      ]);
    });
  });
});

src/household/domain/household-join-requ.source:
import { describe, expect, it } from "vitest";
import {
  toHouseholdId,
  toHouseholdJoinRequestId,
  toMemberId,
} from "../../shared-kernel";
import { Household, householdLeaveConsequence } from "./household";
import {
  HOUSEHOLD_JOIN_REQUEST_TTL_MS,
  HouseholdJoinRequest,
  type HouseholdJoinRequestLeave,
} from "./household-join-request";

const id = toHouseholdJoinRequestId("request-1");
const target = toHouseholdId("household-1");
const other = toHouseholdId("household-2");
const ann = toMemberId("ann");
const bob = toMemberId("bob");
const cat = toMemberId("cat");
const t0 = new Date("2026-10-01T00:00:00Z");
const t1 = new Date("2026-10-02T00:00:00Z");
const lapsed = new Date(t0.getTime() + HOUSEHOLD_JOIN_REQUEST_TTL_MS);

const requested = (
  props: { dropped?: boolean; leave?: HouseholdJoinRequestLeave } = {},
): HouseholdJoinRequest => {
  const result = HouseholdJoinRequest.request({
    id,
    householdId: target,
    requesterId: bob,
    adminId: ann,
    linkId: "link-1",
    dropped: props.dropped ?? false,
    leave: props.leave,
    now: t0,
  });
  if (result.isErr) throw result.error;
  result.value.pullEvents();
  return result.value;
};

const householdOf = (
  members: { memberId: typeof ann; role: "admin" | "member" }[],
): Household =>
  Household.rehydrate({
    id: other,
    createdAt: t0,
    members: members.map((m, i) => ({
      ...m,
      joinedAt: new Date(t0.getTime() + i),
    })),
  });

describe("HouseholdJoinRequest.request", () => {
  it("creates a pending request lapsing in 14 days and records HouseholdJoinRequested", () => {
    const result = HouseholdJoinRequest.request({
      id,
      householdId: target,
      requesterId: bob,
      adminId: ann,
      linkId: "link-1",
      dropped: false,
      now: t0,
    });
    if (result.isErr) throw result.error;
    const request = result.value;
    expect(request.status).toBe("pending");
    expect(request.toState().expiresAt).toEqual(lapsed);
    expect(request.toState().leave).toBeUndefined();
    expect(request.pullEvents().map((e) => e.name)).toEqual([
      "HouseholdJoinRequested",
    ]);
  });

  it("records nothing for a dropped request", () => {
    const result = HouseholdJoinRequest.request({
      id,
      householdId: target,
      requesterId: bob,
      adminId: ann,
      linkId: "link-1",
      dropped: true,
      now: t0,
    });
    if (result.isErr) throw result.error;
    expect(result.value.dropped).toBe(true);
    expect(result.value.pullEvents()).toEqual([]);
  });

  it("rejects asking the link's own admin", () => {
    const result = HouseholdJoinRequest.request({
      id,
      householdId: target,
      requesterId: ann,
      adminId: ann,
      linkId: "link-1",
      dropped: false,
      now: t0,
    });
    expect(result.isErr && result.error.code).toBe("SelfJoinRequest");
  });
});

describe("HouseholdJoinRequest answers", () => {
  it("approves a pending request and records the approver", () => {
    const request = requested();
    expect(request.approve(ann, t1).isOk).toBe(true);
    expect(request.status).toBe("approved");
    const [event] = request.pullEvents();
    expect(event).toMatchObject({
      name: "HouseholdJoinRequestApproved",
      requesterId: bob,
      approverId: ann,
    });
  });

  it("refuses to approve a lapsed, dropped or answered request", () => {
    expect(requested().approve(ann, lapsed).isErr).toBe(true);
    expect(requested({ dropped: true }).approve(ann, t1).isErr).toBe(true);
    const declined = requested();
    declined.decline(t1);
    const result = declined.approve(ann, t1);
    expect(result.isErr && result.error.code).toBe("JoinRequestNotPending");
  });

  it("declines silently", () => {
    const request = requested();
    expect(request.decline(t1).isOk).toBe(true);
    expect(request.status).toBe("declined");
    expect(request.pullEvents()).toEqual([]);
  });

  it("stays open to the requester after a decline, and they may withdraw it", () => {
    const request = requested();
    request.decline(t1);
    expect(request.isOpen(t1)).toBe(true);
    expect(request.isActionable(t1)).toBe(false);
    expect(request.withdraw(bob, t1).isOk).toBe(true);
    expect(request.status).toBe("withdrawn");
    expect(request.isOpen(t1)).toBe(false);
  });

  it("lets only the requester withdraw, while open", () => {
    const result = requested().withdraw(cat, t1);
    expect(result.isErr && result.error.code).toBe("NotRequester");
    const late = requested().withdraw(bob, lapsed);
    expect(late.isErr && late.error.code).toBe("JoinRequestNotPending");
  });

  it("voids a pending request for good", () => {
    const request = requested();
    expect(request.void(t1).isOk).toBe(true);
    expect(request.status).toBe("void");
    expect(request.isOpen(t1)).toBe(false);
    expect(request.void(t1).isErr).toBe(true);
  });
});

describe("HouseholdJoinRequest.consentHolds", () => {
  it("holds without consent only while the requester is in no household", () => {
    const request = requested();
    expect(request.consentHolds(null)).toBe(true);
    expect(
      request.consentHolds(householdOf([{ memberId: bob, role: "admin" }])),
    ).toBe(false);
  });

  it("holds while the requester is in the agreed household with the same consequence", () => {
    const request = requested({
      leave: { householdId: other, consequence: "deleted" },
    });
    expect(request.consentHolds(null)).toBe(false);
    expect(
      request.consentHolds(householdOf([{ memberId: bob, role: "admin" }])),
    ).toBe(true);
    // A housemate joined: leaving now hands the household over instead of deleting it.
    expect(
      request.consentHolds(
        householdOf([
          { memberId: bob, role: "admin" },
          { memberId: cat, role: "member" },
        ]),
      ),
    ).toBe(false);
  });
});

describe("householdLeaveConsequence", () => {
  it("deletes for the last member, hands over for a sole admin, else leaves", () => {
    expect(
      householdLeaveConsequence([{ memberId: bob, role: "admin" }], bob),
    ).toBe("deleted");
    expect(
      householdLeaveConsequence(
        [
          { memberId: bob, role: "admin" },
          { memberId: cat, role: "member" },
        ],
        bob,
      ),
    ).toBe("handover");
    expect(
      householdLeaveConsequence(
        [
          { memberId: bob, role: "member" },
          { memberId: cat, role: "admin" },
        ],
        bob,
      ),
    ).toBe("leave");
    expect(
      householdLeaveConsequence(
        [
          { memberId: bob, role: "admin" },
          { memberId: cat, role: "admin" },
        ],
        bob,
      ),
    ).toBe("leave");
  });
});

