import { describe, expect, it } from "vitest";
import {
  INVITE_EMAIL_MAX_LENGTH,
  INVITER_NAME_MAX_LENGTH,
  inviterNameForEmail,
  normalizeInviteEmail,
} from "./invite-email";

const valueOf = (raw: string) => {
  const result = normalizeInviteEmail(raw);
  return result.isOk ? result.value : result.error.code;
};

describe("normalizeInviteEmail", () => {
  it("trims and lowercases a valid address", () => {
    expect(valueOf("  Anna.De-Vries+Puzzles@Example.COM \n")).toBe(
      "anna.de-vries+puzzles@example.com",
    );
  });

  it("accepts the HTML spec's local-part characters and a single-label domain", () => {
    expect(valueOf("a.b!#$%&'*+/=?^_`{|}~-@localhost")).toBe(
      "a.b!#$%&'*+/=?^_`{|}~-@localhost",
    );
    expect(valueOf("x@a-b.c0")).toBe("x@a-b.c0");
    expect(valueOf("x@a")).toBe("x@a");
    expect(valueOf("x@a.b")).toBe("x@a.b");
  });

  it.each([
    [""],
    ["   "],
    ["anna"],
    ["anna@"],
    ["@example.com"],
    ["anna@@example.com"],
    ["anna@example..com"],
    ["anna@-example.com"],
    ["anna@example-.com"],
    ["anna@exa_mple.com"],
    ["an na@example.com"],
    ["anna@example.com\nBcc: x@y.z"],
    ["<anna@example.com>"],
    ["anna@example.com."],
  ])("rejects %j as InvalidEmail", (raw) => {
    expect(valueOf(raw)).toBe("InvalidEmail");
  });

  it("rejects a domain label longer than 63 characters", () => {
    expect(valueOf(`a@${"b".repeat(63)}.com`)).toBe(`a@${"b".repeat(63)}.com`);
    expect(valueOf(`a@${"b".repeat(64)}.com`)).toBe("InvalidEmail");
  });

  it("accepts exactly the maximum length and rejects one more", () => {
    const domain = `${"d".repeat(60)}.${"d".repeat(60)}.${"d".repeat(60)}.com`;
    const local = (n: number) => "l".repeat(n - domain.length - 1);
    const atMax = `${local(INVITE_EMAIL_MAX_LENGTH)}@${domain}`;
    expect(atMax).toHaveLength(254);
    expect(valueOf(atMax)).toBe(atMax);
    expect(valueOf(`l${atMax}`)).toBe("InvalidEmail");
  });

  it("measures the length after trimming", () => {
    const domain = `${"d".repeat(60)}.${"d".repeat(60)}.${"d".repeat(60)}.com`;
    const atMax = `${"l".repeat(INVITE_EMAIL_MAX_LENGTH - domain.length - 1)}@${domain}`;
    expect(valueOf(`   ${atMax}   `)).toBe(atMax);
  });
});

describe("inviterNameForEmail", () => {
  it("keeps an ordinary name as is", () => {
    expect(inviterNameForEmail("Sander Verkuil")).toBe("Sander Verkuil");
  });

  it("returns undefined for a missing, empty or blank name", () => {
    expect(inviterNameForEmail(undefined)).toBeUndefined();
    expect(inviterNameForEmail("")).toBeUndefined();
    expect(inviterNameForEmail(" \r\n\t\u2028 ")).toBeUndefined();
  });

  it("turns line breaks and control characters into single spaces", () => {
    expect(inviterNameForEmail("Anna\r\nBcc: Bob")).toBe("Anna Bcc: Bob");
    expect(inviterNameForEmail("A\u0000B\u0007C\u007fD\u0085E\u009fF")).toBe(
      "A B C D E F",
    );
    expect(inviterNameForEmail("A\u2028B\u2029C")).toBe("A B C");
  });

  it("drops bidi controls and other invisible format characters", () => {
    for (const mark of [
      "\u061C",
      "\u200E",
      "\u200F",
      "\u202A",
      "\u202B",
      "\u202C",
      "\u202D",
      "\u202E",
      "\u2066",
      "\u2067",
      "\u2068",
      "\u2069",
      "\u200B",
      "\uFEFF",
    ]) {
      expect(inviterNameForEmail(`Ann${mark}a${mark}${mark}`)).toBe("Anna");
    }
    expect(inviterNameForEmail("\u202E\u2066")).toBeUndefined();
  });

  it.each([
    ["Anna https://evil.example/login", "Anna"],
    ["Anna hxxp://evil.example", "Anna"],
    ["Anna (https://evil.example)", "Anna"],
    ["Anna www.evil.example", "Anna"],
    ["Anna WWW.EVIL.EXAMPLE", "Anna"],
    ["Anna evil.example", "Anna"],
    ["Anna bit.ly/x1", "Anna"],
    ["Anna evil.example:8080/pay?now=1", "Anna"],
    ["Anna bücher.de", "Anna"],
    ["Anna sub.evil.example.", "Anna"],
    ["Visit evil.example, Anna", "Visit Anna"],
    ["Anna anna@evil.example", "Anna"],
    ["Anna <anna@evil.example>", "Anna"],
    ["Anna evil\u200B.example", "Anna"],
    ["Anna\nevil.example\nde Vries", "Anna de Vries"],
  ])("drops the link-like token in %j", (raw, kept) => {
    expect(inviterNameForEmail(raw)).toBe(kept);
  });

  it.each([
    ["J.R.R. Tolkien"],
    ["Dr.Who"],
    ["St. John"],
    ["Anna B. de Vries"],
    ["a.k.a. Puzzler"],
    ["Pi 3.14"],
    ["@anna"],
    ["Anna & Bob"],
    ["Anna-Marie O'Neil"],
  ])("keeps the ordinary name %j", (raw) => {
    expect(inviterNameForEmail(raw)).toBe(raw);
  });

  // On purpose, on the safe side: a dotted all-lowercase handle has the shape of a host name
  // (any lowercase last part could be a top-level domain), so it is dropped like a link, and a
  // name with nothing else left falls back to the generic label. A capitalised last part is kept.
  it.each([
    ["anna.smith", undefined],
    ["jan.de.vries", undefined],
    ["puzzle.lover", undefined],
    ["Mr Bean mr.bean", "Mr Bean"],
    ["Jan.Jansen", "Jan.Jansen"],
    ["anna.Smith", "anna.Smith"],
  ])("treats the dotted lowercase handle in %j as a host", (raw, kept) => {
    expect(inviterNameForEmail(raw)).toBe(kept);
  });

  it("returns undefined when only links or addresses were given", () => {
    expect(inviterNameForEmail("https://evil.example")).toBeUndefined();
    expect(
      inviterNameForEmail("evil.example  www.evil.example"),
    ).toBeUndefined();
    expect(inviterNameForEmail("x@y.z")).toBeUndefined();
  });

  it("collapses whitespace runs and trims", () => {
    expect(inviterNameForEmail("  Anna    de   Vries  ")).toBe("Anna de Vries");
  });

  it("keeps a name of exactly the maximum length", () => {
    const name = "n".repeat(INVITER_NAME_MAX_LENGTH);
    expect(inviterNameForEmail(name)).toBe(name);
  });

  it("cuts a longer name with an ellipsis, at the maximum length", () => {
    const cut = inviterNameForEmail("n".repeat(INVITER_NAME_MAX_LENGTH + 1));
    expect(cut).toBe(`${"n".repeat(INVITER_NAME_MAX_LENGTH - 1)}…`);
    expect(Array.from(cut ?? "")).toHaveLength(INVITER_NAME_MAX_LENGTH);
  });

  it("does not leave a space before the ellipsis", () => {
    const name = `${"n".repeat(INVITER_NAME_MAX_LENGTH - 2)} xyz`;
    expect(inviterNameForEmail(name)).toBe(
      `${"n".repeat(INVITER_NAME_MAX_LENGTH - 2)}…`,
    );
  });

  it("counts characters, not UTF-16 units, and never splits an emoji", () => {
    const name = "🧩".repeat(INVITER_NAME_MAX_LENGTH + 5);
    expect(inviterNameForEmail(name)).toBe(
      `${"🧩".repeat(INVITER_NAME_MAX_LENGTH - 1)}…`,
    );
    const fits = "🧩".repeat(INVITER_NAME_MAX_LENGTH);
    expect(inviterNameForEmail(fits)).toBe(fits);
  });
});

src/solving/domain/solve-duration.spec.t.source:
import { describe, expect, it } from "vitest";
import {
  isPlausibleSolveMinutes,
  MAX_SOLVE_MINUTES,
  SolveDuration,
  typedSolveMinutes,
} from "./solve-duration";

describe("SolveDuration", () => {
  it("accepts a positive number of minutes", () => {
    const result = SolveDuration.ofMinutes(90);
    expect(result.isOk).toBe(true);
    if (result.isOk) expect(result.value.minutes).toBe(90);
  });

  it("rounds a fractional duration to whole minutes", () => {
    const result = SolveDuration.ofMinutes(90.4);
    expect(result.isOk).toBe(true);
    if (result.isOk) expect(result.value.minutes).toBe(90);
  });

  it("rejects a sub-30-second span that would round down to zero", () => {
    // Rounds to 0 before the fix's re-ordering — the positive-minutes invariant must reject it,
    // never store a 0.
    const result = SolveDuration.ofMinutes(0.2);
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("InvalidDuration");
  });

  it("rounds a span at the half-minute boundary up to one minute", () => {
    const result = SolveDuration.ofMinutes(0.6);
    expect(result.isOk).toBe(true);
    if (result.isOk) expect(result.value.minutes).toBe(1);
  });

  it.each([0, -5, Number.NaN, Number.POSITIVE_INFINITY])(
    "rejects %p with InvalidDuration",
    (value) => {
      const result = SolveDuration.ofMinutes(value);
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("InvalidDuration");
    },
  );

  // One solve of Number.MAX_VALUE minutes used to become a definition's public average.
  it("accepts a duration up to ten years and nothing longer", () => {
    expect(MAX_SOLVE_MINUTES).toBe(10 * 365 * 1440);
    expect(SolveDuration.ofMinutes(MAX_SOLVE_MINUTES).isOk).toBe(true);
    for (const minutes of [MAX_SOLVE_MINUTES + 1, 1e300, Number.MAX_VALUE]) {
      const result = SolveDuration.ofMinutes(minutes);
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("InvalidDuration");
    }
  });

  it("derives a duration from a start/end span", () => {
    const start = new Date("2026-06-01T10:00:00Z");
    const end = new Date("2026-06-01T11:30:00Z");
    const result = SolveDuration.between(start, end);
    expect(result.isOk).toBe(true);
    if (result.isOk) expect(result.value.minutes).toBe(90);
  });

  it("rounds a 45-second span up to one minute", () => {
    const start = new Date("2026-06-01T10:00:00Z");
    const end = new Date("2026-06-01T10:00:45Z");
    const result = SolveDuration.between(start, end);
    expect(result.isOk).toBe(true);
    if (result.isOk) expect(result.value.minutes).toBe(1);
  });

  it("rejects a zero-length span", () => {
    const instant = new Date("2026-06-01T10:00:00Z");
    const result = SolveDuration.between(instant, instant);
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("InvalidDuration");
  });

  it("rejects an end before start", () => {
    const start = new Date("2026-06-01T11:00:00Z");
    const end = new Date("2026-06-01T10:00:00Z");
    const result = SolveDuration.between(start, end);
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("InvalidDuration");
  });

  it("rehydrates a stored value via fromState", () => {
    expect(SolveDuration.fromState(42).minutes).toBe(42);
  });

  it("compares by minutes", () => {
    const thirty = SolveDuration.fromState(30);
    expect(thirty.equals(SolveDuration.fromState(30))).toBe(true);
    expect(thirty.equals(SolveDuration.fromState(31))).toBe(false);
  });
});

describe("isPlausibleSolveMinutes", () => {
  it("holds for what a solve can be stored with", () => {
    expect(isPlausibleSolveMinutes(1)).toBe(true);
    expect(isPlausibleSolveMinutes(90)).toBe(true);
    expect(isPlausibleSolveMinutes(MAX_SOLVE_MINUTES)).toBe(true);
  });

  it.each([
    0,
    -5,
    MAX_SOLVE_MINUTES + 1,
    Number.MAX_VALUE,
    Number.NaN,
    Number.POSITIVE_INFINITY,
  ])("refuses %p, whatever a row already holds", (minutes) => {
    expect(isPlausibleSolveMinutes(minutes)).toBe(false);
  });
});

describe("typedSolveMinutes", () => {
  const DAY_MS = 24 * 60 * 60 * 1000;
  const day = Date.UTC(2026, 9, 12);

  it("reads a time the member typed on a same-day solve", () => {
    expect(
      typedSolveMinutes({
        startDate: day,
        endDate: day,
        completionTimeMinutes: 200,
      }),
    ).toBe(200);
  });

  it("reads a time the member typed on a solve spanning several days", () => {
    expect(
      typedSolveMinutes({
        startDate: day,
        endDate: day + 3 * DAY_MS,
        completionTimeMinutes: 600,
      }),
    ).toBe(600);
  });

  it("does not take the one day stored for an untimed same-day solve for a time", () => {
    expect(
      typedSolveMinutes({
        startDate: day,
        endDate: day,
        completionTimeMinutes: 1440,
      }),
    ).toBeUndefined();
  });

  it("does not take a duration derived from the dates for a time", () => {
    expect(
      typedSolveMinutes({
        startDate: day,
        endDate: day + 3 * DAY_MS,
        completionTimeMinutes: 3 * 1440,
      }),
    ).toBeUndefined();
  });

  it("has no time for a solve that stored none", () => {
    expect(
      typedSolveMinutes({ startDate: day, endDate: day + DAY_MS }),
    ).toBeUndefined();
  });

  it("has no time for a year-only or undated solve", () => {
    for (const datePrecision of ["year", "unknown"] as const) {
      expect(
        typedSolveMinutes({
          startDate: day,
          endDate: day,
          completionTimeMinutes: 200,
          datePrecision,
        }),
      ).toBeUndefined();
    }
  });

  it("keeps a stored time on a row without an end date: it has no span to derive from", () => {
    expect(
      typedSolveMinutes({ startDate: day, completionTimeMinutes: 200 }),
    ).toBe(200);
  });

  it("has no time for a stored number no solve can have taken", () => {
    for (const completionTimeMinutes of [
      0,
      -5,
      MAX_SOLVE_MINUTES + 1,
      Number.MAX_VALUE,
      Number.NaN,
      Number.POSITIVE_INFINITY,
    ]) {
      expect(
        typedSolveMinutes({
          startDate: day,
          endDate: day + DAY_MS,
          completionTimeMinutes,
        }),
      ).toBeUndefined();
      expect(
        typedSolveMinutes({ startDate: day, completionTimeMinutes }),
      ).toBeUndefined();
    }
  });
});

