import { beforeEach, describe, expect, it } from "vitest";
import { toExchangeId, toMemberId } from "../../../shared-kernel";
import { PartnerReviewScoresInput } from "../../domain";
import {
  FakeExchangeCompletionPort,
  FixedClock,
  InMemoryPartnerReviewRepository,
  InMemoryReputationProfileRepository,
  RecordingEventPublisher,
  SequentialPartnerReviewIdGenerator,
  SequentialReputationProfileIdGenerator,
} from "../testing";
import { makeSubmitPartnerReview } from "./submit-partner-review";

const alice = toMemberId("alice"); // reviewer
const bob = toMemberId("bob"); // reviewee
const carol = toMemberId("carol"); // outsider
const exchangeId = toExchangeId("ex-1");
const otherExchange = toExchangeId("ex-2");
const NOW = new Date("2026-06-08T10:00:00Z");

const goodScores: PartnerReviewScoresInput = {
  communication: 5,
  packaging: 4,
  condition: 4,
  timeliness: 3,
};

describe("makeSubmitPartnerReview", () => {
  let reviews: InMemoryPartnerReviewRepository;
  let profiles: InMemoryReputationProfileRepository;
  let exchanges: FakeExchangeCompletionPort;
  let events: RecordingEventPublisher;
  let submit: ReturnType<typeof makeSubmitPartnerReview>;

  beforeEach(() => {
    reviews = new InMemoryPartnerReviewRepository();
    profiles = new InMemoryReputationProfileRepository();
    exchanges = new FakeExchangeCompletionPort();
    events = new RecordingEventPublisher();
    submit = makeSubmitPartnerReview({
      reviews,
      profiles,
      exchanges,
      reviewIds: new SequentialPartnerReviewIdGenerator(),
      profileIds: new SequentialReputationProfileIdGenerator(),
      events,
      clock: new FixedClock(NOW),
    });
  });

  const cmd = (over: Partial<Parameters<typeof submit>[0]> = {}) => ({
    exchangeId,
    reviewerId: alice,
    revieweeId: bob,
    rating: 4,
    comment: "Great partner",
    scores: goodScores,
    ...over,
  });

  it("submits a review: saves it, recomputes the reviewee profile, and publishes both events", async () => {
    exchanges.seedCompleted(exchangeId, alice, bob);

    const result = await submit(cmd());

    expect(result.isOk).toBe(true);
    expect(reviews.size()).toBe(1);
    expect(profiles.size()).toBe(1);

    const profile = await profiles.findByMember(bob);
    expect(profile?.reviewCount).toBe(1);
    expect(profile?.averageRating).toBe(4);

    expect(events.names()).toEqual([
      "PartnerReviewSubmitted",
      "ReputationChanged",
    ]);
    const changed = events.published.find(
      (e) => e.name === "ReputationChanged",
    ) as unknown as {
      averageRating: number;
      reviewCount: number;
    };
    expect(changed.averageRating).toBe(4);
    expect(changed.reviewCount).toBe(1);
  });

  it("rejects a self-review and writes nothing", async () => {
    exchanges.seedCompleted(exchangeId, alice, alice);

    const result = await submit(cmd({ revieweeId: alice }));

    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("SelfReview");
    expect(reviews.size()).toBe(0);
    expect(profiles.size()).toBe(0);
    expect(events.published).toHaveLength(0);
  });

  it("rejects when the exchange is not completed (no window)", async () => {
    // exchange not seeded ⇒ not completed
    const result = await submit(cmd());

    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("ExchangeNotCompleted");
    expect(reviews.size()).toBe(0);
    expect(events.published).toHaveLength(0);
  });

  it("rejects a non-participant of the completed exchange", async () => {
    exchanges.seedCompleted(exchangeId, alice, bob);

    // carol was not a party to ex-1
    const result = await submit(cmd({ revieweeId: carol }));

    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("ExchangeNotCompleted");
    expect(reviews.size()).toBe(0);
  });

  it("rejects a duplicate review by the same reviewer for the same exchange", async () => {
    exchanges.seedCompleted(exchangeId, alice, bob);
    expect((await submit(cmd())).isOk).toBe(true);

    const second = await submit(cmd());
    expect(second.isErr).toBe(true);
    if (second.isErr) expect(second.error.code).toBe("DuplicatePartnerReview");
    expect(reviews.size()).toBe(1); // no second review written
  });

  it.each([0, 6])(
    "rejects an out-of-bounds rating %s without writing",
    async (rating) => {
      exchanges.seedCompleted(exchangeId, alice, bob);

      const result = await submit(cmd({ rating }));
      expect(result.isErr).toBe(true);
      if (result.isErr) expect(result.error.code).toBe("InvalidRating");
      expect(reviews.size()).toBe(0);
      expect(events.published).toHaveLength(0);
    },
  );

  it("accumulates multiple reviews into one reviewee profile and recomputes the average", async () => {
    exchanges
      .seedCompleted(exchangeId, alice, bob)
      .seedCompleted(otherExchange, carol, bob);

    const first = await submit(cmd({ rating: 5 }));
    expect(first.isOk).toBe(true);

    // A different reviewer on a different completed exchange, same reviewee.
    const second = await submit(
      cmd({ exchangeId: otherExchange, reviewerId: carol, rating: 1 }),
    );
    expect(second.isOk).toBe(true);

    expect(reviews.size()).toBe(2);
    expect(profiles.size()).toBe(1); // single profile keyed by reviewee
    const profile = await profiles.findByMember(bob);
    expect(profile?.reviewCount).toBe(2);
    expect(profile?.averageRating).toBe(3); // (5 + 1) / 2
  });

  it("allows the counterparty to review back (distinct reviewer, same exchange)", async () => {
    exchanges.seedCompleted(exchangeId, alice, bob);
    expect((await submit(cmd())).isOk).toBe(true);

    // bob reviews alice for the same exchange: different reviewer ⇒ not a duplicate.
    const back = await submit(cmd({ reviewerId: bob, revieweeId: alice }));
    expect(back.isOk).toBe(true);
    expect(reviews.size()).toBe(2);
    expect((await profiles.findByMember(alice))?.reviewCount).toBe(1);
  });
});

src/insights/personal-stats.spec.ts.source:
import { describe, expect, it } from "vitest";
import {
  computePersonalStats,
  type PersonalStatsInput,
} from "./personal-stats";

const empty: PersonalStatsInput = {
  completions: [],
  copies: [],
  collectionsCount: 0,
  exchanges: [],
  puzzleReviewRatings: [],
  reviewsReceived: [],
  goals: [],
};

describe("computePersonalStats", () => {
  it("returns all-zero stats for empty input (no NaN from divide-by-zero)", () => {
    const stats = computePersonalStats(empty);
    expect(stats).toEqual({
      completionsCount: 0,
      totalSolveMinutes: 0,
      averageSolveMinutes: 0,
      puzzlesOwned: 0,
      distinctDefinitions: 0,
      collectionsCount: 0,
      exchangesCompleted: 0,
      // No puzzle reviews: null, not 0 (distinguishes "no reviews" from a 0 average).
      averageRatingGiven: null,
      averageRatingReceived: 0,
      goalsActive: 0,
      goalsAchieved: 0,
      goalsTotal: 0,
    });
    // Explicitly guard against NaN leaking through any average.
    expect(Number.isNaN(stats.averageSolveMinutes)).toBe(false);
    expect(Number.isNaN(stats.averageRatingReceived)).toBe(false);
  });

  it("counts only completed solves and sums/averages their solve minutes", () => {
    const stats = computePersonalStats({
      ...empty,
      completions: [
        { isCompleted: true, completionTimeMinutes: 60 },
        { isCompleted: true, completionTimeMinutes: 120 },
        // In-progress: excluded from count, total and average.
        { isCompleted: false, completionTimeMinutes: 999 },
      ],
    });
    expect(stats.completionsCount).toBe(2);
    expect(stats.totalSolveMinutes).toBe(180);
    expect(stats.averageSolveMinutes).toBe(90);
  });

  it("averages solve minutes over present samples only, not over all completed rows", () => {
    const stats = computePersonalStats({
      ...empty,
      completions: [
        { isCompleted: true, completionTimeMinutes: 100 },
        { isCompleted: true }, // no time recorded -> not in the denominator
      ],
    });
    expect(stats.completionsCount).toBe(2);
    expect(stats.totalSolveMinutes).toBe(100);
    // 100 / 1 sample, not 100 / 2.
    expect(stats.averageSolveMinutes).toBe(100);
  });

  it("counts owned copies and distinct definitions", () => {
    const stats = computePersonalStats({
      ...empty,
      copies: [
        { puzzleDefinitionKey: "def-a" },
        { puzzleDefinitionKey: "def-a" },
        { puzzleDefinitionKey: "def-b" },
        { puzzleDefinitionKey: undefined },
        { puzzleDefinitionKey: "" },
      ],
    });
    expect(stats.puzzlesOwned).toBe(5);
    // def-a, def-b only; undefined and "" do not count as definitions.
    expect(stats.distinctDefinitions).toBe(2);
  });

  it("counts only completed exchanges", () => {
    const stats = computePersonalStats({
      ...empty,
      // Asymmetric on purpose: 2 completed vs 3 non-completed, so a flipped predicate diverges.
      exchanges: [
        { status: "completed" },
        { status: "completed" },
        { status: "proposed" },
        { status: "disputed" },
        { status: "accepted" },
      ],
    });
    expect(stats.exchangesCompleted).toBe(2);
  });

  it("averages ratings given and received independently", () => {
    const stats = computePersonalStats({
      ...empty,
      puzzleReviewRatings: [4, 2],
      reviewsReceived: [{ rating: 5 }, { rating: 3 }, { rating: 1 }],
    });
    expect(stats.averageRatingGiven).toBe(3); // (4+2)/2
    expect(stats.averageRatingReceived).toBe(3); // (5+3+1)/3
  });

  it("counts active goals and achieved goals (achieved is derived, current >= target)", () => {
    const stats = computePersonalStats({
      ...empty,
      // Asymmetric: 3 achieved vs 2 not, so flipping >= to < changes the count.
      goals: [
        { isActive: true, targetCompletions: 10, currentCompletions: 3 },
        { isActive: true, targetCompletions: 5, currentCompletions: 5 }, // achieved (exactly at target) + active
        { isActive: false, targetCompletions: 2, currentCompletions: 9 }, // achieved, inactive
        { isActive: false, targetCompletions: 4, currentCompletions: 1 },
        { isActive: true, targetCompletions: 3, currentCompletions: 8 }, // achieved + active
      ],
    });
    expect(stats.goalsActive).toBe(3);
    expect(stats.goalsAchieved).toBe(3);
  });

  it("counts every goal in the total, archived ones included, so achieved never exceeds it", () => {
    const stats = computePersonalStats({
      ...empty,
      goals: [
        { isActive: true, targetCompletions: 10, currentCompletions: 3 },
        // Archived (isActive false) after being met: still achieved, so it must be in the total.
        { isActive: false, targetCompletions: 2, currentCompletions: 9 },
        { isActive: false, targetCompletions: 4, currentCompletions: 1 },
      ],
    });
    expect(stats.goalsTotal).toBe(3);
    expect(stats.goalsAchieved).toBe(1);
    expect(stats.goalsActive).toBe(1);
  });

  it("passes through collectionsCount verbatim", () => {
    expect(
      computePersonalStats({ ...empty, collectionsCount: 7 }).collectionsCount,
    ).toBe(7);
  });

  it("counts every precision in the lifetime total but only dated solves in the time averages", () => {
    const stats = computePersonalStats({
      ...empty,
      completions: [
        { isCompleted: true, completionTimeMinutes: 60 },
        { isCompleted: true, completionTimeMinutes: 120, datePrecision: "day" },
        // Defensive: a year/unknown row never carries minutes, but if one did it must not count.
        {
          isCompleted: true,
          completionTimeMinutes: 999,
          datePrecision: "year",
        },
        { isCompleted: true, datePrecision: "unknown" },
      ],
    });
    expect(stats.completionsCount).toBe(4);
    expect(stats.totalSolveMinutes).toBe(180);
    expect(stats.averageSolveMinutes).toBe(90);
  });
});

