import { describe, expect, it } from "vitest";
import { toConnectionOfferId, toMemberId } from "../../shared-kernel";
import { CONNECTION_OFFER_TTL_MS, ConnectionOffer } from "./connection-offer";

const inviter = toMemberId("alice");
const newcomer = toMemberId("bob");
const stranger = toMemberId("carol");
const offerId = toConnectionOfferId("offer-1");
const NOW = new Date("2026-10-18T10:00:00Z");
const LATER = new Date("2026-10-19T10:00:00Z");
const EXPIRES = new Date(NOW.getTime() + CONNECTION_OFFER_TTL_MS);
const JUST_BEFORE_EXPIRY = new Date(EXPIRES.getTime() - 1);

const pending = () => {
  const result = ConnectionOffer.offer({
    id: offerId,
    fromId: inviter,
    toId: newcomer,
    source: "inviteLink",
    now: NOW,
  });
  if (!result.isOk) throw new Error("setup");
  result.value.pullEvents();
  return result.value;
};

describe("ConnectionOffer.offer", () => {
  it("creates a pending offer that expires 30 days later", () => {
    const result = ConnectionOffer.offer({
      id: offerId,
      fromId: inviter,
      toId: newcomer,
      source: "householdLink",
      now: NOW,
    });
    expect(result.isOk).toBe(true);
    if (!result.isOk) return;
    const offer = result.value;
    expect(CONNECTION_OFFER_TTL_MS).toBe(30 * 24 * 60 * 60 * 1000);
    expect(offer.id).toBe(offerId);
    expect(offer.fromId).toBe(inviter);
    expect(offer.toId).toBe(newcomer);
    expect(offer.status).toBe("pending");
    expect(offer.toState()).toEqual({
      id: offerId,
      fromId: inviter,
      toId: newcomer,
      source: "householdLink",
      status: "pending",
      createdAt: NOW,
      expiresAt: EXPIRES,
    });
  });

  it("records ConnectionOffered with the pair and source, drained once", () => {
    const result = ConnectionOffer.offer({
      id: offerId,
      fromId: inviter,
      toId: newcomer,
      source: "inviteLink",
      now: NOW,
    });
    if (!result.isOk) throw new Error("setup");
    const events = result.value.pullEvents();
    expect(events).toHaveLength(1);
    expect(events[0]).toMatchObject({
      name: "ConnectionOffered",
      offerId,
      fromId: inviter,
      toId: newcomer,
      source: "inviteLink",
      occurredAt: NOW,
    });
    expect(result.value.pullEvents()).toHaveLength(0);
  });

  it("rejects an offer to oneself", () => {
    const result = ConnectionOffer.offer({
      id: offerId,
      fromId: inviter,
      toId: inviter,
      source: "inviteLink",
      now: NOW,
    });
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("SelfFollow");
  });
});

describe("ConnectionOffer.isOpen", () => {
  it("is open while pending and before expiry", () => {
    expect(pending().isOpen(JUST_BEFORE_EXPIRY)).toBe(true);
  });

  it("is closed at the expiry instant", () => {
    expect(pending().isOpen(EXPIRES)).toBe(false);
  });

  it("is closed once answered", () => {
    const offer = pending();
    offer.decline(newcomer, LATER);
    expect(offer.isOpen(LATER)).toBe(false);
  });
});

describe.each(["accept", "decline"] as const)("ConnectionOffer.%s", (op) => {
  const expected = op === "accept" ? "accepted" : "declined";

  it(`moves pending → ${expected} and stamps respondedAt, recording no event`, () => {
    const offer = pending();
    const result = offer[op](newcomer, LATER);
    expect(result.isOk).toBe(true);
    expect(offer.status).toBe(expected);
    expect(offer.toState().respondedAt).toBe(LATER);
    expect(offer.pullEvents()).toHaveLength(0);
  });

  it("is allowed just before expiry", () => {
    expect(pending()[op](newcomer, JUST_BEFORE_EXPIRY).isOk).toBe(true);
  });

  it("refuses anyone but the recipient, even the inviter", () => {
    for (const actor of [inviter, stranger]) {
      const offer = pending();
      const result = offer[op](actor, LATER);
      expect(result.isErr).toBe(true);
      if (result.isErr) {
        expect(result.error.code).toBe("NotConnectionOfferRecipient");
      }
      expect(offer.status).toBe("pending");
    }
  });

  it("refuses an offer that is no longer pending", () => {
    const offer = pending();
    offer.accept(newcomer, LATER);
    const result = offer[op](newcomer, LATER);
    expect(result.isErr).toBe(true);
    if (result.isErr) {
      expect(result.error.code).toBe("ConnectionOfferNotPending");
    }
    expect(offer.status).toBe("accepted");
  });

  it("refuses a pending offer at or past its expiry", () => {
    const offer = pending();
    const result = offer[op](newcomer, EXPIRES);
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("ConnectionOfferExpired");
    expect(offer.status).toBe("pending");
    expect(offer.toState().respondedAt).toBeUndefined();
  });
});

describe("ConnectionOffer.expire", () => {
  it("expires a pending offer at its expiry instant", () => {
    const offer = pending();
    expect(offer.expire(EXPIRES).isOk).toBe(true);
    expect(offer.status).toBe("expired");
    expect(offer.toState().respondedAt).toBeUndefined();
  });

  it("refuses to expire before the expiry instant", () => {
    const offer = pending();
    const result = offer.expire(JUST_BEFORE_EXPIRY);
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("ConnectionOfferNotDue");
    expect(offer.status).toBe("pending");
  });

  it("leaves an answered offer alone", () => {
    const offer = pending();
    offer.decline(newcomer, LATER);
    const result = offer.expire(EXPIRES);
    expect(result.isErr).toBe(true);
    if (result.isErr) {
      expect(result.error.code).toBe("ConnectionOfferNotPending");
    }
    expect(offer.status).toBe("declined");
  });
});

describe("ConnectionOffer.rehydrate", () => {
  it("round-trips its state", () => {
    const state = pending().toState();
    expect(ConnectionOffer.rehydrate(state).toState()).toBe(state);
  });
});

src/catalog/domain/catalog-category.spec.source:
import { describe, expect, it } from "vitest";
import { DomainEvent, toCatalogCategoryId } from "../../shared-kernel";
import {
  CatalogCategory,
  CreateCatalogCategoryProps,
  isValidSortOrder,
  LocalizedText,
} from "./catalog-category";
import {
  CatalogCategoryActiveChanged,
  CatalogCategoryReordered,
} from "./events";

const id = toCatalogCategoryId("cc1");
const NOW = new Date("2026-06-08T10:00:00Z");
const LATER = new Date("2026-06-09T10:00:00Z");
const name: LocalizedText = { en: "Landscapes", nl: "Landschappen" };

const names = (events: readonly DomainEvent[]): string[] =>
  events.map((e) => e.name);

const create = (
  overrides: Partial<CreateCatalogCategoryProps> = {},
): CatalogCategory => {
  const r = CatalogCategory.create({
    id,
    name,
    sortOrder: 0,
    now: NOW,
    ...overrides,
  });
  if (!r.isOk) throw new Error(`setup failed: ${r.error.message}`);
  return r.value;
};

describe("CatalogCategory.create", () => {
  it("starts active and records CatalogCategoryCreated", () => {
    const category = create();
    expect(category.isActive).toBe(true);
    expect(category.sortOrder).toBe(0);
    expect(names(category.pullEvents())).toEqual(["CatalogCategoryCreated"]);
  });

  it.each<[string, LocalizedText]>([
    ["blank en", { en: "  ", nl: "Landschappen" }],
    ["blank nl", { en: "Landscapes", nl: "" }],
  ])("rejects an incomplete name (%s)", (_label, badName) => {
    const r = CatalogCategory.create({
      id,
      name: badName,
      sortOrder: 0,
      now: NOW,
    });
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("EmptyCategoryName");
  });
});

describe("update", () => {
  it("patches color and localized text, recording CatalogCategoryUpdated", () => {
    const category = create();
    category.pullEvents();
    const r = category.update({ color: "#ff0000" }, LATER);
    expect(r.isOk).toBe(true);
    expect(category.toState().color).toBe("#ff0000");
    expect(names(category.pullEvents())).toEqual(["CatalogCategoryUpdated"]);
  });

  // The `??` coalescing keeps a provided value; setting name + description (the latter from an
  // unset baseline) distinguishes `??` from `&&` (which would drop them).
  it("applies a complete replacement name and a new description", () => {
    const category = create(); // no description initially
    const r = category.update(
      {
        name: { en: "Mountains", nl: "Bergen" },
        description: { en: "Peaks", nl: "Toppen" },
      },
      LATER,
    );
    expect(r.isOk).toBe(true);
    expect(category.toState().name).toEqual({ en: "Mountains", nl: "Bergen" });
    expect(category.toState().description).toEqual({
      en: "Peaks",
      nl: "Toppen",
    });
  });

  it("leaves the name unchanged when the patch omits it", () => {
    const category = create();
    category.update({ color: "#123456" }, LATER);
    expect(category.toState().name).toEqual(name);
  });

  it("rejects a replacement name that is incomplete", () => {
    const category = create();
    const r = category.update({ name: { en: "Only EN", nl: " " } }, LATER);
    expect(r.isErr).toBe(true);
    if (r.isErr) expect(r.error.code).toBe("EmptyCategoryName");
  });
});

describe("activate / deactivate (soft, idempotent)", () => {
  it("deactivates softly, emitting CatalogCategoryActiveChanged(false)", () => {
    const category = create();
    category.pullEvents();
    category.deactivate(LATER);
    expect(category.isActive).toBe(false);
    const events = category.pullEvents();
    expect(names(events)).toEqual(["CatalogCategoryActiveChanged"]);
    expect((events[0] as CatalogCategoryActiveChanged).isActive).toBe(false);
  });

  it("is idempotent: deactivating an inactive node emits nothing", () => {
    const category = create();
    category.deactivate(LATER);
    category.pullEvents();
    category.deactivate(LATER);
    expect(category.pullEvents()).toHaveLength(0);
  });

  it("can be reactivated", () => {
    const category = create();
    category.deactivate(NOW);
    category.pullEvents();
    category.activate(LATER);
    expect(category.isActive).toBe(true);
    expect(names(category.pullEvents())).toEqual([
      "CatalogCategoryActiveChanged",
    ]);
  });
});

describe("reorder (stable, idempotent)", () => {
  it("moves to a new position, emitting CatalogCategoryReordered", () => {
    const category = create({ sortOrder: 1 });
    category.pullEvents();
    category.reorder(5, LATER);
    expect(category.sortOrder).toBe(5);
    const events = category.pullEvents();
    expect(names(events)).toEqual(["CatalogCategoryReordered"]);
    expect((events[0] as CatalogCategoryReordered).sortOrder).toBe(5);
  });

  it("is idempotent: reordering to the same position emits nothing", () => {
    const category = create({ sortOrder: 3 });
    category.pullEvents();
    category.reorder(3, LATER);
    expect(category.pullEvents()).toHaveLength(0);
  });
});

describe("rehydrate / toState round-trip", () => {
  it("rehydrates without re-recording events", () => {
    const state = create({ color: "#abc", sortOrder: 7 }).toState();
    const restored = CatalogCategory.rehydrate(state);
    expect(restored.pullEvents()).toHaveLength(0);
    expect(restored.toState()).toEqual(state);
  });
});

describe("isValidSortOrder", () => {
  it.each([0, 3, -2, 1.5])("takes %p", (n) => {
    expect(isValidSortOrder(n)).toBe(true);
  });

  it.each([Number.NaN, Number.POSITIVE_INFINITY, 1e300, -1e300])(
    "refuses %p",
    (n) => {
      expect(isValidSortOrder(n)).toBe(false);
    },
  );
});

src/solving/domain/goal-progress.spec.ts.source:
import { describe, expect, it } from "vitest";
import { DatePrecision } from "./date-precision";
import {
  countsTowardGoal,
  countTowardGoal,
  goalCountingWindow,
  GoalWindow,
} from "./goal-progress";

const at = (iso: string) => new Date(iso);
const solve = (iso: string, datePrecision: DatePrecision = "day") => ({
  endDate: at(iso),
  datePrecision,
});

describe("goalCountingWindow", () => {
  it("starts at the UTC day of the start date and ends after the UTC day of the target date", () => {
    const window = goalCountingWindow({
      startDate: at("2026-01-01T15:45:00Z"),
      createdAt: at("2026-10-30T09:00:00Z"),
      targetDate: at("2026-12-31T08:00:00Z"),
    });
    expect(window.from.toISOString()).toBe("2026-01-01T00:00:00.000Z");
    expect(window.toExclusive?.toISOString()).toBe("2027-01-01T00:00:00.000Z");
  });

  it("falls back to the UTC day the goal was created when it has no start date", () => {
    const window = goalCountingWindow({
      createdAt: at("2026-10-30T23:30:00Z"),
      targetDate: at("2026-11-01T00:00:00Z"),
    });
    expect(window.from.toISOString()).toBe("2026-10-30T00:00:00.000Z");
    expect(window.toExclusive?.toISOString()).toBe("2026-11-02T00:00:00.000Z");
  });

  it("is open-ended when the goal has no target date", () => {
    const window = goalCountingWindow({
      createdAt: at("2026-10-30T09:00:00Z"),
    });
    expect(window.from.toISOString()).toBe("2026-10-30T00:00:00.000Z");
    expect(window.toExclusive).toBeUndefined();
  });
});

describe("countsTowardGoal", () => {
  // The whole of 2026, as a goal from 1 January to 31 December.
  const year2026: GoalWindow = {
    from: at("2026-01-01T00:00:00Z"),
    toExclusive: at("2027-01-01T00:00:00Z"),
  };
  // A goal created on 30 October 2026 with no end date.
  const openEnded: GoalWindow = { from: at("2026-10-30T00:00:00Z") };

  describe("a solve dated to the day", () => {
    it("counts on the first instant of the first day", () => {
      expect(countsTowardGoal(solve("2026-01-01T00:00:00Z"), year2026)).toBe(
        true,
      );
    });

    it("does not count the instant before the window opens", () => {
      expect(
        countsTowardGoal(solve("2025-12-31T23:59:59.999Z"), year2026),
      ).toBe(false);
    });

    it("counts on the last instant of the last day", () => {
      expect(
        countsTowardGoal(solve("2026-12-31T23:59:59.999Z"), year2026),
      ).toBe(true);
    });

    it("does not count from the day after the target date", () => {
      expect(countsTowardGoal(solve("2027-01-01T00:00:00Z"), year2026)).toBe(
        false,
      );
    });

    it("counts any later solve when the goal is open-ended", () => {
      expect(countsTowardGoal(solve("2040-06-01T00:00:00Z"), openEnded)).toBe(
        true,
      );
      expect(
        countsTowardGoal(solve("2026-10-29T23:59:59.999Z"), openEnded),
      ).toBe(false);
    });
  });

  describe("a solve dated only to a year", () => {
    it("counts when its year overlaps the window", () => {
      expect(
        countsTowardGoal(solve("2026-07-01T12:00:00Z", "year"), year2026),
      ).toBe(true);
    });

    it("counts when the window covers only the last day of its year", () => {
      const lastDay: GoalWindow = {
        from: at("2025-12-31T00:00:00Z"),
        toExclusive: at("2026-02-01T00:00:00Z"),
      };
      expect(
        countsTowardGoal(solve("2025-07-01T12:00:00Z", "year"), lastDay),
      ).toBe(true);
    });

    it("counts when the window covers only the first day of its year", () => {
      const firstDay: GoalWindow = {
        from: at("2025-06-01T00:00:00Z"),
        toExclusive: at("2026-01-02T00:00:00Z"),
      };
      expect(
        countsTowardGoal(solve("2026-07-01T12:00:00Z", "year"), firstDay),
      ).toBe(true);
    });

    it("does not count a year that ends as the window opens", () => {
      expect(
        countsTowardGoal(solve("2025-07-01T12:00:00Z", "year"), year2026),
      ).toBe(false);
    });

    it("does not count a year that starts as the window closes", () => {
      expect(
        countsTowardGoal(solve("2027-07-01T12:00:00Z", "year"), year2026),
      ).toBe(false);
    });

    it("counts the year itself even when its sentinel lies before an open-ended window", () => {
      // A 2026 import is stored on 1 July; a goal opened in October still overlaps 2026.
      expect(
        countsTowardGoal(solve("2026-07-01T12:00:00Z", "year"), openEnded),
      ).toBe(true);
      expect(
        countsTowardGoal(solve("2025-07-01T12:00:00Z", "year"), openEnded),
      ).toBe(false);
    });
  });

  describe("an undated solve", () => {
    it("never counts, even when its stored instant lies in the window", () => {
      expect(
        countsTowardGoal(solve("2026-06-01T00:00:00Z", "unknown"), year2026),
      ).toBe(false);
    });
  });
});

describe("countTowardGoal", () => {
  it("counts only the solves inside the window", () => {
    const window: GoalWindow = {
      from: at("2026-10-30T00:00:00Z"),
      toExclusive: at("2027-01-01T00:00:00Z"),
    };
    const solves = [
      solve("2024-03-01T10:00:00Z"),
      solve("2026-10-29T22:00:00Z"),
      solve("2026-10-30T08:00:00Z"),
      solve("2026-11-15T00:00:00Z"),
      solve("2026-07-01T12:00:00Z", "year"),
      solve("2026-11-01T00:00:00Z", "unknown"),
    ];
    expect(countTowardGoal(solves, window)).toBe(3);
  });

  it("is zero without solves", () => {
    expect(countTowardGoal([], { from: at("2026-01-01T00:00:00Z") })).toBe(0);
  });
});

