import { beforeEach, describe, expect, it } from "vitest";
import { toExchangeId, toMemberId, toThreadId } from "../../../shared-kernel";
import { Thread } from "../../domain";
import { FixedClock, InMemoryThreadRepository } from "../testing";
import { makeMarkThreadRead } from "./mark-thread-read";

const alice = toMemberId("alice");
const bob = toMemberId("bob");
const carol = toMemberId("carol"); // outsider
const exchangeId = toExchangeId("ex-1");
const threadId = toThreadId("thread-1");
const missingThread = toThreadId("thread-404");
const NOW = new Date("2026-06-08T10:00:00Z");

describe("makeMarkThreadRead", () => {
  let threads: InMemoryThreadRepository;
  let clock: FixedClock;
  let mark: ReturnType<typeof makeMarkThreadRead>;

  beforeEach(async () => {
    threads = new InMemoryThreadRepository();
    clock = new FixedClock(NOW);
    mark = makeMarkThreadRead({ threads, clock });
    await threads.save(
      Thread.openForExchange(threadId, exchangeId, [alice, bob]),
    );
  });

  it("records only the caller's read receipt at the clock's now", async () => {
    const result = await mark({ threadId, memberId: alice });

    expect(result.isOk).toBe(true);
    const reloaded = await threads.findById(threadId);
    expect(reloaded?.lastReadAt(alice)).toEqual(NOW);
    expect(reloaded?.lastReadAt(bob)).toBeNull();
  });

  it("rejects ThreadNotFound", async () => {
    const result = await mark({ threadId: missingThread, memberId: alice });
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("ThreadNotFound");
  });

  it("rejects a non-participant", async () => {
    const result = await mark({ threadId, memberId: carol });
    expect(result.isErr).toBe(true);
    if (result.isErr) expect(result.error.code).toBe("NotParticipant");
    const reloaded = await threads.findById(threadId);
    expect(reloaded?.readReceipts).toHaveLength(0);
  });
});

src/sharing/domain/exchange-route.spec.t.source:
import { describe, expect, it } from "vitest";
import { exchangeAllowedVia, mayExchangeVia } from "./exchange-route";

describe("mayExchangeVia", () => {
  it("refuses when there is no route", () => {
    expect(mayExchangeVia([])).toBe(false);
  });

  it("refuses a ViewOnly circle seat on its own", () => {
    expect(mayExchangeVia([{ kind: "circle", level: "ViewOnly" }])).toBe(false);
  });

  it("allows an Exchange or Admin circle seat", () => {
    expect(mayExchangeVia([{ kind: "circle", level: "Exchange" }])).toBe(true);
    expect(mayExchangeVia([{ kind: "circle", level: "Admin" }])).toBe(true);
  });

  it("allows when another circle grants Exchange", () => {
    expect(
      mayExchangeVia([
        { kind: "circle", level: "ViewOnly" },
        { kind: "circle", level: "Exchange" },
      ]),
    ).toBe(true);
  });

  it.each(["public", "household", "mutualFollow"] as const)(
    "a %s route allows despite a ViewOnly circle seat",
    (kind) => {
      expect(
        mayExchangeVia([{ kind: "circle", level: "ViewOnly" }, { kind }]),
      ).toBe(true);
    },
  );
});

describe("exchangeAllowedVia", () => {
  it("is null when nothing allows it", () => {
    expect(exchangeAllowedVia([])).toBeNull();
    expect(
      exchangeAllowedVia([{ kind: "circle", level: "ViewOnly" }]),
    ).toBeNull();
  });

  it("is circle when only Exchange or Admin seats allow it", () => {
    expect(
      exchangeAllowedVia([
        { kind: "circle", level: "ViewOnly" },
        { kind: "circle", level: "Admin" },
      ]),
    ).toBe("circle");
  });

  it.each(["public", "household", "mutualFollow"] as const)(
    "is direct when a %s route exists, circle seats or not",
    (kind) => {
      expect(exchangeAllowedVia([{ kind }])).toBe("direct");
      expect(
        exchangeAllowedVia([{ kind: "circle", level: "Exchange" }, { kind }]),
      ).toBe("direct");
    },
  );
});

