import { describe, expect, it } from "vitest";
import { toMemberId, toMessageId } from "../../shared-kernel";
import { Message, MessageState } from "./message";

const state: MessageState = {
  id: toMessageId("msg-1"),
  authorId: toMemberId("alice"),
  kind: "text",
  body: "Hello there",
  sentAt: new Date("2026-06-08T10:00:00Z"),
};

describe("Message", () => {
  it("exposes its state through getters and round-trips via fromState/toState", () => {
    const msg = Message.fromState(state);
    expect(msg.id).toBe(state.id);
    expect(msg.authorId).toBe(state.authorId);
    expect(msg.kind).toBe("text");
    expect(msg.body).toBe("Hello there");
    expect(msg.sentAt).toBe(state.sentAt);
    expect(msg.toState()).toEqual(state);
    expect(msg.attachmentRef).toBeUndefined();
  });

  it("exposes a media message's attachment reference and caption", () => {
    const media: MessageState = {
      ...state,
      kind: "location",
      body: "",
      attachmentRef: "att-1",
    };
    const msg = Message.fromState(media);
    expect(msg.kind).toBe("location");
    expect(msg.body).toBe("");
    expect(msg.attachmentRef).toBe("att-1");
    expect(msg.toState()).toEqual(media);
  });
});

src/sharing/domain/visibility-scope.spec.source:
import { describe, expect, it } from "vitest";
import {
  isPubliclyViewable,
  permitsTransaction,
  TransactionKind,
  VisibilityScope,
} from "./visibility-scope";

describe("isPubliclyViewable", () => {
  it.each<[VisibilityScope, boolean]>([
    ["private", false],
    ["friendCircle", false],
    ["visible", true],
    ["lendable", true],
    ["swappable", true],
    ["tradeable", true],
  ])("%s -> %s", (scope, expected) => {
    expect(isPubliclyViewable(scope)).toBe(expected);
  });
});

describe("permitsTransaction", () => {
  const KINDS: TransactionKind[] = ["lend", "swap", "trade"];

  it.each<[VisibilityScope, TransactionKind]>([
    ["lendable", "lend"],
    ["swappable", "swap"],
    ["tradeable", "trade"],
  ])("%s permits exactly %s", (scope, allowed) => {
    expect(permitsTransaction(scope, allowed)).toBe(true);
    for (const other of KINDS.filter((k) => k !== allowed)) {
      expect(permitsTransaction(scope, other)).toBe(false);
    }
  });

  it.each<VisibilityScope>(["private", "friendCircle", "visible"])(
    "%s permits no transaction",
    (scope) => {
      for (const kind of KINDS)
        expect(permitsTransaction(scope, kind)).toBe(false);
    },
  );
});

